# 預設 0，比較樣本 Samples 預設 'Entire frame'，自訂樣本位置 CustomSamples 預設 []（空白；選「自訂」時空白是錯誤，R2025a 的實際行為）
DEFAULT_ERRRATE = {"rd": "0", "cd": "0", "samples": "Entire frame", "custom": ""}
DEFAULT_GFSK = {"if": "1.77778M", "bw": "500k", "iq_order": "IQ", "taps": 33}
DEFAULT_CSV = {"shift": "0", "scale": "1", "fs": "", "fmt": "AUTO", "dk": 2,
               "dthr": 8.0, "dmin": 20.0, "merge": True, "time_offset": False}


def log(msg: str) -> None:
    """把訊息附加到 ~/signal_viewer.log（失敗就算了，不影響主程式）。"""
    try:
        with open(LOG_PATH, "a", encoding="utf-8") as f:
            f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + str(msg).rstrip() + "\n")
    except Exception:
        pass


def record_action(desc: str) -> None:
    """保留最近 25 筆動作記錄（診斷視窗用）。"""
    ACTION_HISTORY.append(time.strftime("%H:%M:%S ") + desc)


def in_ipython() -> bool:
    """是否在 IPython / Spyder kernel 裡執行。"""
    if "ipykernel" in sys.modules:
        return True
    gi = getattr(builtins, "get_ipython", None)
    try:
        return gi is not None and gi() is not None
    except Exception:
        return False


# ---------------------------------------------------------------------------
# 1. 解析工具（寬鬆、失敗時回傳 None，不丟例外）
# ---------------------------------------------------------------------------
_NUM_RE = re.compile(r"^(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$")
_SI_PREFIX = {"p": 1e-12, "n": 1e-9, "u": 1e-6, "µ": 1e-6, "μ": 1e-6,
              "m": 1e-3, "k": 1e3, "K": 1e3, "M": 1e6, "G": 1e9}
_TIME_UNIT = {"s": 1.0, "sec": 1.0, "ms": 1e-3, "us": 1e-6, "µs": 1e-6, "μs": 1e-6,
              "ns": 1e-9, "ps": 1e-12}
_NUMTEXT = r"[+-]?[\d.,]*\d[\d.,]*(?:[eE][+-]?\d+)?"


def parse_number(s) -> Optional[float]:
    """寬鬆的數字解析：NFKC 正規化、去空白、小數逗號、千分位、0x / 0b 前綴。"""
    if s is None or isinstance(s, bool):
        return None
    if isinstance(s, (int, float, np.integer, np.floating)):
        return float(s)
    t = unicodedata.normalize("NFKC", str(s))
    t = re.sub(r"\s+", "", t)
    if not t:
        return None
    sign = 1.0
    if t[0] in "+-":
        sign = -1.0 if t[0] == "-" else 1.0
        t = t[1:]
    if not t:
        return None
    if t.lower() in ("nan", "inf", "infinity"):     # 和整欄快速路徑（np.asarray float）、MATLAB readmatrix 一致：NaN／Inf 是值，不是壞格子
        return sign * float(t)
    if re.fullmatch(r"0[xX][0-9a-fA-F]+", t):
        return sign * int(t, 16)
    if re.fullmatch(r"0[bB][01]+", t):
        return sign * int(t, 2)
    if "," in t:
        parts = t.split(",")
        if len(parts) == 2 and "." not in t and not re.fullmatch(r"\d{3}", parts[1]):
            t = parts[0] + "." + parts[1]       # 小數逗號：1,5 → 1.5
        else:
            t = t.replace(",", "")              # 千分位：1,000 → 1000
    if not _NUM_RE.match(t):
        return None
    try:
        return sign * float(t)
    except ValueError:
        return None


def parse_si(s) -> Optional[float]:
    """解析 64M、64 MHz、64Msps、1.5G、500k、64e6 這類寫法。"""
    if s is None or isinstance(s, bool):
        return None
    if isinstance(s, (int, float, np.integer, np.floating)):
        return float(s)
    t = unicodedata.normalize("NFKC", str(s)).strip()
    if not t:
        return None
    low = t.lower()
    for suf in ("sa/s", "s/s", "sps", "hz"):     # 去掉結尾單位
        if low.endswith(suf):
            t = t[: len(t) - len(suf)]
            break
    t = t.strip()
    m = re.fullmatch(r"(" + _NUMTEXT + r")\s*([pnuµμmkKMG])?", t)
    if not m:
        return None
    v = parse_number(m.group(1))
    if v is None:
        return None
    p = m.group(2)
    return v * _SI_PREFIX[p] if p else v


def fmt_si(v: float, unit: str = "") -> str:
    """輸出成 64M、1.77778MHz 這種格式（6 位有效數字）。"""
    if v is None or not math.isfinite(v):
        return str(v)
    if v == 0:
        return "0" + unit
    a = abs(v)
    for scale, p in ((1e9, "G"), (1e6, "M"), (1e3, "k"), (1.0, ""),
                     (1e-3, "m"), (1e-6, "u"), (1e-9, "n"), (1e-12, "p")):
        if a >= scale * 0.9999995:
            return f"{v / scale:.6g}{p}{unit}"
    return f"{v:.6g}{unit}"


def parse_time_s(s) -> Optional[float]:
    """"93.391254 ms"、"-59.656 us"、"16 ns"、"0 s" → 秒。沒寫單位就當秒。"""
    if s is None or isinstance(s, bool):
        return None
    if isinstance(s, (int, float, np.integer, np.floating)):
        return float(s)
    t = unicodedata.normalize("NFKC", str(s)).strip()
    m = re.fullmatch(r"(" + _NUMTEXT + r")\s*(ps|ns|us|µs|μs|ms|sec|s)?", t, re.IGNORECASE)
    if not m:
        return None
    v = parse_number(m.group(1))
    if v is None:
        return None
    u = (m.group(2) or "s").lower()
    return v * _TIME_UNIT.get(u, 1.0)


_SPEC_INF_RE = re.compile(r"[+-]?inf(?:inity)?", re.IGNORECASE)
_SPEC_NAN_RE = re.compile(r"[+-]?nan", re.IGNORECASE)
_SPEC_NUM_RE = re.compile(r"(" + _NUMTEXT + r")\s*([pnuµμmkKMG])?")
_SI_EXP10 = {"p": -12, "n": -9, "u": -6, "µ": -6, "μ": -6, "m": -3, "k": 3, "K": 3, "M": 6, "G": 9}   # _SI_PREFIX 的 10 的次方
_SPEC_UNIT_WORDS = ("sa/s", "s/s", "sps", "hz")      # parse_si 略過的結尾單位字（照這個順序比，sps 不會被當成 s）
_SPEC_TIME_WORDS = ("sec", "s")                      # 時間欄位另外略過的秒


def parse_spec_number(s, inf: bool = False, nan: bool = False, time: bool = False,
                      units: Optional[Sequence[str]] = None) -> Optional[float]:
    """頻譜視窗的數字欄位一律用這一條規則（使用者 2026-10-25 決定；取代頻譜遮罩欄位原本照 MATLAB 工具列的寬鬆解析）：
    DSV 的 SI 字首解析（parse_si 的寫法）——2k＝2000、1.5M＝1.5e6、500m＝0.5、4p、3n、20u／20µ、5K、1G（字首大小寫有分：m 是千分之一、
    M 是百萬，每個欄位都一樣）、結尾的單位字照 parse_si 略過（Hz、sps、S/s、Sa/s；大小寫不拘）；time＝用秒的時間欄位（頻譜圖的時間解析度、
    時間跨度）另外略過結尾的 s／sec（1ms、20us、1 s、1msec；1Ms 是 100 萬秒，和 1M 一樣）。字首用十進位換算（1.023k 和 1.023e3 一樣是 1023，
    直接乘 1e3 會差 1 ulp、整數欄位就不收了）；數字本身照 parse_number（1,5＝1.5、1,000＝1000）。
    整串都要是數字：不完整或後面有多餘的字（'12abc'、'50abc'、'1..2'、'5 dB'、'0x10'、'0b101'）、數字中間或正負號後面有空白（'1 000'、'- 5'）、
    空白 → None（欄位的錯誤）。
    inf＝這個欄位收 ±Inf（MATLAB 也收、DSV 本來就處理的欄位：遮罩的上限／下限與參考位準、峰值的 Threshold、Min Height 與 Min Distance）：Inf、-Inf、
    inf、INF、+Inf、Infinity（大小寫不拘、前後可以有空白；字中間或正負號後面有空白的 'In f'、'- Inf' 和數字一樣是錯），溢位的 1e999 也算；
    其他欄位 ±Inf → None。nan＝收 NaN（只有遮罩的上限／下限：位準寫 NaN 的那一段不測，MATLAB 實測）；其他欄位 NaN → None。
    向量與矩陣欄位（ACPR 偏移量、色彩範圍、遮罩矩陣）整串先 NFKC（全形的括號、分號、逗號也認得）再切開，每個數字各自照這條規則。
    units＝dB 類欄位自己的單位字（使用者 2026-10-26 決定）：數字後面可以寫這個單位（空白可有可無、大小寫不拘：衰減 5 dB、參考位準與遮罩位準
    5 dBr、峰值的 Threshold／Min Height 與色彩範圍寫頻譜的單位 dBm、dB/Hz…；Inf／NaN 後面也可以寫），別的單位字（Hz、sps、別的 dB 單位）
    是錯——給 units 時不再略過 Hz 那些字；() ＝不收任何單位字（線性振幅的 Threshold 這種沒有單位的欄位）。"""
    if s is None or isinstance(s, bool):
        return None
    t = unicodedata.normalize("NFKC", str(s)).strip()
    if units is not None:                                 # dB 類欄位：先拿掉自己的單位字（只拿一次），其他照下面同一套
        for u in sorted((str(u_) for u_ in units if u_), key=len, reverse=True):
            if len(t) > len(u) and t[-len(u):].lower() == u.lower():
                t = t[: len(t) - len(u)].strip()
                break
    if _SPEC_INF_RE.fullmatch(t):
        return (-math.inf if t.startswith("-") else math.inf) if inf else None
    if _SPEC_NAN_RE.fullmatch(t):
        return math.nan if nan else None
    low = t.lower()
    for suf in (() if units is not None else _SPEC_UNIT_WORDS) + (_SPEC_TIME_WORDS if time else ()):
        if low.endswith(suf):
            t = t[: len(t) - len(suf)].strip()
            break
    m = _SPEC_NUM_RE.fullmatch(t)
    v = parse_number(m.group(1)) if m else None
    if v is None:
        return None
    e = _SI_EXP10.get(m.group(2) or "", 0)
    if e and math.isfinite(v):
        v = float(decimal.Decimal(repr(float(v))).scaleb(e))     # repr＝最短可還原的十進位（最多 17 位，scaleb 不會捨入），float() 正確捨入
    if math.isnan(v) or (math.isinf(v) and not inf):
        return None
    return float(v)


def join_unit_tokens(parts: Sequence[str]) -> List[str]:
    """dB 類的向量／矩陣欄位（色彩範圍、遮罩的上限／下限）切開後的字：只有單位字的那一個（沒有數字、不是 Inf／NaN、不是正負號或小數點開頭）
    接回前一個數字（'-80 dB, 20 dB' → '-80 dB'、'20 dB'；'-10 dBr' 是一個數字，不是兩欄），單位字照純量欄位一樣可以和數字隔一個空白；
    接不上的（第一個就是單位字）照原樣留著，交給數字解析判錯。"""
    out: List[str] = []
    for p in parts:
        word = (not re.search(r"\d", p) and not p.startswith(("+", "-", "."))
                and not _SPEC_INF_RE.fullmatch(p) and not _SPEC_NAN_RE.fullmatch(p))
        if word and out:
            out[-1] = out[-1] + " " + p
        else:
            out.append(p)
    return out


def parse_token(tok, fmt: str = "DEC") -> Optional[float]:
    """依讀取格式解析一個 token：DEC（含 0x/0b）、HEX（unsigned）、HEXS（signed 二補數）。"""
    if tok is None:
        return None
    t = unicodedata.normalize("NFKC", str(tok)).strip()
    if not t:
        return None
    f = (fmt or "DEC").upper()
    if f in ("DEC", "AUTO"):
        return parse_number(t)
    neg = False
    if t[0] in "+-":
        neg = t[0] == "-"
        t = t[1:]
    if t[:2].lower() == "0x":
        t = t[2:]
    if not t or not re.fullmatch(r"[0-9a-fA-F]+", t):
        return None
    v = int(t, 16)
    if f == "HEXS":
        bits = len(t) * 4                 # 位元數 = 字元數 × 4
        if v >= 1 << (bits - 1):
            v -= 1 << bits
    elif f != "HEX":
        return None
    return float(-v if neg else v)


# ---------------------------------------------------------------------------
# 2. 資料層：文字檔、CSV、快取、掃描資料夾
# ---------------------------------------------------------------------------
_COMMENT_PREFIXES = ("#", "%", "//")
_TOKEN_SPLIT = re.compile(r"[\s,;]+")
_HEX_RE = re.compile(r"^[0-9a-fA-F]+$")


def system_text_encodings() -> List[str]:
    """系統字碼頁的候選（zh-TW Windows＝cp950），依序試、去重：locale.getpreferredencoding(False)（Python UTF-8 模式
    PYTHONUTF8=1／-X utf8 之下是 utf-8）、locale.getencoding()（3.11 起；UTF-8 模式下也回真正的 ANSI 字碼頁）、Windows 的 GetACP()。
    0.9.13 W7（verify_win_0912.md）：以前只看 getpreferredencoding，UTF-8 模式下 Big5 的 CSV 讀成亂碼、還原時「CSV 沒有欄位」。"""
    import locale
    cands: List[str] = []
    try:
        cands.append(locale.getpreferredencoding(False) or "")
    except Exception:
        pass
    ge = getattr(locale, "getencoding", None)
    if ge is not None:
        try:
            cands.append(ge() or "")
        except Exception:
            pass
    if sys.platform == "win32":
        try:
            import ctypes
            cands.append(f"cp{int(ctypes.windll.kernel32.GetACP())}")
        except Exception:
            pass
    out: List[str] = []
    for c in cands:
        c = str(c).strip()
        if c and c.lower().replace("_", "-") not in [o.lower().replace("_", "-") for o in out]:
            out.append(c)
    return out or ["utf-8"]


def read_text_any(path: str, limit: Optional[int] = None) -> str:
    """讀文字檔：先用 utf-8-sig（嚴格），失敗再用系統字碼頁（zh-TW Windows 的 cp950；system_text_encodings 的候選依序試），最後 utf-8 取代。
    limit：只讀前面這麼多 bytes（取檔頭用），並丟掉最後一個不完整的行，避免切到多位元組字元。"""
    with open(path, "rb") as f:
        raw = f.read() if limit is None else f.read(limit)
    if limit is not None and len(raw) >= limit and b"\n" in raw:
        raw = raw[: raw.rfind(b"\n") + 1]
    cuts = (0, 1, 2, 3) if (limit is not None and len(raw) >= limit) else (0,)   # 沒有換行可切時：切到半個字最多丟 3 bytes
    for enc in ["utf-8-sig"] + system_text_encodings():
        for cut in cuts:
            try:
                return (raw[: len(raw) - cut] if cut else raw).decode(enc)
            except (UnicodeDecodeError, LookupError):
                continue
    return raw.decode("utf-8", "replace")


def read_text_tokens(path: str) -> List[str]:
    """一行一個值：跳過空行與註解行，每行只取第一個 token。"""
    toks: List[str] = []
    with io.StringIO(read_text_any(path), newline=None) as f:   # universal newlines，和原本 open() 一樣
        for line in f:
            s = line.strip()
            if not s or s.startswith(_COMMENT_PREFIXES):
                continue
            first = _TOKEN_SPLIT.split(s, 1)[0]
            if first:
                toks.append(first)
    return toks


def detect_text_format(tokens: List[str]) -> str:
    """AUTO 判斷：前 400 個 token 全是同寬度純 hex，且（含 A-F 或寬度 ≥ 4）才算 HEX。"""
    sample = [t for t in tokens[:400] if t]
    if not sample:
        return "DEC"
    w = len(sample[0])
    if all(len(t) == w and _HEX_RE.match(t) for t in sample):
        if w >= 4 or any(re.search(r"[a-fA-F]", t) for t in sample):
            return "HEX"
    return "DEC"


_HEX_LUT = np.full(256, 255, dtype=np.uint8)
_HEX_LUT[48:58] = np.arange(10)
_HEX_LUT[65:71] = np.arange(10, 16)
_HEX_LUT[97:103] = np.arange(10, 16)


def _parse_hex_fixed(tokens: List[str], f: str) -> Optional[np.ndarray]:
    """快速路徑：全部是同寬度（≤ 13 字）的純 hex 字（沒有正負號、0x、空格）→ 向量化解析；結果和逐個 parse_token 相同。
    不符合（寬度不一、有別的字元、非 ASCII）回 None，改走逐個解析。"""
    n = len(tokens)
    w = len(tokens[0]) if n else 0
    if not 0 < w <= 13:
        return None
    try:
        b = "".join(tokens).encode("ascii")
    except (UnicodeEncodeError, TypeError):
        return None
    if len(b) != n * w:
        return None
    d = _HEX_LUT[np.frombuffer(b, dtype=np.uint8).reshape(n, w)]
    if (d == 255).any():
        return None
    v = d.astype(np.int64) @ (np.int64(16) ** np.arange(w - 1, -1, -1, dtype=np.int64))
    if f == "HEXS":
        bits = 4 * w
        v = np.where(v >= (1 << (bits - 1)), v - (1 << bits), v)
    return v.astype(float)


def parse_tokens_hold(tokens: List[str], fmt: str) -> np.ndarray:
    """整批解析；解析不了的格子用前一個有效值補（hold_fill），開頭的用第一個有效值補。"""
    n = len(tokens)
    if n == 0:
        return np.zeros(0)
    f = (fmt or "DEC").upper()
    if f in ("DEC", "AUTO"):
        try:                                   # 快速路徑：乾淨的十進位
            return np.asarray(tokens, dtype=float)
        except (ValueError, TypeError):
            pass
    if f in ("HEX", "HEXS"):
        fast = _parse_hex_fixed(tokens, f)
        if fast is not None:
            return fast
    out = np.empty(n)
    last: Optional[float] = None
    first_valid = -1
    for i, t in enumerate(tokens):
        v = parse_token(t, f)
        if v is None:
            out[i] = np.nan if last is None else last
        else:
            out[i] = v
            last = v
            if first_valid < 0:
                first_valid = i
    if first_valid > 0:
        out[:first_valid] = out[first_valid]
    elif first_valid < 0:
        out[:] = np.nan            # 整欄沒有一個數值（文字欄、只有單位）＝NaN，像 MATLAB readmatrix；不畫線、不參與差異比對
    return out


def load_text_signal(path: str, fmt: str = "AUTO") -> Tuple[np.ndarray, str]:
    """讀文字檔 → (值陣列, 實際使用的格式)。"""
    toks = read_text_tokens(path)
    f = (fmt or "AUTO").upper()
    if f == "AUTO":
        f = detect_text_format(toks)
    return parse_tokens_hold(toks, f), f


def sniff_delimiter(text: str) -> str:
    """用 csv.Sniffer 偵測分隔符號（, ; Tab），失敗時數第一列哪個最多。"""
    head = text[:4096]
    try:
        return csv.Sniffer().sniff(head, delimiters=",;\t").delimiter
    except Exception:
        first = head.splitlines()[0] if head.splitlines() else ""
        counts = {d: first.count(d) for d in (",", ";", "\t")}
        best = max(counts, key=counts.get)
        return best if counts[best] > 0 else ","


class CsvTable:
    """一個 CSV 檔：標頭、時間欄、各欄位的值。"""

    _TIME_VALUE_RE = re.compile(r"[+-]?[\d.,]+(?:[eE][+-]?\d+)?\s*(ps|ns|us|µs|μs|ms|s)", re.IGNORECASE)

    def __init__(self, path: str, text: Optional[str] = None):
        self.path = path
        if text is None:
            text = read_text_any(path)
        self.delimiter = sniff_delimiter(text)
        rows = [r for r in csv.reader(io.StringIO(text), delimiter=self.delimiter)
                if any(c.strip() for c in r)]
        self.names: List[str] = []
        self.rows: List[List[str]] = []
        self.time_col: Optional[int] = None
        self.has_header = False
        if not rows:
            return
        first = rows[0]
        # 第一列不全是數字就當作標頭
        self.has_header = not all(parse_number(c) is not None for c in first)
        if self.has_header:
            self.names = []
            for i, c in enumerate(first):              # 重複的欄位名加 _2、_3…（對話框的 Treeview 用欄位名當 iid，重複會丟 TclError）
                name = base = c.strip() or f"col{i + 1}"
                k = 2
                while name.lower() in (n.lower() for n in self.names):
                    name = f"{base}_{k}"
                    k += 1
                self.names.append(name)
            self.rows = rows[1:]
        else:
            self.names = [f"col{i + 1}" for i in range(len(first))]
            self.rows = rows
        self.time_col = self._detect_time_col()
        if self.time_col is not None and self.has_header:
            # 標頭下面的單位列（示波器常見：Time,ch1 / s,V）：時間格解析不了就不是資料，丟掉；
            # 不丟的話會被當成一個樣本（用第一個有效值補）→ 整條訊號多一點、往後錯一格，起始時間也讀不到
            tc = self.time_col
            k = 0
            while k < len(self.rows):
                cell = (self.rows[k][tc] if tc < len(self.rows[k]) else "").strip()
                if not cell or parse_time_s(cell) is not None:    # 空格是缺值、不是單位；解析得出來就是資料
                    break
                k += 1
            if 0 < k < len(self.rows):
                self.rows = self.rows[k:]

    def _detect_time_col(self) -> Optional[int]:
        if self.has_header:
            for i, n in enumerate(self.names):
                ln = n.strip().lower()
                if "time" in ln or ln in ("t", "timestamp"):
                    return i
            return None
        if self.rows and self.rows[0]:
            c = self.rows[0][0].strip()
            if self._TIME_VALUE_RE.fullmatch(c):   # 沒標頭：第一欄是「數字＋時間單位」
                return 0
        return None

    @property
    def nrows(self) -> int:
        return len(self.rows)

    def data_columns(self) -> List[str]:
        """排除時間欄的欄位名。"""
        return [n for i, n in enumerate(self.names) if i != self.time_col]

    def col_index(self, name: str) -> int:
        if name in self.names:
            return self.names.index(name)
        low = [n.lower() for n in self.names]
        if name.lower() in low:
            return low.index(name.lower())
        raise KeyError(tr("CSV 沒有欄位 {name!r}").format(name=name))

    def column_tokens(self, name: str) -> List[str]:
        idx = self.col_index(name)
        return [r[idx].strip() if idx < len(r) else "" for r in self.rows]

    def values_fmt(self, name: str, fmt: str = "AUTO") -> Tuple[np.ndarray, str]:
        toks = self.column_tokens(name)
        f = (fmt or "AUTO").upper()
        if f == "AUTO":
            f = detect_text_format([t for t in toks if t])
        return parse_tokens_hold(toks, f), f

    def values(self, name: str, fmt: str = "AUTO") -> np.ndarray:
        """欄位的值；解析不了的格子用前一個有效值補（hold_fill）。"""
        return self.values_fmt(name, fmt)[0]

    def time_values(self) -> Optional[np.ndarray]:
        if self.time_col is None:
            return None
        toks = self.column_tokens(self.names[self.time_col])
        out = np.empty(len(toks))
        last = np.nan
        for i, t in enumerate(toks):
            v = parse_time_s(t)
            if v is not None:
                last = v
            out[i] = last
        return out

    def _time_ends(self) -> Optional[Tuple[int, float, float]]:
        """時間欄（hold 補值後）有限值的 (個數, 第一個, 最後一個)：只從頭、從尾各找第一個解析得出來的格子，
        不逐列解析整欄（百萬列的 CSV 逐列 parse_time_s 要好幾秒）。結果和 time_values() 首尾相同。"""
        if self.time_col is None:
            return None
        tc = self.time_col
        cell = lambda r: r[tc].strip() if tc < len(r) else ""     # noqa: E731
        n = len(self.rows)
        i0 = next((i for i in range(n) if parse_time_s(cell(self.rows[i])) is not None), None)
        if i0 is None:
            return (0, math.nan, math.nan)
        j = next(j for j in range(n - 1, i0 - 1, -1) if parse_time_s(cell(self.rows[j])) is not None)
        return (n - i0, float(parse_time_s(cell(self.rows[i0]))), float(parse_time_s(cell(self.rows[j]))))

    def estimate_rate(self) -> Optional[float]:
        """由時間欄首尾估計取樣率。"""
        e = self._time_ends()
        if e is None or e[0] < 2:
            return None
        span = e[2] - e[1]
        if not span > 0:
            return None
        return (e[0] - 1) / span

    def start_time(self) -> Optional[float]:
        if self.time_col is None or not self.rows:
            return None
        r = self.rows[0]
        v = parse_time_s(r[self.time_col].strip() if self.time_col < len(r) else "")
        return None if v is None or not math.isfinite(v) else float(v)


# 快取：標頭和整檔分開，key = (絕對路徑, mtime_ns, size)
_HEADER_CACHE: Dict[tuple, Tuple[List[str], Optional[int]]] = {}
_TABLE_CACHE: Dict[tuple, CsvTable] = {}


def file_cache_key(path: str) -> tuple:
    st = os.stat(path)
    return (os.path.abspath(path), st.st_mtime_ns, st.st_size)


def placeholder_bad_key(path: str, e: BaseException) -> Optional[tuple]:
    """佔位訊號的檔案在卻讀不了時記下的「當時的檔案」（file_cache_key）：自動重試（每 3 秒）在檔案沒改過時就不再讀——內容不對（欄位名稱改了、
    格式不對）的大檔每 3 秒重讀很耗時。打不開（權限、被別的程式鎖住：Windows 的 Excel 開著 CSV）回 None：那種重試很便宜、鎖放掉時檔案不一定會改，照樣每次都試。"""
    if isinstance(e, OSError):
        return None
    try:
        return file_cache_key(path)
    except OSError:
        return None


def get_csv_table(path: str):
    """CSV 或 .mat 都回「表格」物件（CsvTable／matfile.MatTable 同介面）。"""
    key = file_cache_key(path)
    t = _TABLE_CACHE.get(key)
    if t is None:
        if len(_TABLE_CACHE) >= MAX_TABLE_CACHE:
            _TABLE_CACHE.clear()               # 整檔快取超過 8 個就全部清空
        t = matfile.MatTable(path) if is_mat_file(path) else wavfile.WavTable(path) if is_wav_like(path) else CsvTable(path)
        _TABLE_CACHE[key] = t
        _HEADER_CACHE[key] = (list(t.names), t.time_col)
    return t


def get_csv_header(path: str) -> Tuple[List[str], Optional[int]]:
    """只讀前幾列取得欄位名與時間欄（加入訊號分頁展開 CSV 用）；.mat 沒有「只讀標頭」，整檔讀一次並快取。"""
    key = file_cache_key(path)
    h = _HEADER_CACHE.get(key)
    if h is None:
        if is_mat_file(path) or is_wav_like(path):
            t = get_csv_table(path)
            h = (list(t.names), t.time_col)
        else:
            head = "\n".join(read_text_any(path, limit=65536).splitlines()[:6]) + "\n"
            t = CsvTable(path, text=head)
            h = (list(t.names), t.time_col)
        _HEADER_CACHE[key] = h
    return h


def is_mat_file(name: str) -> bool:
    return name.lower().endswith(MAT_EXTS)


def is_wav_like(name: str) -> bool:
    return name.lower().endswith(WAV_EXTS) or name.lower().endswith(NPY_EXTS)


def is_csv_file(name: str) -> bool:
    """CSV、.mat、WAV、.npy／.npz：都是「一個檔案、很多欄」的表格型來源，資料夾樹、匯入對話框、直接加入、拖放走同一條路。"""
    return name.lower().endswith(CSV_EXTS) or name.lower().endswith(MAT_EXTS) or is_wav_like(name)


def is_text_file(name: str) -> bool:
    return name.lower().endswith(TEXT_EXTS)


def signal_key_for(root: str, path: str, column: Optional[str] = None) -> str:
    """訊號 key：文字檔是 子資料夾/檔名；CSV 欄位是 檔案;;欄位。"""
    try:
        rel = os.path.relpath(path, root) if root else os.path.basename(path)
    except ValueError:                           # Windows 不同磁碟機
        rel = os.path.basename(path)
    if rel.startswith(".."):
        rel = os.path.basename(path)
    rel = rel.replace(os.sep, "/")
    return f"{rel};;{column}" if column is not None else rel


def scan_folder(root: str, errors: Optional[List[OSError]] = None) -> Dict[str, List[str]]:
    """遞迴掃描，回傳 {相對子資料夾: [檔名,...]}，根目錄本身用 "."。
    errors：給 list 時收集讀不到的資料夾（os.walk 預設會默默跳過，macOS 沒給「檔案與資料夾」權限時樹會是空的）。"""
    out: Dict[str, List[str]] = {}
    for dirpath, dirnames, filenames in os.walk(root, onerror=errors.append if errors is not None else None):
        dirnames[:] = sorted(d for d in dirnames if not d.startswith("."))
        files = sorted((f for f in filenames if is_text_file(f) or is_csv_file(f)),
                       key=str.lower)
        if not files:
            continue
        rel = os.path.relpath(dirpath, root).replace(os.sep, "/")
        out["." if rel == "." else rel] = files
    return out


# --- 目前資料夾（MATLAB Current Folder）用的掃描與欄位格式 -------------------------------------------
CF_COLS = ("size", "modified", "type")                   # MATLAB：Size／Date Modified／Type（Name 是樹本身那欄）
CF_COL_HEADS = {"size": "大小", "modified": "修改日期", "type": "類型"}
CF_HISTORY_MAX = 20                                      # 最近資料夾（位址列下拉）與返回堆疊的上限
CF_REFRESH_MS = 3000                                     # 自動重新整理檢查間隔
CF_REFRESH_MAX_DIRS = 2000
CF_SCAN_CAP = 20000                                      # 一次最多列這麼多項目（指到很大的資料夾時不要卡住）


def _cf_hidden(entry) -> bool:
    if entry.name.startswith("."):
        return True
    if sys.platform.startswith("win"):
        try:
            return bool(entry.stat(follow_symlinks=False).st_file_attributes & 0x2)   # FILE_ATTRIBUTE_HIDDEN
        except Exception:
            return False
    return False


def scan_tree(root: str, show_hidden: bool = False, errors: Optional[List[OSError]] = None,
              cap: int = CF_SCAN_CAP) -> Tuple[Dict[str, List[Tuple[str, bool, int, float]]], bool]:
    """遞迴列出 root 底下所有資料夾與檔案（MATLAB Current Folder 也列出全部，不只能開的）。
    回傳 ({相對資料夾（根＝"."，子層用 / 分隔）: [(名稱, 是資料夾, 大小, 修改時間)]}, 是否因為太多而截斷)。
    隱藏檔（. 開頭；Windows 的隱藏屬性）預設不列（MATLAB 偏好「Show hidden files and folders」預設關）。
    捷徑／符號連結的資料夾照樣列出但不往下走（避免迴圈）。"""
    out: Dict[str, List[Tuple[str, bool, int, float]]] = {}
    count = 0
    stack = ["."]
    while stack:
        rel = stack.pop()
        d = root if rel == "." else os.path.join(root, *rel.split("/"))
        try:
            with os.scandir(d) as it:
                ents = list(it)
        except OSError as e:
            if errors is not None:
                errors.append(e)
            continue
        items: List[Tuple[str, bool, int, float]] = []
        sub: List[str] = []
        for e in ents:
            if not show_hidden and _cf_hidden(e):
                continue
            try:
                isdir = e.is_dir()
                st = e.stat()
            except OSError:
                continue
            items.append((e.name, isdir, 0 if isdir else int(st.st_size), float(st.st_mtime)))
            if isdir and not e.is_symlink():
                sub.append(e.name if rel == "." else f"{rel}/{e.name}")
        out[rel] = items
        count += len(items)
        if count > cap:
            return out, True
        stack.extend(sorted(sub, reverse=True))
    return out, False


def folder_map_from_scan(scan: Dict[str, list]) -> Dict[str, List[str]]:
    """舊介面相容：{相對資料夾: [能畫的檔名]}（只留有檔案的資料夾），scan_folder 的格式。"""
    out: Dict[str, List[str]] = {}
    for rel, items in scan.items():
        files = sorted((n for n, isdir, _s, _t in items if not isdir and (is_text_file(n) or is_csv_file(n))), key=str.lower)
        if files:
            out[rel] = files
    return out


def cf_fmt_size(n: Optional[int]) -> str:
    """MATLAB 的大小欄：KB 起跳（fileSize "${0} ${1}"，單位 KB／MB／GB…）。"""
    if n is None:
        return ""
    if n < 1024 * 1024:
        return f"{max(1, int(round(n / 1024)))} KB" if n else "0 KB"
    for unit, k in (("MB", 1024 ** 2), ("GB", 1024 ** 3), ("TB", 1024 ** 4)):
        if n < k * 1024 or unit == "TB":
            v = n / k
            return f"{v:.1f} {unit}" if v < 10 else f"{v:.0f} {unit}"
    return f"{n} B"


def cf_fmt_mtime(t: Optional[float]) -> str:
    if not t:
        return ""
    try:
        return time.strftime("%Y/%m/%d %H:%M", time.localtime(t))
    except Exception:
        return ""


def cf_type_text(name: str, isdir: bool) -> str:
    """MATLAB：資料夾＝"Folder"、其他＝"${副檔名} File"。"""
    if isdir:
        return tr("資料夾")
    ext = os.path.splitext(name)[1].lstrip(".").upper()
    return tr("{ext} 檔案").format(ext=ext) if ext else tr("檔案")


def cf_name_error(name: str, folder: str, is_folder: bool, show_hidden: bool) -> Optional[str]:
    """新名稱的檢查（MATLAB Current Folder 改名的提示）：空白、斜線、同名、隱藏名稱。沒問題回 None。"""
    if not name:
        return tr("名稱不能是空白。")
    bad = '\\/:*?"<>|' if sys.platform.startswith("win") else "/"
    if any(c in name for c in bad):
        return tr("名稱不能含有這些字元：{chars}").format(chars=" ".join(bad))
    if name.startswith(".") and not show_hidden:
        return tr("沒有開「顯示隱藏的檔案與資料夾」時，不能改成隱藏的名稱（. 開頭）。")
    if os.path.exists(os.path.join(folder, name)):
        return tr("已經有同名的資料夾。") if is_folder else tr("已經有同名的檔案。")
    return None


def cf_details_text(node: Optional[dict], nsel: int, scan: Optional[dict], root: str) -> str:
    """詳細資料面板的內容（MATLAB Details：沒選＝提示、資料夾＝項目數、檔案＝類型／大小／日期；表格多列出欄位）。"""
    if nsel > 1:
        return tr("已選取 {n} 個項目").format(n=nsel)
    if not node:
        return tr("選一個檔案或資料夾來看詳細資料")
    kind = node.get("kind")
    if kind == "column":
        return tr("欄位：{col}\n檔案：{name}").format(col=node.get("column"), name=node.get("name"))
    lines = [node.get("name") or ""]
    if kind == "folder":
        items = (scan or {}).get(node.get("sub"), [])
        lines.append(tr("資料夾｜{n} 個項目").format(n=len(items)))
        lines.append(tr("修改日期：{t}").format(t=cf_fmt_mtime(node.get("mtime"))))
        return "\n".join(lines)
    lines.append(tr("{type}｜{size}").format(type=cf_type_text(node.get("name") or "", False), size=cf_fmt_size(node.get("size"))))
    lines.append(tr("修改日期：{t}").format(t=cf_fmt_mtime(node.get("mtime"))))
    if kind == "csv":
        try:
            names, tcol = get_csv_header(node["path"])
            cols = [n for i, n in enumerate(names) if i != tcol]
            more = "…" if len(cols) > 8 else ""
            lines.append(tr("{n} 個資料欄：{names}").format(n=len(cols), names=tr("、").join(cols[:8]) + more))
            if tcol is not None:
                lines.append(tr("時間欄：{name}").format(name=names[tcol]))
        except Exception as e:
            lines.append(tr("讀不到欄位：{err}").format(err=e))
    elif kind == "other":
        lines.append(tr("這種檔案不能畫圖；雙擊用系統預設程式開啟"))
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# 3. 突波抑制
# ---------------------------------------------------------------------------
def despike(x, k: int = 2, n_sigma: float = 8.0, min_abs: float = 20.0,
            passes: int = 8) -> Tuple[np.ndarray, np.ndarray]:
    """修 FPGA 擷取時常見的單點 / 短暫跳到 0 或滿刻度的錯誤值。

    對每個長度 L = 1..k 的候選區間，用區間外側前後各一點連一條直線，
    區間內每一點都偏離直線超過門檻才算突波（分數 = 區間內偏差的最小值）。
    門檻 = max(min_abs, n_sigma × σ)，σ = 1.4826 × median(score)。
    L ≥ 2 扣掉曲率補償 curv × (L+1)² / 8，避免把平滑的波峰削平。
    每輪依分數高→低修正（同分短的優先），修正段與兩端點鎖住，同一輪不重疊；
    最多 passes 輪。回傳 (修正後 array, 被修正位置的 bool mask)。
    """
    y = np.asarray(x, dtype=float).copy()
    n = len(y)
    mask = np.zeros(n, dtype=bool)
    k = int(max(1, min(3, int(k))))
    if n < 3:
        return y, mask
    for _ in range(int(max(1, passes))):
        cands: List[Tuple[float, int, int]] = []
        thr = float(min_abs)
        d2 = np.abs(np.diff(y, 2))                 # d2[j] = |y[j] - 2y[j+1] + y[j+2]|
        for L in range(1, k + 1):
            m = n - L - 1                          # 候選起點 s = 1..n-L-1，共 m 個
            if m <= 0:
                continue
            left = y[0:m]
            right = y[L + 1:L + 1 + m]
            score = None
            for i in range(L):
                seg = y[1 + i:1 + i + m]
                line = left + (right - left) * ((i + 1) / (L + 1))
                dev = np.abs(seg - line)
                score = dev if score is None else np.minimum(score, dev)
            if L == 1:
                # σ 由單點偏差估計：σ = 1.4826 × median(score)；所有 L 共用同一個門檻，
                # 這樣每週期取樣點很少（本身偏差就大）的訊號不會被誤判
                sigma = 1.4826 * float(np.median(score))
                thr = max(float(min_abs), float(n_sigma) * sigma)
            if L >= 2:
                # 曲率補償：取區間外側（左 s-3..s-1、右 s+L..s+L+2）二階差分的最大值
                s_idx = np.arange(1, m + 1)
                lc = np.zeros(m)
                j = s_idx - 3
                ok = j >= 0
                lc[ok] = d2[j[ok]]
                rc = np.zeros(m)
                j = s_idx + L
                ok = j <= n - 3
                rc[ok] = d2[j[ok]]
                score = score - np.maximum(lc, rc) * (L + 1) ** 2 / 8.0
            # 兩端點本身的落差（階梯邊緣、或區間外側那一點其實也是突波）大於區間的偏離量時不算突波：
            # 匯流排每次換值不會被當成突波；比 k 長的突波不會「修一半」把好點拉向壞值（等 k 調大再整段修）
            jump = np.abs(right - left)
            for s0 in np.nonzero((score > thr) & (score > jump))[0]:
                cands.append((float(score[s0]), L, int(s0) + 1))
        if not cands:
            break
        cands.sort(key=lambda c: (-c[0], c[1]))
        locked = np.zeros(n, dtype=bool)
        fixed_any = False
        for _sc, L, s in cands:
            a, b = s - 1, s + L
            if locked[a:b + 1].any():
                continue
            y[s:s + L] = y[a] + (y[b] - y[a]) * (np.arange(1, L + 1) / (L + 1))
            mask[s:s + L] = True
            locked[a:b + 1] = True
            fixed_any = True
        if not fixed_any:
            break
    return y, mask


# ---------------------------------------------------------------------------
# 4. Signal dataclass
# ---------------------------------------------------------------------------
SIGNAL_FIELDS = ("key", "path", "sps", "offset", "label", "panel", "uid", "fmt", "column",
                 "vshift", "vscale", "despike", "dk", "dthr", "dmin", "color", "lw", "ls",
                 "marker", "ms", "visible", "yaxis", "ptype", "derive", "src", "disp", "radix", "bits", "roi", "pp")


def parse_roi(text) -> Optional[Tuple[int, int]]:
    """擷取訊號的樣本範圍字串 "i0:i1" → (i0, i1)；格式不對、i0 < 0 或 i1 ≤ i0 → None。"""
    t = str(text or "").strip()
    if ":" not in t:
        return None
    a, _, b = t.partition(":")
    try:
        i0, i1 = int(a), int(b)
    except ValueError:
        return None
    return (i0, i1) if 0 <= i0 < i1 else None


def iq_derive(kind: str, i, q, fs: Optional[float] = None) -> np.ndarray:
    """I/Q → |I+jQ|（iq_mag）、相位角度（iq_phase：−180..180°；iq_phase_unwrap：展開成連續）
    或瞬時頻率（iq_fm：相鄰樣本的 unwrap 相位差 × fs/2π，Hz；第 0 個樣本沒有前一點＝NaN，長度和輸入一樣）。長度不同時截成較短的。"""
    i = np.asarray(i, dtype=float)
    q = np.asarray(q, dtype=float)
    n = min(len(i), len(q))
    if kind == "iq_mag":
        return np.hypot(i[:n], q[:n])
    ph = np.arctan2(q[:n], i[:n])
    if kind == "iq_fm":
        out = np.full(n, np.nan)
        if n >= 2:
            out[1:] = np.diff(np.unwrap(ph)) * float(fs if fs else 1.0) / (2.0 * math.pi)
        return out
    if kind == "iq_phase_unwrap":
        ph = np.unwrap(ph)
    return np.degrees(ph)


def iq_derived_name(kind: str, si, sq) -> str:
    """衍生訊號的名稱（主視窗的 I/Q 幅度／相位與 I/Q 分析視窗共用，貼上時才認得出同一組）。"""
    if kind == "iq_mag":
        return f"|{si.name} + j·{sq.name}|"
    if kind == "iq_fm":
        return f"FM({si.name} + j·{sq.name}) [Hz]"
    return f"∠({si.name} + j·{sq.name}) [deg]"


@dataclass
class Signal:
    """一條訊號的所有參數；data / detected / raw / spike_mask 是快取，不參與比較。"""
    key: str
    path: str
    sps: float = 1.0                 # samples per symbol
    offset: float = 0.0              # 單位依 SETTINGS["offset_unit"]（symbol 或 sample）
    label: str = ""
    panel: int = 1
    uid: int = 0
    fmt: str = "AUTO"
    column: Optional[str] = None     # CSV 欄位名；文字檔為 None
    vshift: float = 0.0
    vscale: float = 1.0
    despike: bool = False
    dk: int = 2
    dthr: float = 8.0
    dmin: float = 20.0
    color: Optional[str] = None      # 線色（None = 依 panel 內順序用 PALETTE）
    lw: Optional[float] = None       # 線寬（點；None = 依風格預設：default 1.0、matlab 0.5）
    ls: Optional[str] = None         # 線型（None = 依「虛線區分」選項自動）
    marker: str = ""                 # 標記樣式（""=無）
    ms: float = DEFAULT_MS           # 標記大小（點）
    visible: bool = True             # 隱藏的不畫、不比差異，但留在清單
    yaxis: str = "left"              # 畫在左軸或右軸（twinx）
    ptype: str = DEFAULT_PLOT_TYPE   # 繪圖類型 line／stairs／stem（MATLAB timescope PlotType）
    derive: str = ""                 # 衍生訊號種類（DERIVE_KINDS）；"" ＝從檔案讀
    src: str = ""                    # 衍生訊號的來源 uid："<I uid>,<Q uid>"；前處理（PP_KINDS）是一個 uid
    disp: str = "analog"             # 顯示格式 analog／digital（手動選；Logic Analyzer DisplayChannelFormat；dsv_bus）
    radix: str = ""                  # 進位制 ""＝自動／hex／bin／oct／sdec／udec（DisplayChannelRadix）
    bits: int = 0                    # 位元寬度（0＝自動：HEX 字數 × 4 或數值範圍）
    roi: str = ""                    # 擷取的訊號（MATLAB Extract Signals）：來源資料的樣本範圍 "i0:i1"（含 i0、不含 i1）；""＝整段
    pp: Dict[str, Any] = field(default_factory=dict)   # 前處理衍生訊號的參數（dsv_preprocess.validate 的結果：頻率 Hz、時間秒＋顯示單位）
    data: Optional[np.ndarray] = field(default=None, compare=False, repr=False)
    detected: Optional[str] = field(default=None, compare=False, repr=False)
    raw: Optional[np.ndarray] = field(default=None, compare=False, repr=False)
    spike_mask: Optional[np.ndarray] = field(default=None, compare=False, repr=False)
    src_key: Optional[tuple] = field(default=None, compare=False, repr=False)   # 讀檔當時的 (路徑, mtime, size)
    src_cache: Optional[tuple] = field(default=None, compare=False, repr=False)  # 衍生訊號：算的時候用的來源陣列（同一物件＝沒變）
    raw_full: Optional[np.ndarray] = field(default=None, compare=False, repr=False)  # 擷取的訊號：切之前的整段原始值（突波抑制用整段算）
    # B1（2026-10-28 使用者決定，0.9.13）：開啟（自動還原、匯入設定）時來源檔案不在的佔位訊號——留在清單（灰字、Fmt 欄「檔案不在」）、不畫、
    # 參數全留；它的衍生訊號也不畫、等資料（waiting）。檔案回來（啟動時、資料夾自動重新整理的計時器、清單右鍵「重新載入檔案不在的訊號」）
    # 就讀進來、旗標清掉。不是設定檔的欄位（不在 SIGNAL_FIELDS）：自動存檔照樣記路徑與參數，下次開啟再看檔案在不在
    missing_file: bool = field(default=False, compare=False, repr=False)
    load_error: Optional[str] = field(default=None, compare=False, repr=False)   # 佔位訊號：檔案在卻讀不了的原因（清單 Fmt「讀不了」、提示、狀態列寫）
    bad_key: Optional[tuple] = field(default=None, compare=False, repr=False)    # 佔位訊號：上次讀不了時檔案的 (路徑, mtime, size)——自動重試只在檔案改過才再讀
    # 剛從檔案加進來、還沒讀過（拖放、資料夾面板的「加入」、匯入 CSV 對話框新加的欄位）：讀不了＝不是能用的檔，照舊不加（重畫時移除＋
    # 錯誤視窗「讀取訊號失敗（已從清單移除）」）。讀成功一次就清掉。其他讀不了的（開著的訊號改讀取格式、重畫時發現檔案被改壞或拿掉權限、
    # 貼上、⌘Z 拿回來的）都留成佔位（2026-10-29 22:5x 使用者決定，0.9.14；SignalViewer._placeholder_lost_sources）
    fresh_add: bool = field(default=False, compare=False, repr=False)

    # --- 衍生訊號（I/Q → 幅度／相位）：來源用 uid 找（Signal.resolver 由主視窗設定）--------------------------
    @property
    def src_uids(self) -> Tuple[int, ...]:
        try:
            return tuple(int(t) for t in str(self.src or "").split(",") if t.strip())
        except ValueError:
            return ()

    def sources(self) -> Optional[List["Signal"]]:
        """衍生訊號的來源（I、Q；前處理是那一條）；找不到任何一條回傳 None。
        前處理的來源可以是任何訊號（含另一條衍生訊號：先濾波再取包絡，MATLAB 也是一步一步做）；I/Q 的來源必須是一般訊號。"""
        fn = Signal.resolver
        uids = self.src_uids
        if not self.derive or fn is None:
            return None
        if self.derive in PP_KINDS:
            if len(uids) != 1:
                return None
            x = fn(uids[0])
            return None if x is None or x is self else [x]
        if len(uids) != 2:
            return None
        out = [fn(u) for u in uids]
        if any(x is None or x is self or x.derive for x in out):
            return None
        return out

    _pp_busy = set()               # （類別屬性，不加型別註記＝不是 dataclass 欄位）正在算的前處理衍生訊號（手改設定檔造成的循環來源 → 當成來源不見，不無限遞迴）

    def _src_state(self) -> Optional[tuple]:
        """來源的狀態：I、Q 的資料陣列；FM 另加 fs（SPS × symbol rate，變了就重算）；
        前處理＝(來源資料, 來源 fs, 來源起點秒數)——來源改 SPS／offset／symbol rate 也要重算（濾波的 Hz、時間單位的視窗跟著 fs）。"""
        if self.derive in PP_KINDS:
            if id(self) in Signal._pp_busy:
                return None
            Signal._pp_busy.add(id(self))
            try:
                srcs = self.sources()
                if srcs is None:
                    return None
                si = srcs[0]
                return (si.get_data(), self._fs_of(si), float(si.x0) / self._symbol_rate(si))
            finally:
                Signal._pp_busy.discard(id(self))
        srcs = self.sources()
        if srcs is None:
            return None
        st: tuple = tuple(x.get_data() for x in srcs)
        if self.derive == "iq_fm":
            st = st + (self._fs_of(srcs[0]),)
        return st

    @staticmethod
    def _symbol_rate(src: Optional["Signal"] = None) -> float:
        fn = Signal.symbol_rate_fn                   # (來源訊號) → 它所在 panel 的 symbol rate；舊的無參數函式也接受
        try:
            sr = fn(src) if fn is not None else DEFAULT_SYMBOL_RATE
        except TypeError:
            sr = fn()
        return float(sr if sr and sr > 0 else DEFAULT_SYMBOL_RATE)

    @staticmethod
    def _fs_of(src: "Signal") -> float:
        fn = Signal.symbol_rate_fn                   # (來源訊號) → 它所在 panel 的 symbol rate（每個 panel 各自設）；舊的無參數函式也接受
        try:
            sr = fn(src) if fn is not None else DEFAULT_SYMBOL_RATE
        except TypeError:
            sr = fn()
        return float(src.sps) * float(sr if sr and sr > 0 else DEFAULT_SYMBOL_RATE)

    def _derived_fresh(self) -> bool:
        st, c = self._src_state(), self.src_cache
        if st is None or c is None:
            return st is None and c is None
        if len(st) != len(c):
            return False
        return all((a is b) if isinstance(a, np.ndarray) else (a == b) for a, b in zip(st, c))

    # --- 讀取與快取 ---------------------------------------------------------
    @property
    def roi_range(self) -> Optional[Tuple[int, int]]:
        """擷取的訊號：來源資料的樣本範圍 (i0, i1)（含 i0、不含 i1）；一般訊號 None。"""
        return parse_roi(self.roi)

    def waiting(self) -> bool:
        """B1：正在等來源檔案回來——自己是檔案不在的佔位訊號（missing_file），或來源鏈裡有一條是（衍生訊號也不畫、等資料）。"""
        return signal_waiting(self)

    def _load_full(self) -> np.ndarray:
        """讀檔（或算衍生訊號）的整段原始值；順便設定 detected、src_key、src_cache。
        B1：佔位訊號（missing_file）檔案還不在＝空的、不丟例外（plot() 不會把它當讀取失敗移除）；檔案回來了就照常讀、旗標清掉；
        回來了卻讀不了（權限、格式）也留在清單、原因記在 load_error。衍生訊號的來源鏈裡有佔位訊號＝空的、等資料（不算算不出來）。"""
        if self.derive:
            st = self._src_state()
            self.src_cache = st
            self.src_key = None
            if st is None:                    # 來源被移除／還沒還原：空的（畫面略過、清單 Fmt 顯示 missing）
                self.detected = "missing"
                return np.zeros(0)
            if self.waiting():                # B1：來源的檔案不在——等資料（src_cache 記著現在這組空陣列，來源讀進來就會重算）
                self.detected = None
                if self.derive in PP_KINDS:
                    self.pp_error = None
                    self.pp_warnings = []
                return np.zeros(0)
            if self.derive in PP_KINDS:       # 前處理：交給已對過 MATLAB 的模組算；算不出來（來源變短、有 NaN…）＝空的，原因記在 pp_error
                try:
                    if np.asarray(st[0]).size == 0:   # 來源沒有資料（來源自己算不出來、它的來源不見了、空檔）：不是正常的空結果，說明來源的問題
                        raise pp_empty_source_error(self.sources()[0])
                    r = dsv_preprocess.compute(self.derive, self.pp, st[0], st[1], st[2])
                except dsv_preprocess.PreprocessError as e:
                    self.pp_error = e.message
                    self.detected = "error"
                    return np.zeros(0)
                self.pp_error = None
                self.pp_warnings = list(r["warnings"])
                self.detected = dsv_preprocess.detected_label(self.derive)
                return r["y"]
            self.detected = {"iq_mag": "|I+jQ|", "iq_phase": "∠ deg", "iq_phase_unwrap": "∠ deg unwrap", "iq_fm": "FM Hz"}.get(self.derive, self.derive)
            return iq_derive(self.derive, st[0], st[1], fs=st[2] if len(st) > 2 else None)
        if self.missing_file:                 # B1：佔位訊號
            if not os.path.isfile(self.path):
                self.detected = None
                self.load_error = None        # 現在是「檔案不在」（以前讀不了的原因不算了）
                return np.zeros(0)
            try:
                full = self._read_file()
            except Exception as e:            # 檔案在卻讀不了（權限、格式、欄位名稱不對）：留在清單、記原因（清單 Fmt「讀不了」、狀態列寫）
                err = f"{type(e).__name__}: {e}"
                if err != self.load_error:    # 同一個原因只記一次 log（自動重試每 3 秒一次）
                    log(f"佔位訊號的檔案在卻讀不了 {self.key}（{self.path}）: {e}")
                self.load_error = err
                self.bad_key = placeholder_bad_key(self.path, e)
                self.detected = None
                return np.zeros(0)
            self.missing_file, self.load_error, self.bad_key = False, None, None
            return full
        return self._read_file()

    def _read_file(self) -> np.ndarray:
        """從檔案讀整段原始值（一般訊號）：凍結檔 .npy、CSV 欄位、文字檔；設定 detected、src_key。讀不了丟例外。"""
        try:
            key = file_cache_key(self.path)
        except OSError:
            key = None
        if self.column is None and str(self.path).lower().endswith(".npy"):     # 改成獨立訊號的衍生訊號（frozen_data_dir）
            full = np.asarray(np.load(self.path, allow_pickle=False), dtype=float).ravel()
            self.detected = "float"
            self.src_key = key
            self.fresh_add = False
            return full
        if self.column is not None:
            table = get_csv_table(self.path)
            full, self.detected = table.values_fmt(self.column, self.fmt)
        else:
            full, self.detected = load_text_signal(self.path, self.fmt)
        self.src_key = key
        self.fresh_add = False                  # 讀成功過：之後讀不了就留佔位（0.9.14）
        return full

    def ensure_raw(self) -> np.ndarray:
        if self.raw is None:
            full = self._load_full()
            rr = self.roi_range
            if rr is None:
                self.raw_full = None
                self.raw = full
            else:                             # 擷取的訊號：只留那一段（檔案後來變短就截到有的）
                self.raw_full = full
                self.raw = full[rr[0]:min(rr[1], len(full))]
        return self.raw

    def source_changed(self) -> bool:
        """檔案在讀進來之後被改寫過（例如重新擷取覆蓋同名檔）。檔案不見了不算（保留已讀的資料）。
        衍生訊號：來源的資料變了（改 shift／scale／突波抑制、重新讀檔、來源被移除或復原）。"""
        if self.derive:
            return self.raw is not None and not self._derived_fresh()
        if self.raw is None or self.src_key is None:
            return False
        try:
            return file_cache_key(self.path) != self.src_key
        except OSError:
            return False

    def get_data(self) -> np.ndarray:
        """處理順序：原始值 → despike → (y + vshift) × vscale，結果快取在 data。"""
        if self.derive and self.raw is not None and not self._derived_fresh():
            self.invalidate(reload=True)          # 來源變了：重算（只比對陣列物件，很便宜）
        if self.data is None:
            raw = self.ensure_raw().astype(float)
            rr = self.roi_range
            if self.despike and rr is not None and self.raw_full is not None and len(self.raw_full) > len(raw):
                yf, mf = despike(self.raw_full.astype(float), k=self.dk, n_sigma=self.dthr, min_abs=self.dmin)
                y, m = yf[rr[0]:rr[0] + len(raw)], mf[rr[0]:rr[0] + len(raw)]   # 整段算完再切：邊緣幾點也和來源一模一樣
            elif self.despike:
                y, m = despike(raw, k=self.dk, n_sigma=self.dthr, min_abs=self.dmin)
            else:
                y, m = raw, np.zeros(len(raw), dtype=bool)
            self.spike_mask = m
            self.data = (y + self.vshift) * self.vscale
        return self.data

    def invalidate(self, reload: bool = False) -> None:
        self.data = None
        self.spike_mask = None
        if reload:
            self.raw = None
            self.raw_full = None
            self.detected = None
            self.src_cache = None

    @property
    def n(self) -> int:
        return 0 if self.raw is None else len(self.raw)

    @property
    def spikes_fixed(self) -> int:
        return 0 if self.spike_mask is None else int(self.spike_mask.sum())

    # --- x 軸（內部單位一律 symbol）---------------------------------------
    @property
    def x0(self) -> float:
        if SETTINGS.get("offset_unit") == "sample":
            return self.offset / self.sps
        return float(self.offset)

    def step_xy(self) -> Tuple[np.ndarray, np.ndarray]:
        """給 step(where='post') 用：x 長度 N+1。"""
        y = self.get_data()
        x = self.x0 + np.arange(len(y) + 1) / self.sps
        return x, y

    @property
    def x_span(self) -> Tuple[float, float]:
        n = len(self.get_data())
        return self.x0, self.x0 + n / self.sps

    def value_at(self, x: float) -> Optional[float]:
        """sample-and-hold；超出範圍回傳 None。"""
        y = self.get_data()
        i = int(math.floor((x - self.x0) * self.sps + 1e-9))
        if 0 <= i < len(y):
            v = float(y[i])
            return v if math.isfinite(v) else None      # NaN／Inf 的樣本（空欄、溢位）→ 游標讀值顯示「—」
        return None

    def values_at(self, xs) -> np.ndarray:
        """向量版 value_at；超出範圍回傳 NaN。"""
        y = self.get_data()
        xs = np.asarray(xs, dtype=float)
        idx = np.floor((xs - self.x0) * self.sps + 1e-9).astype(np.int64)
        out = np.full(len(xs), np.nan)
        ok = (idx >= 0) & (idx < len(y))
        out[ok] = y[idx[ok]]
        return out

    def index_range(self, x0: float, x1: float) -> Tuple[int, int]:
        """x 範圍內的樣本索引 [i0, i1)（範圍外截掉）。"""
        n = len(self.get_data())
        if not math.isfinite(x0):
            i0 = 0
        else:
            i0 = max(0, int(math.ceil((x0 - self.x0) * self.sps - 1e-9)))
        if not math.isfinite(x1):
            i1 = n
        else:
            i1 = min(n, int(math.floor((x1 - self.x0) * self.sps + 1e-9)) + 1)
        return i0, max(i0, i1)

    def slice_range(self, x0: float, x1: float) -> Tuple[np.ndarray, float]:
        """x 範圍內的資料（給頻譜用）→ (y, dx[symbol])。"""
        y = self.get_data()
        i0, i1 = self.index_range(x0, x1)
        if i1 <= i0:
            return np.zeros(0), 1.0 / self.sps
        return y[i0:i1], 1.0 / self.sps

    # --- 其他 ---------------------------------------------------------------
    def default_label(self) -> str:
        if self.derive:
            return self.key
        if self.column is not None:
            stem = os.path.splitext(os.path.basename(self.path))[0]
            return f"{stem}:{self.column}"
        return self.key

    @property
    def name(self) -> str:
        return self.label or self.key

    def to_dict(self) -> dict:
        d = {k: getattr(self, k) for k in SIGNAL_FIELDS}
        d["pp"] = dsv_preprocess.copy_params(self.pp)       # 副本：快照／設定檔／剪貼簿不和訊號共用同一個 dict
        return d

    @classmethod
    def from_dict(cls, d: dict, version: int = CONFIG_VERSION) -> "Signal":
        kw = {k: d[k] for k in SIGNAL_FIELDS if k in d}
        sig = cls(**kw)
        sig.label = drop_surrogates(sig.label)       # 手改、壞掉的 JSON 裡的孤立代理字元：整張圖畫不出來、自動存檔寫不進去（0.9.9 就這樣）
        try:
            sig.sps = float(sig.sps) if sig.sps else 1.0
        except (TypeError, ValueError):
            sig.sps = 1.0
        if not (0 < sig.sps < math.inf) or not math.isfinite(1.0 / sig.sps):     # 手改的設定檔：NaN／inf／負數 → 1
            sig.sps = 1.0
        for k_, dflt in (("offset", 0.0), ("vshift", 0.0), ("vscale", 1.0)):
            try:
                v_ = float(getattr(sig, k_))
            except (TypeError, ValueError):
                v_ = dflt
            setattr(sig, k_, v_ if math.isfinite(v_) and not (k_ == "vscale" and v_ == 0) else dflt)
        sig.panel = int(sig.panel)
        sig.dk = int(sig.dk)
        sig.lw = None if sig.lw in (None, "", 0) else float(sig.lw)
        if version <= 4 and sig.lw == 1.0:
            sig.lw = None                 # v3.2 一律寫 1.0；當成「未設定」才能跟著風格變
        if sig.ls not in LINESTYLES:
            sig.ls = None
        if sig.marker not in MARKERS:
            sig.marker = ""
        try:
            sig.ms = float(sig.ms) if sig.ms and float(sig.ms) > 0 else DEFAULT_MS
        except (TypeError, ValueError):
            sig.ms = DEFAULT_MS
        sig.visible = bool(sig.visible)
        if sig.yaxis not in ("left", "right"):
            sig.yaxis = "left"
        if sig.ptype not in PLOT_TYPE_KEYS:
            sig.ptype = DEFAULT_PLOT_TYPE
        if sig.derive not in DERIVE_KINDS:
            sig.derive = ""
        sig.src = str(sig.src or "") if sig.derive else ""
        sig.pp = dsv_preprocess.normalize_params(sig.derive, sig.pp) if sig.derive in PP_KINDS else {}   # 舊設定檔沒有 pp
        rr = parse_roi(sig.roi)
        sig.roi = f"{rr[0]}:{rr[1]}" if rr else ""
        dsv_bus.normalize_fields(sig)
        return sig


Signal.resolver = None      # uid → Signal（主視窗設定；衍生訊號找來源用）。類別屬性，不是 dataclass 欄位
Signal.symbol_rate_fn = None    # (來源訊號) → symbol rate（主視窗：那條訊號所在 panel 的；FM 衍生訊號算 fs 用）


def frozen_data_dir() -> str:
    """衍生訊號的來源被刪掉、它改成獨立訊號時（2026-10-25 使用者決定 U8），那條訊號現在的資料存在這裡（.npy，自動存檔記路徑）：
    macOS ~/Library/Application Support/SignalViewer/frozen、Windows %LOCALAPPDATA%\\SignalViewer\\frozen、其他 ~/.local/share/SignalViewer/frozen。
    沒有人用到的檔自動清掉（U9：SignalViewer.cleanup_frozen）；「匯出設定」把資料放進設定檔裡，不靠這裡的檔。"""
    home = os.path.expanduser("~")
    if sys.platform == "darwin":
        base = os.path.join(home, "Library", "Application Support", "SignalViewer")
    elif sys.platform == "win32":
        base = os.path.join(os.environ.get("LOCALAPPDATA") or home, "SignalViewer")
    else:
        base = os.path.join(os.environ.get("XDG_DATA_HOME") or os.path.join(home, ".local", "share"), "SignalViewer")
    return os.path.join(base, "frozen")


# --- 凍結檔的自動清理（2026-10-25 使用者決定 U9）---------------------------------------------------------------------
# 沒有人用到＝目前的訊號、復原／重做的快照、訊號剪貼簿、自動存檔（上次的工作階段）都沒用到它，而且沒有別的 DSV 開著
# （別的 DSV 的記憶體、undo 看不到，寧可不清）。啟動時、每次寫完自動存檔後清。只動 save_frozen_array 存的檔名格式，別的檔案一律不碰。
FROZEN_FILE_RE = re.compile(r"^[0-9A-Za-z_.-]+_[0-9a-f]{20}\.npy$")                 # <名稱>_<資料內容雜湊 20 位>.npy
FROZEN_TMP_RE = re.compile(r"^[0-9A-Za-z_.-]+_[0-9a-f]{20}\.npy\.\d+\.tmp\.npy$")    # 寫到一半（當掉）留下的暫存檔
FROZEN_LOCK_PREFIX = ".dsv-instance-"                                                # 開著的 DSV 在凍結資料夾裡鎖著的登記檔


def _path_basename(path) -> str:
    """路徑的檔名（/ 和 \\ 都算分隔：別台電腦、別的作業系統存的路徑也拆得開）。"""
    return re.split(r"[\\/]", str(path or ""))[-1]


FROZEN_READBACK_MSG = "data read back differs from what was written"   # save_frozen_array 存完讀回來不一樣（OSError 的 strerror）


def _frozen_file_holds(path: str, a: np.ndarray) -> bool:
    """path 已經存著和 a（一維 float64）每個位元都一樣的資料（NaN、±Inf、-0 也算）。不在、讀不了、格式不對、內容不同都回 False。"""
    try:
        if not os.path.isfile(path):
            return False
        b = np.load(path, allow_pickle=False)
    except Exception:
        return False
    return (isinstance(b, np.ndarray) and b.dtype == a.dtype and b.shape == a.shape
            and bool(np.array_equal(b.view(np.uint64), a.view(np.uint64))))


class _WriteOnly:
    """np.lib.format.write_array 的寫入目標只給 write（不是真的檔案物件）：numpy 就用 fp.write 一段一段寫（Python 的檔案 I/O），
    不走 ndarray.tofile。tofile 寫不完時丟的 OSError 沒有 errno（「1200 requested and 496 written」「obtaining file position failed」），
    錯誤視窗說不出原因；Python 的寫入失敗都帶 errno（磁碟滿 ENOSPC、超過檔案大小上限 EFBIG、超過配額 EDQUOT…）。"""
    __slots__ = ("write",)

    def __init__(self, f):
        self.write = f.write


def _write_npy(path: str, a: np.ndarray) -> None:
    """a 寫成 .npy（和 np.save 同樣的格式、同樣的位元組）：寫完 flush＋fsync，寫不進去丟帶 errno 的 OSError（_WriteOnly）。
    寫到一半的檔由呼叫端（save_frozen_array）刪掉。"""
    from numpy.lib import format as npy_format
    with open(path, "wb") as f:
        npy_format.write_array(_WriteOnly(f), a, allow_pickle=False)
        f.flush()
        os.fsync(f.fileno())                       # 磁碟滿有時到 fsync 才報（延後配置）：在換上去之前就知道


def save_frozen_array(arr, stem: str, directory: Optional[str] = None) -> str:
    """一段資料存進 frozen_data_dir()（directory＝別的資料夾，selftest 用）：檔名 <stem>_<資料內容雜湊>.npy，同一份資料只存一個
    （已經有、讀回來一模一樣就直接用；同名但內容不對、讀不了的重寫）。回傳路徑。
    存完讀回來確認每個位元都一樣才回傳（2026-10-25 使用者決定 U10：刪掉來源之前要確定衍生訊號的資料真的存好了）；存不了（資料夾唯讀、
    磁碟滿、同名的檔案或資料夾擋住…）丟帶 errno 的 OSError（_write_npy），寫到一半的暫存檔當場刪掉。"""
    a = np.ascontiguousarray(np.asarray(arr, dtype=float)).ravel()
    d = directory or frozen_data_dir()
    os.makedirs(d, exist_ok=True)
    stem = re.sub(r"[^0-9A-Za-z_.-]+", "_", str(stem or ""))[:40].strip("._") or "signal"
    digest = hashlib.blake2b(a.tobytes(), digest_size=10).hexdigest()
    path = os.path.join(d, f"{stem}_{digest}.npy")
    if _frozen_file_holds(path, a):
        return path
    tmp = path + f".{os.getpid()}.tmp.npy"
    try:
        _write_npy(tmp, a)
        os.replace(tmp, path)
    except BaseException:
        try:
            os.remove(tmp)                         # 磁碟滿時寫了一半：不留在資料夾裡占空間
        except OSError:
            pass
        raise
    if not _frozen_file_holds(path, a):
        raise OSError(errno.EIO, FROZEN_READBACK_MSG, path)
    return path


def frozen_write_probe(directory: str) -> None:
    """凍結資料夾寫得進去嗎：在資料夾裡建一個小檔、寫一個位元組、刪掉。唯讀、沒有權限、磁碟是唯讀的、同名的檔案擋在資料夾的位置…
    都丟 OSError（原因照實）。2026-10-25 使用者決定 U10「資料夾寫不進去就整個不刪」：要存的資料已經在資料夾裡、不用再寫時也照這個規則
    （_prepare_detach）。檔名符合 FROZEN_TMP_RE：萬一刪不掉，U9 的清理會清。"""
    p = os.path.join(directory, f"write-probe_{os.urandom(10).hex()}.npy.{os.getpid()}.tmp.npy")
    fd = os.open(p, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    try:
        os.write(fd, b"\0")
    finally:
        os.close(fd)
        try:
            os.remove(p)
        except OSError:
            pass


def write_json_atomic(path: str, obj) -> None:
    """設定 JSON（自動存檔、匯出設定）整個寫好才換上去：寫同一個資料夾裡的暫存檔、flush＋fsync，再 os.replace 蓋過去（原本的權限照舊）。
    寫到一半失敗（磁碟滿、超過檔案大小上限…）就刪掉暫存檔、原本的檔一個位元組都不動，再丟出 OSError——以前直接 open(path, "w") 覆寫，
    關閉時磁碟滿會把自動存檔截斷成半個 JSON，下次開啟讀不回來、什麼都沒有，U9 的清理接著把上次用到的凍結檔清掉，資料永久不見（2026-10-26）。
    path 是捷徑（symlink）就寫到它指的檔，捷徑本身不換掉。
    暫存檔建不了（資料夾不能寫入——檔案本身可以寫也一樣——、磁碟滿…）也一樣：丟 OSError、原本的檔一個位元組都不動，絕不直接覆寫
    （2026-10-26 第十輪：以前資料夾沒有權限時退回 open(path, "w")，先截斷再寫，磁碟又滿時把上一份自動存檔截斷成半個 JSON，
    U12 的對話框卻說上一份保持原樣）。自動存檔照 U12 問「照樣關閉／先不關」，匯出設定跳錯誤視窗。沒有權限時錯誤的檔名寫資料夾
    （真正寫不進去的是它；暫存檔名沒有意義）。"""
    target = os.path.realpath(path)
    folder = os.path.dirname(target) or "."
    tmp = os.path.join(folder, f".{os.path.basename(target)}.{os.getpid()}.{os.urandom(3).hex()}.tmp")
    try:
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0), 0o666)   # Windows：換行只由文字層轉一次
    except PermissionError as e:
        raise PermissionError(e.errno, e.strerror, folder) from None
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        try:
            os.chmod(tmp, os.stat(target).st_mode & 0o7777)   # 蓋過去的檔照原本的權限（open(path, "w") 也不改權限）
        except OSError:
            pass
        os.replace(tmp, target)
    except BaseException:
        try:
            os.remove(tmp)
        except OSError:
            pass
        raise


def _oserror_brief(e: OSError, folder: str) -> str:
    """OSError 的系統訊息，路徑在 folder（frozen 資料夾）裡就不重複寫整個路徑（錯誤視窗另有一行寫資料夾）：暫存檔、登記檔、資料夾本身
    只寫「[Errno n] 說明」，擋在 .npy 位置的東西寫它的檔名，資料夾外面的路徑照寫。好幾條衍生訊號同一個原因時就只寫一次。"""
    base = f"[Errno {e.errno}] {e.strerror}"
    p = getattr(e, "filename2", None) or e.filename        # os.replace 的 filename2＝目的地（擋在那裡的東西）
    if not p:
        return base
    p = str(p)
    fn, pn = os.path.normcase(os.path.abspath(folder)), os.path.normcase(os.path.abspath(p))
    if pn == fn:
        return base
    if os.path.dirname(pn) == fn:
        name = os.path.basename(p)
        return base if (name.endswith(".tmp.npy") or name.startswith(FROZEN_LOCK_PREFIX)) else f"{base}: '{name}'"
    return f"{base}: '{p}'"


def _blocked_by_file(e: OSError, folder: Optional[str] = None) -> bool:
    """「資料夾的位置被同名的檔案擋住」的 Windows 寫法（0.9.13 W3）：macOS 丟 ENOTDIR／EEXIST，Windows 對擋住的檔「裡面」的路徑
    丟的是 errno 2（No such file or directory，filename＝裡面的暫存檔）。錯誤路徑的上層（不含它自己）或 frozen 資料夾本身往上找，
    有一層是現存的「檔案」就是被擋住。"""
    cands = [(getattr(e, "filename", None), True), (getattr(e, "filename2", None), True), (folder, False)]
    for p, parents_only in cands:
        if not p:
            continue
        try:
            cur = os.path.abspath(str(p))
            if parents_only:
                cur = os.path.dirname(cur)
            for _ in range(256):
                if not cur:
                    break
                if os.path.isfile(cur):
                    return True
                parent = os.path.dirname(cur)
                if parent == cur:
                    break
                cur = parent
        except Exception:
            continue
    return False


def frozen_error_text(e: BaseException, folder: Optional[str] = None) -> str:
    """凍結檔存不了的原因（U10 的錯誤視窗用）：常見的 OSError 換成看得懂的說法，括號裡附系統原本的訊息；其他的照原本的訊息。
    folder＝frozen 資料夾（_oserror_brief：路徑在資料夾裡就不重複寫）。"""
    raw = str(e) or type(e).__name__
    desc = None
    if isinstance(e, OSError):
        no = e.errno
        if folder and no is not None and e.strerror:
            raw = _oserror_brief(e, folder)
        dst = getattr(e, "filename2", None)                  # os.replace 的目的地：Windows 上被資料夾擋住是 PermissionError（WinError 5）
        if e.strerror == FROZEN_READBACK_MSG:
            desc = tr("存進去的資料讀回來不一樣")
        elif (isinstance(e, (FileExistsError, NotADirectoryError, IsADirectoryError)) or no in (errno.EEXIST, errno.ENOTDIR, errno.EISDIR)
              or (dst and os.path.isdir(str(dst))) or (no == errno.ENOENT and _blocked_by_file(e, folder))):   # W3：Windows 丟 errno 2
            desc = tr("有同名的檔案或資料夾擋住")
        elif isinstance(e, PermissionError) or no in (errno.EACCES, errno.EPERM):
            desc = tr("沒有寫入權限")
        elif no == errno.EROFS:
            desc = tr("磁碟是唯讀的")
        elif no == errno.ENOSPC:
            desc = tr("磁碟空間不足")
        elif no is not None and no == getattr(errno, "EDQUOT", None):
            desc = tr("超過磁碟配額")
        elif no == errno.EFBIG:
            desc = tr("檔案超過大小上限")                # 檔案系統（例如 FAT32 的 4 GB）或系統（ulimit -f）允許的單一檔案大小
    return tr("{desc}（{raw}）").format(desc=desc, raw=raw) if desc else raw


def frozen_stem(name: str) -> str:
    """凍結檔的檔名 → 存檔時的 <名稱>（去掉 _<雜湊>.npy）；不是這個格式就去掉副檔名。"""
    name = _path_basename(name)
    return name[:-25] if FROZEN_FILE_RE.match(name) else os.path.splitext(name)[0]


def encode_frozen_array(arr) -> dict:
    """「匯出設定」帶著的獨立訊號資料：float64（little-endian）壓縮後轉 base64，讀回來一模一樣（NaN、±Inf、-0 都照原值）。"""
    a = np.ascontiguousarray(np.asarray(arr, dtype=float)).ravel()
    raw = a.astype("<f8", copy=False).tobytes()
    return {"dtype": "<f8", "n": int(a.size), "zlib_b64": base64.b64encode(zlib.compress(raw, 6)).decode("ascii")}


def decode_frozen_array(enc) -> np.ndarray:
    """encode_frozen_array 的反向；格式不對、長度不符就丟 ValueError。"""
    if not isinstance(enc, dict) or str(enc.get("dtype", "<f8")) != "<f8" or not isinstance(enc.get("zlib_b64"), str):
        raise ValueError("frozen data: bad format")
    a = np.frombuffer(zlib.decompress(base64.b64decode(enc["zlib_b64"])), dtype="<f8").astype(float)
    if "n" in enc and int(a.size) != int(enc["n"]):
        raise ValueError(f"frozen data: {a.size} samples, expected {enc['n']}")
    return a


def frozen_refs(items) -> Set[str]:
    """訊號（Signal 或 to_dict 的 dict）用到的凍結檔檔名（一律轉小寫）。只看檔名：資料夾換了名字、別台電腦存的路徑也算用到（寧可多留）。
    不分大小寫：macOS（APFS 預設）、Windows 的檔名不分大小寫，名稱只差大小寫、資料一樣的兩條訊號共用同一個檔（save_frozen_array 看到
    「已經有」就直接用，路徑是自己的寫法）；分大小寫的檔案系統上多留一個也不會錯。"""
    out: Set[str] = set()
    for it in items or ():
        p = it.get("path") if isinstance(it, dict) else getattr(it, "path", None)
        name = _path_basename(p)
        if name and FROZEN_FILE_RE.match(name):
            out.add(name.lower())
    return out


FROZEN_NAME_SCAN_RE = re.compile(r"[0-9A-Za-z_.-]+_[0-9a-f]{20}\.npy")      # 文字裡的凍結檔檔名（FROZEN_FILE_RE 不含頭尾）


def frozen_names_in(obj) -> Set[str]:
    """設定檔裡一條訊號（或任何 JSON 值）的文字裡出現的凍結檔檔名（一律轉小寫）。欄位型別不對、讀不成訊號的那一條（"path" 不是文字、
    不是 JSON 物件…）也知道它用到哪個凍結檔（2026-10-26 第十二輪）；寧可多算：文字裡有 <名稱>_<20 位雜湊>.npy 就算。"""
    try:
        text = json.dumps(obj, ensure_ascii=False, default=str)
    except Exception:
        text = str(obj)
    return {m.lower() for m in FROZEN_NAME_SCAN_RE.findall(text)}


def frozen_local_twin(path) -> Optional[str]:
    """凍結檔 path 不在（別的帳號、別台電腦存的路徑：換電腦、帳號名稱不同…）時，這台電腦 frozen_data_dir() 裡同名、內容也對得上檔名裡的
    雜湊的那個檔（save_frozen_array 的檔名＝<名稱>_<資料內容的雜湊>.npy：同名而且雜湊對得上＝同一份資料）。不是凍結檔的檔名、沒有、讀不了、
    內容和雜湊對不上都回 None。frozen_refs 本來就只看檔名（別台電腦存的路徑也算用到這台的那個檔），還原時也照同一個規則找（2026-10-26 第十二輪：
    以前這種訊號開啟時默默略過，第一次關閉就把這台的那個檔當成沒人用到清掉）。"""
    name = _path_basename(path)
    if not FROZEN_FILE_RE.match(name):
        return None
    cand = os.path.join(frozen_data_dir(), name)
    try:
        if not os.path.isfile(cand):
            return None
        a = np.load(cand, allow_pickle=False)
        if not isinstance(a, np.ndarray) or a.ndim != 1 or a.dtype.kind != "f":
            return None
        b = np.ascontiguousarray(np.asarray(a, dtype=float)).ravel()
    except Exception:
        return None
    return cand if hashlib.blake2b(b.tobytes(), digest_size=10).hexdigest() == name[-24:-4] else None


def settings_entry_name(d) -> str:
    """設定檔裡一條訊號給使用者看的名稱（讀不成訊號的那一條也要說得出是哪一條）：label、key、檔名，都沒有就是那段文字（太長截掉）。"""
    if isinstance(d, dict):
        for k in ("label", "key"):
            v = d.get(k)
            if isinstance(v, str) and v.strip():
                return v
        p = d.get("path")
        if isinstance(p, str) and p.strip():
            return _path_basename(p)
    t = str(d)
    return t if len(t) <= 60 else t[:59] + "…"


def signal_entry_problem(d) -> Optional[str]:
    """設定檔裡一條訊號讀不成 Signal（Signal.from_dict 丟例外）時，給使用者看的原因：不是 JSON 物件、少了 "key"／"path"、
    "panel"／"dk" 不是整數、"lw" 不是數字；看不出來是哪一欄回 None（呼叫端寫例外原本的訊息）。純函式。"""
    if not isinstance(d, dict):
        return tr('設定檔的 "{key}" 不是 JSON 物件').format(key="signals[]")
    for k in ("key", "path"):
        if k not in d:
            return tr('設定檔少了 "{key}"').format(key=f"signals[].{k}")
    for k in ("panel", "dk"):
        if k in d:
            try:
                int(d[k])
            except (TypeError, ValueError, OverflowError):
                return tr('設定檔的 "{key}" 不是整數').format(key=f"signals[].{k}")
    lw = d.get("lw")
    if lw not in (None, "", 0):
        try:
            float(lw)
        except (TypeError, ValueError):
            return tr('設定檔的 "{key}" 不是數字').format(key="signals[].lw")
    return None


def settings_problem(cfg) -> Optional[str]:
    """設定 dict 還原不了的結構問題（給使用者看的原因）；沒問題回 None。純函式，不改 cfg。
    看的是會讓 apply_settings 整個失敗、或一條訊號都還原不了的地方：不是 JSON 物件、"version" 不是整數、"view" 不是物件、
    "signals" 不是清單或某一條的 "uid" 不是整數、"annotations"／"datatips"／"folder_history" 是數字（不能逐項讀）、"root" 不是文字。
    自動存檔（U13）：開啟時有這種問題就照「讀不了」處理——提示、另存備份、從空的開始；凍結檔的清理（不清）和關閉時蓋掉之前先備份也照同一個標準
    （2026-10-26 第十一輪：以前 "view" 不是物件時開啟只記 log、從空的開始、不提示，關閉時把它整個蓋掉，接著清掉上次用到的凍結檔，資料永久不見）。"""
    if not isinstance(cfg, dict):
        return tr("設定檔不是 JSON 物件")
    try:
        int(cfg.get("version") or 0)
    except (TypeError, ValueError, OverflowError):
        return tr('設定檔的 "{key}" 不是整數').format(key="version")
    view, sigs, root = cfg.get("view"), cfg.get("signals"), cfg.get("root")
    if view and not isinstance(view, dict):
        return tr('設定檔的 "{key}" 不是 JSON 物件').format(key="view")
    if sigs and not isinstance(sigs, list):
        return tr('設定檔的 "{key}" 不是清單').format(key="signals")
    for d in sigs or []:
        if isinstance(d, dict):
            try:
                int(d.get("uid") or 0)
            except (TypeError, ValueError, OverflowError):
                return tr('設定檔的 "{key}" 不是整數').format(key="signals[].uid")
    for key in ("annotations", "datatips", "folder_history"):
        v = cfg.get(key)
        if v and isinstance(v, (int, float)):              # 數字（含 true）：逐項讀的時候整個失敗
            return tr('設定檔的 "{key}" 不是清單').format(key=key)
    if root and not isinstance(root, str):
        return tr('設定檔的 "{key}" 不是文字').format(key="root")
    return None


def frozen_refs_in_file(path: str) -> Optional[Set[str]]:
    """設定檔（自動存檔）用到的凍結檔檔名；沒有這個檔＝空集合；讀不了、格式不對（settings_problem）＝None（不知道它用到哪些：呼叫端不清）。
    捷徑（symlink）在、它指的檔卻不在（外接磁碟、網路磁碟沒接上…）也是 None：那個檔只是現在讀不到，上次的工作階段可能就在裡面
    （2026-10-26 第十一輪：以前當成「沒有自動存檔」，啟動時的清理把上次用到的凍結檔全部刪掉）。"""
    try:
        with open(path, "r", encoding="utf-8") as f:
            cfg = json.load(f)
    except FileNotFoundError:
        return None if os.path.islink(path) else set()
    except Exception:
        return None
    if settings_problem(cfg):
        return None
    return frozen_refs(cfg.get("signals") or [])


def signal_origin(s) -> Tuple[str, Optional[str], str]:
    """訊號的資料從哪裡來：(檔案路徑、欄位、擷取範圍)。剪貼簿裡的衍生訊號記下它的來源 I、Q 是哪兩條（CLIP_SRC_KEY，見 source_identity）：
    貼上時同一個 uid 的訊號已經換成別的（例如「匯入設定」換掉了工作階段，設定檔裡的 uid 又從 1 開始），就當成來源已經不在（U11／U16），
    不會接到別的訊號上。衍生訊號沒有檔案路徑，這裡一律是 ('', None, '')——它的身分要用 source_identity。"""
    p = str((s.get("path") if isinstance(s, dict) else getattr(s, "path", "")) or "")
    col = s.get("column") if isinstance(s, dict) else getattr(s, "column", None)
    roi = s.get("roi") if isinstance(s, dict) else getattr(s, "roi", "")
    return (os.path.normcase(os.path.abspath(p)) if p else "", None if col is None else str(col), str(roi or ""))


SOURCE_IDENTITY_MAX_DEPTH = 32            # 衍生訊號的來源鏈最多往下記幾層（手改設定檔造成的循環來源才會碰到）


def source_identity(s, _depth: int = 0) -> tuple:
    """剪貼簿裡衍生訊號的來源「是哪一條」（CLIP_SRC_KEY；只在記憶體，貼上時用 same_source_identity 比）。
    一般訊號＝signal_origin（檔案路徑、欄位、擷取範圍）。來源自己也是衍生訊號時（前處理可以接在衍生訊號後面：低通之後再取包絡）它沒有
    檔案路徑，光看 signal_origin 任何一條衍生訊號都「對得上」——改成記它的種類（derive）、擷取範圍、前處理參數，再一層一層記它自己的來源，
    一直到最底層的一般訊號（2026-10-27 0.9.10 深度審查第 1 輪：「匯入設定」讓 lowpass(m b) 拿到 lowpass(m a) 的 uid 之後貼上複製的包絡，
    會安靜地接到不相干的 lowpass(m b) 上、畫出別的資料；U11 的規則延伸到來源是衍生訊號的情況）。來源找不到（算不出來）就記它的 src 字串；
    超過深度上限（循環）記成 cycle。"""
    derive = str((s.get("derive") if isinstance(s, dict) else getattr(s, "derive", "")) or "")
    if not derive:
        return signal_origin(s)
    if _depth >= SOURCE_IDENTITY_MAX_DEPTH:
        return ("derived", derive, "cycle")
    roi = str(getattr(s, "roi", "") or "")
    pp = getattr(s, "pp", None) or {}
    try:
        pp_c = json.dumps(pp, sort_keys=True, ensure_ascii=False, default=str)
    except Exception:
        pp_c = str(pp)
    srcs = s.sources() if hasattr(s, "sources") else None
    if srcs is None:
        chain: tuple = ("missing", str(getattr(s, "src", "") or ""))
    else:
        chain = tuple(source_identity(x, _depth + 1) for x in srcs)
    return ("derived", derive, roi, pp_c, chain)


def same_source_identity(a, b) -> bool:
    """兩個 source_identity（或剪貼簿裡存著的副本：tuple／list 混用）是不是同一條來源。"""
    try:
        return json.dumps(a, ensure_ascii=False, default=str) == json.dumps(b, ensure_ascii=False, default=str)
    except Exception:
        return False


def signal_waiting(s, _depth: int = 0) -> bool:
    """B1（2026-10-28 使用者決定）：訊號 s 正在等來源檔案回來——它自己是檔案不在的佔位訊號（Signal.missing_file），或它的來源鏈裡
    （衍生訊號的來源、來源的來源…）有一條是。這種訊號留在清單、不畫、參數全留，檔案回來就讀進來、重算。來源找不到（被移除）的不算
    （那是「missing」：0.9.9 起就是空的）。手改設定檔造成的循環來源：超過深度上限就當成不是。"""
    if getattr(s, "missing_file", False):
        return True
    if not getattr(s, "derive", "") or _depth >= SOURCE_IDENTITY_MAX_DEPTH:
        return False
    srcs = s.sources() if hasattr(s, "sources") else None
    return bool(srcs) and any(signal_waiting(x, _depth + 1) for x in srcs)


def signal_waits_unreadable(s, _depth: int = 0) -> bool:
    """s 在等的佔位訊號（自己、或來源鏈裡的）全部都是「檔案在卻讀不了」的（load_error 有原因；2026-10-29 使用者決定一樣留佔位）——
    說明時寫「讀不了」而不是「檔案不在」（第二輪行為驗證 R2-2）。不在等、或有一條是檔案真的不在的回 False。"""
    if getattr(s, "missing_file", False):
        return bool(getattr(s, "load_error", None))
    if not getattr(s, "derive", "") or _depth >= SOURCE_IDENTITY_MAX_DEPTH:
        return False
    waits = [x for x in (s.sources() if hasattr(s, "sources") else None) or [] if signal_waiting(x, _depth + 1)]
    return bool(waits) and all(signal_waits_unreadable(x, _depth + 1) for x in waits)


# --- 讀不了的自動存檔（2026-10-26 使用者決定 U13、U15）-------------------------------------------------------------------
# 啟動時自動存檔在、卻讀不了（被別的程式寫壞、截斷、沒有讀取權限）：提示、另存一份備份（<名稱>.bad.json；已經有就加時間，
# 舊的備份一律不蓋掉）、這次從空的開始。U15（取代 U13「掃描備份文字裡的檔名」）：自動存檔旁邊只要還有任何一份備份
# （<名稱>.bad*.json），凍結檔的自動清理一個檔都不刪；使用者把備份全部刪掉之後才照常清（壞掉的檔可能截斷在 "signals" 之前、
# 整份變成 NUL，文字裡看不到的檔名一樣是上次的工作階段用到的）。


def _autosave_stem(base: str) -> str:
    return base[:-5] if base.lower().endswith(".json") else base


def autosave_backup_pattern(path: str) -> str:
    """自動存檔 path 的備份檔名樣式（提示、log 寫給使用者看）：<名稱>.bad*.json，例如 .signal_viewer_last.bad*.json。"""
    return _autosave_stem(os.path.basename(os.path.abspath(path))) + ".bad*.json"


def autosave_pending_aside_path(path: Optional[str] = None) -> str:
    """「還欠一次另存」的紀錄檔（F-R2D2N，2026-10-30 14:xx 使用者決定）：自動存檔 path（預設 AUTOSAVE_PATH）旁邊的 <名稱>.pending-aside.json——
    另存備份（<名稱>.bad*.json）失敗時記下哪一份、為什麼（SignalViewer._aside_note_fail），成功了就拿掉；下次開啟時先補做另存（_retry_pending_asides），
    成功了才照常改寫或照「留最近 3 個版本」刪那份備份，還是失敗就提示並不動它。名稱不符合 .bad*.json（不算 U15 的備份）、也不是 .backup*.json（不算版本備份）。"""
    p = AUTOSAVE_PATH if path is None else path
    folder, base = os.path.split(os.path.abspath(p))
    return os.path.join(folder, _autosave_stem(base) + ".pending-aside.json")


def read_pending_asides(path: Optional[str] = None) -> List[dict]:
    """紀錄檔（autosave_pending_aside_path）裡還欠著的另存：[{"src": 那份備份的路徑, "label": 哪一種, "reason": 上次失敗的原因, "time": 記下的時間}]；
    沒有、讀不了、結構不對回 []（不丟例外）。"""
    try:
        with open(autosave_pending_aside_path(path), "rb") as f:
            d = json.loads(f.read().decode("utf-8"))
        items = d.get("items") if isinstance(d, dict) else None
        return [it for it in (items or []) if isinstance(it, dict) and isinstance(it.get("src"), str) and it.get("src")]
    except Exception:
        return []


def autosave_backup_paths(path: str) -> Optional[List[str]]:
    """自動存檔 path 讀不了時留下的備份：同一個資料夾裡名稱符合 <名稱>.bad*.json 的（backup_bad_autosave 存的 <名稱>.bad.json、
    <名稱>.bad-<時間>.json，也包括使用者複製、改名的，例如 Finder 的「<名稱>.bad 拷貝.json」；不分大小寫——寧可多算）。
    資料夾列不出來回 None（不知道有沒有備份：呼叫端不清凍結檔）。"""
    folder, base = os.path.split(os.path.abspath(path))
    rx = re.compile(re.escape(_autosave_stem(base)) + r"\.bad.*\.json", re.IGNORECASE | re.DOTALL)
    try:
        names = os.listdir(folder)
    except OSError:
        return None
    return sorted(os.path.join(folder, n) for n in names if rx.fullmatch(n))


# --- B3（2026-10-28 使用者決定，0.9.13）：這版寫的自動存檔備份、被舊版改寫過的偵測 ---------------------------------------------
# 每次寫自動存檔成功之後再寫一份一模一樣的備份（內容含 app_version）。用舊版開過又關掉時，舊版把自動存檔改寫成沒有新鍵
# （前處理結果、軸名稱／標題、眼圖與錯誤率比對的預設…）的版本；下次這版開啟時自動存檔的 app_version 比備份的舊 → 問一次
# 「用備份還原／用現在的檔」。凍結檔的清理把備份用到的也算有人用到；備份讀不了就不清。名稱不符合 U15 的 <名稱>.bad*.json。
# 0.9.14（2026-10-29 18:1x 使用者決定，R3-D2）：每個版本各留一份自己的備份 <名稱>.backup-<版本>.json，留最近 3 個版本（更舊的自動刪掉，
# 只有它們用到的獨立訊號資料照常清）。0.9.13 寫的 <名稱>.backup.json 只讀、不寫：0.9.13 靠這個檔判斷 C6（比它新的版本寫了這個檔，0.9.13
# 就不再替自己留備份——三個版本交替時中間那版的工作階段沒有備份），它算裡面 app_version 那一版（0.9.13）的備份，一樣照版本留最近 3 個。
AUTOSAVE_VERSION_BACKUP_SUFFIX = ".backup.json"          # 0.9.13 的名稱（沒有版本號）：0.9.14 起只讀、不寫
AUTOSAVE_BACKUP_KEEP_VERSIONS = 3                         # 留最近幾個版本的備份（2026-10-29 18:1x 使用者決定：涵蓋新版、這版、舊版交替使用）


def autosave_backup_version_part(v) -> str:
    """版本號放進備份檔名的寫法（0.9.14）：英數字、點、底線、減號照留，其他字元換成底線；空的寫 0。"""
    s = re.sub(r"[^0-9A-Za-z._-]", "_", str(v if v is not None else "").strip())
    return s or "0"


def autosave_version_backup_path(path: Optional[str] = None, version: Optional[str] = None) -> str:
    """自動存檔 path（預設 AUTOSAVE_PATH）旁邊 version 那一版（預設這版 APP_VERSION）留的備份：<名稱>.backup-<版本>.json
    （例如 .signal_viewer_last.backup-0.9.14.json；0.9.14 起每個版本各留一份自己的，2026-10-29 18:1x 使用者決定。0.9.13 是沒有版本號的
    <名稱>.backup.json——autosave_legacy_backup_path）。"""
    p = AUTOSAVE_PATH if path is None else path
    folder, base = os.path.split(os.path.abspath(p))
    v = APP_VERSION if version is None else version
    return os.path.join(folder, f"{_autosave_stem(base)}.backup-{autosave_backup_version_part(v)}.json")


def autosave_legacy_backup_path(path: Optional[str] = None) -> str:
    """0.9.13 寫的備份：<名稱>.backup.json（沒有版本號；0.9.14 起只讀、不寫——算裡面 app_version 那一版的備份）。"""
    p = AUTOSAVE_PATH if path is None else path
    folder, base = os.path.split(os.path.abspath(p))
    return os.path.join(folder, _autosave_stem(base) + AUTOSAVE_VERSION_BACKUP_SUFFIX)


def parse_saved_time(v) -> Optional[float]:
    """設定檔的 saved（dump_settings：time.strftime("%Y-%m-%d %H:%M:%S")，寫檔那台機器的當地時間）→ 秒數（time.mktime）；
    沒有、不是文字、不是這個格式（手改、別的程式寫的）、日期不對回 None。"""
    if not isinstance(v, str):
        return None
    try:
        return time.mktime(time.strptime(v.strip(), "%Y-%m-%d %H:%M:%S"))
    except (ValueError, OverflowError):
        return None


def _same_file_path(a: Optional[str], b: Optional[str]) -> bool:
    """兩個路徑是不是同一個位置（不解析捷徑；Windows 不分大小寫）。"""
    if not a or not b:
        return False
    return os.path.normcase(os.path.abspath(a)) == os.path.normcase(os.path.abspath(b))


class VersionBackup:
    """自動存檔旁邊的一份版本備份（version_backups；0.9.14）。path＝檔案；legacy＝0.9.13 的 <名稱>.backup.json；name_version＝檔名裡的版本
    （每版各自的檔；0.9.13 的是空的）；canonical＝名稱就是 DSV 寫的那種（大小寫一樣）；cfg／why＝read_settings_json 的結果（讀不了＝None、原因）。"""
    __slots__ = ("path", "legacy", "name_version", "canonical", "cfg", "why")

    def __init__(self, path: str, legacy: bool, name_version: str, canonical: bool, cfg: Optional[dict], why: Optional[str]):
        self.path, self.legacy, self.name_version, self.canonical, self.cfg, self.why = path, legacy, name_version, canonical, cfg, why

    @property
    def version(self) -> Optional[str]:
        """這份是哪一版的備份：每版各自的檔＝檔名的版本；0.9.13 的 .backup.json＝裡面的 app_version（讀不了、沒寫＝None：不知道）。"""
        if not self.legacy:
            return self.name_version
        v = self.cfg.get("app_version") if self.cfg is not None else None
        return None if v is None or str(v).strip() == "" else str(v)

    @property
    def saved(self) -> str:
        return str((self.cfg or {}).get("saved") or "?")

    @property
    def saved_time(self) -> float:
        """這份備份是什麼時候寫的（秒數）——B3／U13 從候選裡挑「最後一次工作」的那份用（pick_version_backup；2026-10-29 22:1x 使用者決定）。
        用內容裡的 saved（dump_settings 寫的 "%Y-%m-%d %H:%M:%S"，寫檔那台機器的當地時間；問句寫的也是它）；沒寫、讀不出來（不是文字、
        不是這個格式、日期不對）就改用檔案的修改時間（os.path.getmtime）；連修改時間都拿不到算最舊。"""
        t = parse_saved_time((self.cfg or {}).get("saved"))
        if t is not None:
            return t
        try:
            return os.path.getmtime(self.path)
        except (OSError, ValueError, OverflowError):
            return float("-inf")

    @property
    def when(self) -> str:
        """問句、提示寫的「什麼時候寫的」：內容裡的 saved；沒寫、讀不出來時照實寫檔案的修改時間（挑哪一份時用的也是它，saved_time）。"""
        if parse_saved_time((self.cfg or {}).get("saved")) is not None:
            return str(self.cfg.get("saved")).strip()
        t = self.saved_time
        if t == float("-inf"):
            return "?"
        try:
            return tr("檔案的修改時間 {time}").format(time=time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(t)))
        except (ValueError, OverflowError, OSError):
            return "?"

    @property
    def usable(self) -> bool:
        """讀得了、名稱是 DSV 寫的那種、知道是哪一版（每版各自的檔：內容的 app_version 和檔名的版本對得上；0.9.13 的檔：寫著 app_version）——
        才拿來問、才會照「留最近 3 個版本」刪；其他的（使用者改過名、複製來的、讀不了的）不問、不刪，凍結檔的清理照樣算它用到的（讀不了就不清）。"""
        if self.cfg is None or not self.canonical or self.version is None:
            return False
        return self.legacy or version_tuple(self.cfg.get("app_version")) == version_tuple(self.name_version)

    def __repr__(self) -> str:
        return f"VersionBackup({os.path.basename(self.path)!r}, version={self.version!r}, usable={self.usable})"


def version_backups(path: Optional[str] = None) -> Optional[List["VersionBackup"]]:
    """自動存檔 path（預設 AUTOSAVE_PATH）旁邊的每一份版本備份（0.9.14）：每個版本各自的 <名稱>.backup-<版本>.json 和 0.9.13 的
    <名稱>.backup.json，照檔名排，每一份都讀一次（read_settings_json）。名稱比對不分大小寫（寧可多算：凍結檔的清理把每一份都算有人用到）；
    同名的資料夾也列出來（讀不了：不問、不刪、清理這次不清）。資料夾列不出來回 None（不知道有哪些：呼叫端不清、不刪）。"""
    p = AUTOSAVE_PATH if path is None else path
    folder, base = os.path.split(os.path.abspath(p))
    stem = _autosave_stem(base)
    rx = re.compile(re.escape(stem) + r"\.backup(?:-([0-9A-Za-z._-]+))?\.json", re.IGNORECASE)
    try:
        names = os.listdir(folder)
    except OSError:
        return None
    out: List[VersionBackup] = []
    for n in sorted(names):
        m = rx.fullmatch(n)
        if not m:
            continue
        nv = m.group(1) or ""
        canonical = n == (f"{stem}.backup-{nv}.json" if nv else stem + AUTOSAVE_VERSION_BACKUP_SUFFIX)
        fp = os.path.join(folder, n)
        cfg, why = read_settings_json(fp)
        out.append(VersionBackup(fp, not nv, nv, canonical, cfg, why))
    return out


def pick_version_backup(backups: Sequence["VersionBackup"], this_version: str, autosave_version=None,
                        autosave_readable: bool = True) -> Tuple[Optional["VersionBackup"], List["VersionBackup"]]:
    """B3／U13 拿哪一份備份來問（0.9.14）：回 (要問的那一份或 None, 其他也找得回東西的備份)。只看 usable 的。
    2026-10-29 22:1x 使用者決定：候選裡拿**最後一次工作**的那一份——存檔時間最新的（VersionBackup.saved_time：內容裡的 saved，沒寫、讀不出來就用
    檔案的修改時間），不是版本最新的。例：0.9.14 → 0.9.13 加了東西 → 0.9.12 開過 → 回到 0.9.14：問 0.9.13 留的（0.9.13 加的東西在裡面；只有 0.9.14
    才有的設定可能不在）。存檔時間一樣（同一秒）時拿版本新的；同一版有兩份（每版各自的檔和 0.9.13 的 .backup.json）時用每版各自的那份。
    自動存檔讀得了（B3）：候選＝不比這版新、又比自動存檔新的（版本比大小；沒有 app_version 的自動存檔當最舊）；比這版新的版本寫的一律不拿來問
    （C6：回到那個版本時它自己會問）。其他＝其餘的候選（例如三個版本交替時版本最新、但比較早寫的那一份，可能就是這版自己的），照存檔時間新到舊。
    自動存檔讀不了（U13）：候選＝讀得了、不比這版新的；一份都沒有時照 0.9.13 拿比這版新的版本寫的來問（這版不會改寫它；幾份裡同樣拿存檔時間最新的）。
    其他＝其餘讀得了的（不比這版新的在前）。"""
    me = version_tuple(this_version)
    ok = [b for b in backups if b.usable]

    def key(b):
        return (b.saved_time, version_tuple(b.version), not b.legacy)
    if autosave_readable:
        av = version_tuple(autosave_version)
        cands = sorted((b for b in ok if av < version_tuple(b.version) <= me), key=key, reverse=True)
        return (cands[0], cands[1:]) if cands else (None, [])
    older = sorted((b for b in ok if version_tuple(b.version) <= me), key=key, reverse=True)
    newer = sorted((b for b in ok if version_tuple(b.version) > me), key=key, reverse=True)
    every = older + newer
    return (every[0], every[1:]) if every else (None, [])


def backups_to_prune(backups: Sequence["VersionBackup"], this_version: str, keep: int = AUTOSAVE_BACKUP_KEEP_VERSIONS) -> List[str]:
    """留最近 keep 個版本的備份（0.9.14，2026-10-29 18:1x 使用者決定）：這版寫好自己的備份之後要刪哪幾份。照版本排（每個版本算一個名額，
    這版自己算一個——就算檔還沒寫），比這版舊、又不在最新的 keep 個版本裡的那幾個版本的備份（0.9.13 的 .backup.json 算它裡面 app_version
    那一版）。這版自己的、比這版新的一律不刪；不 usable 的（讀不了、不知道是哪一版、檔名的版本和內容對不上、名稱不是 DSV 寫的那種）不刪、也不佔名額。"""
    me = version_tuple(this_version)
    ok = [b for b in backups if b.usable]
    ranked = sorted({version_tuple(b.version) for b in ok} | {me}, reverse=True)
    kept = set(ranked[:max(1, int(keep))]) | {me}
    return [b.path for b in ok if version_tuple(b.version) < me and version_tuple(b.version) not in kept]


def version_backup_refs(path: Optional[str] = None) -> Tuple[Optional[Set[str]], str]:
    """自動存檔 path 旁邊每一份版本備份（version_backups：每個版本各自的、0.9.13 的 .backup.json、比這版新的版本的都算）用到的凍結檔檔名——
    凍結檔的清理都算有人用到（0.9.14：每一份留著的備份都算）。任何一份讀不了（壞掉、截斷、結構不對、沒有讀取權限、捷徑指的檔不在、同名的資料夾）、
    資料夾列不出來 → (None, 原因)：這次不清（照 0.9.13：備份讀不了就不清）。"""
    baks = version_backups(path)
    if baks is None:
        folder = os.path.dirname(os.path.abspath(AUTOSAVE_PATH if path is None else path))
        return None, f"自動存檔所在的資料夾列不出來，不知道有哪些版本的備份（{folder}）"
    refs: Set[str] = set()
    for b in baks:
        r = frozen_refs_in_file(b.path)
        if r is None:
            return None, f"自動存檔的備份讀不了，不知道它用到哪些（{b.path}）"
        refs |= r
    return refs, ""


def version_tuple(v) -> Tuple[int, ...]:
    """app_version 字串（"0.9.13"）→ 可以比大小的 tuple；沒有、不是文字、不是數字的部分當 0（很舊的檔）；尾端的 0 不算（"0.9" ＝ "0.9.0"）。"""
    out: List[int] = []
    for part in str(v if v is not None else "").strip().split("."):
        m = re.match(r"\d+", part.strip())
        out.append(int(m.group(0)) if m else 0)
    while len(out) > 1 and out[-1] == 0:
        out.pop()
    return tuple(out) if out else (0,)


def newer_version_backup(path: str) -> Optional[str]:
    """C6（2026-10-29 使用者決定）：這版留的備份 path 是比這版（APP_VERSION）新的版本寫的就回它的 app_version，否則（沒有、讀不了、同一版、
    比較舊）回 None。較舊的版本不改寫較新版本寫的備份，也不拿它來問「上次的自動存檔被舊版改寫過」——之後回到新版本時，新版本照 B3 發現
    自動存檔被這個舊版改寫過、問要不要用備份。"""
    cfg, _why = read_settings_json(path)
    if cfg is None:
        return None
    ver = cfg.get("app_version")
    return str(ver) if ver is not None and version_tuple(ver) > version_tuple(APP_VERSION) else None


def read_settings_json(path: str) -> Tuple[Optional[dict], Optional[str]]:
    """讀一個設定 JSON（自動存檔、它的備份）：回 (dict, None)；不在、讀不了、結構不對（settings_problem）回 (None, 原因)。不丟例外。"""
    try:
        with open(path, "rb") as f:
            cfg = json.loads(f.read().decode("utf-8"))
    except Exception as e:
        return None, settings_read_error_text(e)
    why = settings_problem(cfg)
    return (None, why) if why else (cfg, None)


def older_version_rewrite(autosave: str, backup: str) -> Optional[Tuple[dict, dict]]:
    """B3：自動存檔是不是被比備份舊的版本改寫過——兩個檔都在、都讀得了，而且自動存檔的 app_version 比備份的舊（沒有 app_version 的當最舊）
    → 回 (自動存檔的 dict, 備份的 dict)；否則（沒有備份、任一個讀不了、同一版、自動存檔比較新）回 None。
    0.9.14 起啟動時的 B3 改用 version_backups／pick_version_backup（每個版本各一份備份，挑哪一份問）；這裡兩份之間的比較規則不變（selftest 照舊驗）。"""
    if not os.path.lexists(backup):
        return None
    a, _wa = read_settings_json(autosave)
    if a is None:
        return None
    b, _wb = read_settings_json(backup)
    if b is None:
        return None
    return (a, b) if version_tuple(a.get("app_version")) < version_tuple(b.get("app_version")) else None


def settings_prefs_only(cfg) -> bool:
    """設定 dict 只有偏好（「自動還原上次」關著時寫的自動存檔：view.autosave 是 false、沒有訊號、標註、資料提示）。
    B3（2026-10-29 使用者決定）：自動存檔和這版留的備份兩份都只有偏好時不問「用備份還原／用現在的檔」，照預設用現在的檔
    （問句講的前處理結果、軸名稱／標題…兩份裡都沒有）。"""
    if not isinstance(cfg, dict):
        return False
    view = cfg.get("view") if isinstance(cfg.get("view"), dict) else {}
    return view.get("autosave") is False and not cfg.get("signals") and not cfg.get("annotations") and not cfg.get("datatips")


def frozen_cleanup_blocker(autosave: str) -> Optional[str]:
    """凍結檔這次能不能清（U9 的清理之前問；別的 DSV 開著另外看）：不能清就回傳原因（記 log），可以清回 None。
    - 自動存檔讀不了（壞掉、結構不對、沒有讀取權限、捷徑指的檔不在）：不知道上次的工作階段用到哪些——不清；
    - 自動存檔所在的資料夾列不出來：不知道有沒有讀不了的自動存檔留下的備份——不清；
    - U15（2026-10-26 使用者決定）：自動存檔旁邊還有任何一份備份（<名稱>.bad*.json）——一個檔都不刪，備份全部刪掉之後才照常清。"""
    if frozen_refs_in_file(autosave) is None:
        if os.path.islink(autosave) and not os.path.exists(autosave):
            return f"自動存檔是捷徑、它指的檔不在（外接磁碟沒接上？），不知道它用到哪些（{autosave}）"
        return f"自動存檔讀不了，不知道它用到哪些（{autosave}）"
    baks = autosave_backup_paths(autosave)
    if baks is None:
        return f"自動存檔所在的資料夾列不出來，不知道有沒有讀不了的自動存檔留下的備份（{os.path.dirname(os.path.abspath(autosave))}）"
    if baks:
        names = ", ".join(os.path.basename(p) for p in baks[:4]) + (" …" if len(baks) > 4 else "")
        return (f"讀不了的自動存檔留下的備份還在（{len(baks)} 份：{names}）——備份全部刪掉之前一個凍結檔都不刪"
                f"（U15；{autosave_backup_pattern(autosave)}）")
    return None


def backup_bad_autosave(path: str, now: Optional[float] = None, stem_of: Optional[str] = None) -> str:
    """讀不了的自動存檔另存一份備份（U13），回傳備份的路徑；備份不了（資料夾不能寫入、磁碟滿…）丟 OSError，寫到一半的備份刪掉。
    名稱 <名稱>.bad.json；已經有（以前的備份）就不蓋掉，改用 <名稱>.bad-<年月日-時分秒>.json（再撞名加 -2、-3…）。和某一份舊備份
    一模一樣（例如上次開啟後沒關好，壞檔還在）就不再多存一份、回傳那一份。複製位元組（原本的檔留在原處：捷徑照舊，下次寫自動存檔時換掉）；
    沒有讀取權限、不能複製時把檔案本身改名成備份（不然下次寫自動存檔就把它蓋掉了）。
    自動存檔是捷徑（symlink）、它指的檔不在（外接磁碟、網路磁碟沒接上…）：把捷徑本身改名成備份（還是指著原本那個檔；那個檔一個位元組都不動），
    原本的位置空出來，之後寫的自動存檔是一份新的檔，不會在那個檔回來時寫穿捷徑把它蓋掉（2026-10-26 第十一輪）。
    stem_of＝備份的名稱照這個自動存檔取（0.9.13：這版留的備份 .backup.json 讀不了時，另存成自動存檔的 <名稱>.bad*.json——U15 才認得）。"""
    folder, base = os.path.split(os.path.abspath(path))
    like = path if stem_of is None else stem_of
    stem = _autosave_stem(os.path.basename(os.path.abspath(like)))
    try:
        with open(path, "rb") as f:
            data: Optional[bytes] = f.read()
    except FileNotFoundError:
        if not os.path.islink(path):
            raise
        data = None                                        # 捷徑在、指的檔不在：捷徑本身改名成備份
    except OSError:
        data = None
    if data is not None:
        for old in autosave_backup_paths(like) or []:
            try:
                with open(old, "rb") as f:
                    if f.read() == data:
                        return old
            except OSError:
                continue
    stamp = time.strftime("%Y%m%d-%H%M%S", time.localtime(now))
    names = [f"{stem}.bad.json"] + [f"{stem}.bad-{stamp}{'' if k == 1 else f'-{k}'}.json" for k in range(1, 100)]
    for name in names:
        dst = os.path.join(folder, name)
        if os.path.lexists(dst):
            continue                                       # 舊的備份一律不蓋掉
        if data is None:
            os.rename(path, dst)
            return dst
        try:
            fd = os.open(dst, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_BINARY", 0), 0o666)
        except FileExistsError:
            continue
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(data)
                f.flush()
                os.fsync(f.fileno())
        except BaseException:
            try:
                os.remove(dst)                             # 寫到一半（磁碟滿）：不留半份備份
            except OSError:
                pass
            raise
        return dst
    raise OSError(errno.EEXIST, os.strerror(errno.EEXIST), os.path.join(folder, names[-1]))


def file_readable(path: str) -> bool:
    """這個檔現在真的讀得了嗎（開檔、讀一個位元組）。os.access 在 Windows 不看 ACL（只看唯讀屬性，永遠說讀得了），
    所以不用它（第一輪 Windows 驗證 W14-1：自動存檔沒有讀取權限、整個改名成備份之後，「先修好它的權限」那句在 Windows 從不出現）。"""
    try:
        with open(path, "rb") as f:
            f.read(1)
        return True
    except OSError:
        return False


# --- 關閉時提醒還有檔案沒處理（2026-10-30 使用者決定 00:5x、09:1x）--------------------------------------------------------
# 關閉 DSV 時，只要還有下列任一種就跳一個小提示、寫出檔案位置（按「確定」就關閉；沒有就不跳），每次關閉都提醒，直到使用者處理掉：
# ① 複製圖到剪貼簿失敗留下的 PNG（Windows；W13：使用者決定「留著，但每次關閉時都要說哪裡有東西未處理」）；
# ② 另存的舊備份／讀不了的自動存檔另存（<名稱>.bad*.json；U15：在的期間凍結檔一個都不清）；
# ③ 讀不了的版本備份（擋住凍結檔的清理）；④ 另存還欠著的備份（上次另存失敗、這次再試也失敗：另存成功之前不重寫、不刪它，F-R2D2N）。
# 只在使用者自己關閉時（視窗的關閉鈕、⌘Q／App 選單「結束」、Dock 的「結束」，Windows 的 Alt+F4／taskkill /PID）；結束訊號（SIGTERM：更新後重開，要 2 秒內存好結束）、
# Ctrl+Break、系統登出／關機（macOS 的 loginwindow 送的 quit、Windows 的 WM_QUERYENDSESSION）不跳；
# 先寫好自動存檔再跳，提示過一段時間自己關掉（Windows 的 taskkill /PID 和關閉鈕分不出來，不能讓程式關不掉）；U12（自動存檔寫不進去的問句）照舊優先。
# 開啟時的問句（B3／U13）開著就按主視窗的關閉鈕（C1：什麼都不存）也跳（2026-10-31 15:3x 使用者決定 C2-2；提示照實寫這次什麼都沒存）。
# ① 兩個平台都看（2026-10-30 14:xx 使用者決定「Mac 也列」：macOS 複製失敗一樣留下 plotkit_clip_*.png）。
CLOSE_REMINDER_TIMEOUT_MS = 15000
CLOSE_REMINDER_MAX_LIST = 12   # 提示裡每一類最多列這麼多個檔，其餘寫「還有 N 個」（第二輪 Windows 驗證 W14R2-5：以前沒有上限，幾十個檔就比螢幕高、「確定」在螢幕外）


def close_reminder_items(autosave: Optional[str] = None, include_clip: Optional[bool] = None,
                         clip_folder: Optional[str] = None) -> Dict[str, List[str]]:
    """關閉時要提醒的檔（完整路徑）：{"clip": ①, "bad": ②, "vbak": ③, "pend": ④}。include_clip＝要不要看 ①（預設兩個平台都看：2026-10-30 14:xx
    使用者決定「Mac 也列」；以前只在 Windows 看）；clip_folder＝暫存資料夾（預設 tempfile.gettempdir()）。列不出來的那一類當成沒有（不擋關閉）。"""
    a = AUTOSAVE_PATH if autosave is None else autosave
    out: Dict[str, List[str]] = {"clip": [], "bad": [], "vbak": [], "pend": []}
    if include_clip is None:
        include_clip = True
    if include_clip:
        try:
            out["clip"] = list(pk.clipboard.leftover_clip_files(clip_folder))
        except Exception:
            pass
    out["bad"] = list(autosave_backup_paths(a) or [])
    try:
        out["vbak"] = [b.path for b in (version_backups(a) or []) if frozen_refs_in_file(b.path) is None]
    except Exception:
        pass
    try:
        out["pend"] = [it["src"] for it in read_pending_asides(a) if os.path.lexists(it["src"]) and not os.path.isdir(it["src"])]
    except Exception:
        pass
    return out


def close_reminder_lines(items: Dict[str, List[str]], saved: Optional[bool], pattern: str, timeout_ms: int = CLOSE_REMINDER_TIMEOUT_MS) -> List[str]:
    """關閉時提醒的內容（_remind_unhandled_files）：四類各自列出完整路徑（每類最多 CLOSE_REMINDER_MAX_LIST 個，其餘寫「還有 N 個（都在這個資料夾）」），
    最後一句照實寫自動存檔的狀態：saved＝True 已經存好、False＝U12 選了照樣關閉（這次的變更沒有存）、None＝開啟時的問句開著就關閉（C1：什麼都沒存）。"""
    sec = int(round(timeout_ms / 1000))
    lines = [tr("關閉之前提醒一下：下面這些檔還在，DSV 不會自己刪掉它們（處理掉之後就不再提醒）。")]

    def add(head: str, paths: List[str]) -> None:
        lines.extend(["", head])
        lines.extend("  " + p for p in paths[:CLOSE_REMINDER_MAX_LIST])
        if len(paths) > CLOSE_REMINDER_MAX_LIST:
            lines.append("  " + tr("……還有 {k} 個（都在這個資料夾裡：{folder}）").format(k=len(paths) - CLOSE_REMINDER_MAX_LIST,
                                                                        folder=os.path.dirname(paths[CLOSE_REMINDER_MAX_LIST])))
    if items.get("clip"):
        add(tr("複製圖到剪貼簿失敗時存下的圖（可以直接開來用；不需要了就刪掉）："), items["clip"])
    if items.get("bad"):
        add(tr("另存的舊備份、讀不了的自動存檔另存的備份（{pattern}；可以用「匯入設定」開啟，確認裡面的訊號之後再刪）。這些檔還在的期間，frozen 資料夾裡的獨立訊號資料檔一個都不會被自動清掉：").format(pattern=pattern),
            items["bad"])
    if items.get("vbak"):
        add(tr("讀不了的版本備份（有它在，frozen 資料夾裡沒人用到的獨立訊號資料檔就不會被自動清掉；修好或刪掉它之後才照常清）："), items["vbak"])
    if items.get("pend"):
        add(tr("另存還欠著的備份（上次另存失敗、這次再試也失敗：另存成功之前 DSV 不重寫、不刪它；讓它所在的資料夾可以寫入之後再開啟 DSV 會再試）："), items["pend"])
    if saved is None:
        last = tr("開啟時的問句還開著就關閉了：這次什麼都沒存（自動存檔、備份、凍結檔都不動，上次的工作階段下次開啟照樣還原）；這個提示 {sec} 秒後會自己關掉，DSV 接著關閉。")
    elif saved:
        last = tr("自動存檔已經存好了；這個提示 {sec} 秒後會自己關掉，DSV 接著關閉。")
    else:
        # U12 選了「照樣關閉」（自動存檔寫不進去）：照實寫這次的變更沒存
        last = tr("這次的變更沒有存（自動存檔寫不進去，你選了照樣關閉）；這個提示 {sec} 秒後會自己關掉，DSV 接著關閉。")
    lines += ["", last.format(sec=sec)]
    return lines


def file_identity(path: str) -> Optional[Tuple[int, int, int, int]]:
    """檔案現在是哪一份（裝置、inode、大小、修改時間）；不在、讀不到回 None。"""
    try:
        st = os.stat(path)
    except OSError:
        return None
    return (st.st_dev, st.st_ino, st.st_size, st.st_mtime_ns)


def strip_extended_prefix(p: str) -> str:
    """拿掉 Windows 延伸路徑前綴：\\\\?\\C:\\… → C:\\…、\\\\?\\UNC\\伺服器\\… → \\\\伺服器\\…；其他照原樣（0.9.13 W4）。"""
    if isinstance(p, str) and p.startswith("\\\\?\\"):
        p = p[4:]
        if p[:4].upper() == "UNC\\":
            p = "\\\\" + p[4:]
    return p


def readlink_plain(path: str) -> str:
    """os.readlink，但 Windows 回的 \\\\?\\C:\\… 延伸路徑前綴拿掉（0.9.13 W4）：給使用者看（捷徑指到哪裡）、比對都用這個。"""
    return strip_extended_prefix(os.readlink(path))


def autosave_identity(path: str) -> Tuple[Optional[tuple], Optional[Tuple[int, int, int, int]]]:
    """自動存檔現在是哪一份：(捷徑本身（指向哪裡、捷徑的裝置與 inode；不是捷徑＝None）, 它指的檔（file_identity；不在＝None）)。
    啟動時讀不了又備份不了（_autosave_unbacked）的那一份，關閉時拿來比：捷徑指的檔當時不在、現在回來了，也還是同一份（要先備份才能寫）。"""
    link = None
    try:
        if os.path.islink(path):
            st = os.lstat(path)
            link = (readlink_plain(path), st.st_dev, st.st_ino)
    except OSError:
        link = None
    return link, file_identity(path)


def same_unreadable_autosave(then, now) -> bool:
    """啟動時讀不了的自動存檔（then＝autosave_identity）現在還是不是同一份：捷徑換了、不再是捷徑就不是；同一個捷徑、當時指的檔不在
    （現在回來了也一樣）就是；其他照檔案本身（file_identity）比，當時讀不到身分的不算。"""
    if then is None or now is None:
        return False
    (l0, f0), (l1, f1) = then, now
    if l0 != l1:
        return False
    if l0 is not None and f0 is None:
        return True
    return f0 is not None and f0 == f1


def unwritable_folder(e: Optional[BaseException], path: str) -> Optional[str]:
    """寫 path 失敗的原因是「資料夾不能寫入」（write_json_atomic 在那個資料夾建不了暫存檔：PermissionError 的檔名是資料夾）時，
    回傳那個資料夾——檔案本身可能可以寫，只寫「沒有寫入權限」會讓人去改檔案的權限（2026-10-26 第十一輪）。和 path 所在的資料夾是同一個
    就用使用者看到的寫法（例如 /tmp 不寫成 /private/tmp）；捷徑指到別的資料夾就寫真的那個。不是這種錯誤回 None。"""
    if not isinstance(e, PermissionError):
        return None
    f = getattr(e, "filename", None)
    if not f or not os.path.isdir(str(f)):
        return None
    vis = os.path.dirname(os.path.abspath(path)) or "."
    try:
        if os.path.samefile(vis, str(f)):
            return vis
    except OSError:
        pass
    return str(f)


def oserror_text(e: Optional[BaseException]) -> str:
    """寫入、讀取失敗的原因（關閉時自動存檔寫不進去、讀不了的自動存檔備份不了…）：OSError 換成看得懂的說法加系統訊息，不寫檔名
    （對話框另有一行寫路徑；暫存檔名沒有意義）；其他例外照原本的訊息。"""
    if e is None:
        return ""
    if isinstance(e, OSError) and e.errno is not None and e.strerror:
        return frozen_error_text(OSError(e.errno, e.strerror))
    return str(e) or type(e).__name__


def settings_read_error_text(e: BaseException) -> str:
    """自動存檔讀不了的原因（U13）：不是完整的 JSON（被截斷、寫壞）、不是 JSON 物件、沒有讀取權限…
    讀的時候的權限錯誤寫「沒有讀取權限」（oserror_text 是寫入用的說法，會寫成「沒有寫入權限」：2026-10-26 第十輪）。"""
    if isinstance(e, (json.JSONDecodeError, UnicodeDecodeError)):
        return tr("不是完整的 JSON（{raw}）").format(raw=str(e))
    if isinstance(e, OSError) and (isinstance(e, PermissionError) or e.errno in (errno.EACCES, errno.EPERM)):
        if e.errno is not None and e.strerror:
            return tr("{desc}（{raw}）").format(desc=tr("沒有讀取權限"), raw=f"[Errno {e.errno}] {e.strerror}")
        return tr("沒有讀取權限")
    return oserror_text(e)


def _lock_fd_retry(fd: int, budget: float = FROZEN_LOCK_RETRY_S) -> bool:
    """_lock_fd，鎖不到就在 budget 秒內短暫重試：別的 DSV 檢查有沒有人開著時會把我們的登記檔鎖住一下（frozen_other_instances，
    微秒等級），剛好撞上的話只試一次就會留下一個沒鎖的登記檔，60 秒後被別的 DSV 當成當掉留下的刪掉、照清（實測 macOS 約萬分之七到千分之七）。"""
    deadline = time.monotonic() + max(0.0, budget)
    while True:
        if _lock_fd(fd):
            return True
        if time.monotonic() >= deadline:
            return False
        time.sleep(0.002)


def _lock_fd(fd: int) -> bool:
    """不等待地鎖住檔案（macOS／Linux flock、Windows msvcrt.locking 第 0 個位元組）；鎖不到（別人鎖著、檔案系統不支援）回 False。"""
    try:
        if os.name == "nt":
            import msvcrt
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        return True
    except (OSError, ImportError, ValueError):
        return False


def _unlock_fd(fd: int) -> None:
    try:
        if os.name == "nt":
            import msvcrt
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
        else:
            import fcntl
            fcntl.flock(fd, fcntl.LOCK_UN)
    except Exception:
        pass


class FrozenInstanceLock:
    """這個 DSV 在凍結資料夾裡的登記：.dsv-instance-<pid>-<亂數>.lock，開著的期間一直鎖著（程式結束、當掉時作業系統自動解鎖）。
    別的 DSV 要清凍結檔之前看到有人鎖著就不清（我們的目前訊號、undo、剪貼簿可能還用到）。"""

    def __init__(self, directory: str):
        self.path = os.path.join(directory, f"{FROZEN_LOCK_PREFIX}{os.getpid()}-{os.urandom(4).hex()}.lock")
        self.fd: Optional[int] = os.open(self.path, os.O_RDWR | os.O_CREAT, 0o600)
        self.locked = _lock_fd_retry(self.fd)          # 別的 DSV 剛好在檢查它（鎖住一下）就再試，不留下沒鎖的登記

    def valid(self) -> bool:
        """登記還有效：鎖著，而且登記檔還在、就是我們開著的那一個（整個凍結資料夾被刪掉、或登記檔被刪掉，別的 DSV 就看不到我們了）。"""
        if self.fd is None or not self.locked:
            return False
        try:
            a, b = os.fstat(self.fd), os.stat(self.path)
        except OSError:
            return False
        if os.name != "nt" and a.st_ino and b.st_ino:  # 同名的檔被重建也不算（Windows 開著的檔刪不掉，只看在不在）
            return (a.st_ino, a.st_dev) == (b.st_ino, b.st_dev)
        return True

    def release(self) -> None:
        fd, self.fd = self.fd, None
        if fd is None:
            return
        if self.locked:
            _unlock_fd(fd)
        try:
            os.close(fd)
        except OSError:
            pass
        try:
            os.remove(self.path)
        except OSError:
            pass


def frozen_other_instances(directory: str, own: Optional[str] = None, now: Optional[float] = None) -> bool:
    """凍結資料夾裡有沒有別的開著的 DSV（它鎖著自己的登記檔；own＝自己的登記檔，不算）。沒鎖著的登記檔是結束或當掉的 DSV 留下的：
    建立超過 FROZEN_LOCK_FRESH_S 秒就刪掉；更新的照樣算開著（剛建好、還沒鎖上）。打不開、鎖不了的一律算開著（寧可不清）。"""
    try:
        names = os.listdir(directory)
    except OSError:
        return False
    now = time.time() if now is None else now
    own_n = os.path.normcase(os.path.abspath(own)) if own else None
    busy = False
    for name in names:
        if not (name.startswith(FROZEN_LOCK_PREFIX) and name.endswith(".lock")):
            continue
        p = os.path.join(directory, name)
        if own_n is not None and os.path.normcase(os.path.abspath(p)) == own_n:
            continue
        try:
            fd = os.open(p, os.O_RDWR)
        except FileNotFoundError:
            continue                                   # 剛好結束、自己刪掉了
        except OSError:
            busy = True
            continue
        try:
            free = _lock_fd(fd)
            if free:
                _unlock_fd(fd)
        finally:
            os.close(fd)
        try:
            fresh = now - os.path.getmtime(p) < FROZEN_LOCK_FRESH_S
        except OSError:
            continue
        if not free or fresh:
            busy = True
            continue
        try:
            os.remove(p)                               # 結束或當掉的 DSV 留下的
        except OSError:
            pass
    return busy


def clean_frozen_dir(directory: str, keep: Set[str], still_alone: Optional[Callable[[], bool]] = None) -> List[str]:
    """刪掉 directory 裡沒人用到的凍結檔：只動 save_frozen_array 存的檔名格式（FROZEN_FILE_RE）與它寫到一半留下的暫存檔，
    keep（檔名，frozen_refs 的結果；比對不分大小寫，見 frozen_refs）裡的、登記檔、別的檔案一律不碰。still_alone：每刪一個之前再問一次
    （別的 DSV 剛好開了就停）。回傳刪掉的檔名。能不能清（讀不了的自動存檔、它的備份：U15）由呼叫端先問 frozen_cleanup_blocker。"""
    removed: List[str] = []
    try:
        names = sorted(os.listdir(directory))
    except OSError:
        return removed
    keep_l = {str(k).lower() for k in keep}
    for name in names:
        if not (FROZEN_FILE_RE.match(name) or FROZEN_TMP_RE.match(name)) or name.lower() in keep_l:
            continue
        if still_alone is not None and not still_alone():
            break
        try:
            os.remove(os.path.join(directory, name))
            removed.append(name)
        except OSError as e:
            log(f"凍結檔刪不掉 {name}: {e}")
    return removed


# --- DSV 自己畫的對話框（2026-10-26 使用者決定 U12、U13）----------------------------------------------------------------
# 關閉時自動存檔寫不進去要問「照樣關閉／先不關」（系統原生的對話框改不了按鈕文字），啟動時自動存檔讀不了要提示——這兩個用 Tk 畫：
# 開著的時候 Tk 的事件迴圈照常轉，結束訊號（SIGTERM：更新後自動重啟）照樣處理得到，可以直接把對話框關掉、照常結束，不會被擋住。
_NATIVE_DIALOGS = [0]          # 系統原生的訊息框（messagebox）正開著的層數：這時候不再疊一個 Tk 對話框上去（_can_ask_now）
_TK_DIALOGS: List[Any] = []    # 正在等回答的 DsvDialog（ask）：結束訊號來時用各自的 term 答案關掉（close_pending_dialogs）
_TERM_REQUESTED = [False]      # 收到結束訊號了：之後才要跳的 DsvDialog.ask 不等，直接用 term 的答案（訊號剛好在跳出來之前到）


class DsvDialog(tk.Toplevel):
    """DSV 自己畫的對話框：一段訊息＋一排按鈕（文字自訂）。ask()＝等回答（模態）；notice()＝不擋操作的提示（只有「確定」）。
    Esc、關掉視窗＝cancel，Return＝default；預設的按鈕在最右邊（macOS 的習慣）。"""

    def __init__(self, parent, title: str, message: str, buttons: Sequence[Tuple[str, Any]], default: Any = None,
                 cancel: Any = None, term: Any = None):
        super().__init__(parent)
        th = T.current()
        px = th.px if th else (lambda n: n)
        self.result, self.term = cancel, term
        self.message = message
        self.title(title)
        try:
            if parent is not None:
                self.transient(parent)
        except tk.TclError:
            pass
        self.resizable(False, False)
        outer = ttk.Frame(self, padding=px(16))
        outer.pack(fill="both", expand=True)
        ttk.Label(outer, text=message, justify="left", wraplength=px(560)).pack(anchor="w")
        bar = ttk.Frame(outer)
        bar.pack(fill="x", pady=(px(16), 0))
        self.buttons: Dict[Any, Any] = {}
        for text, value in reversed(list(buttons)):
            b = ttk.Button(bar, text=text, command=lambda v=value: self.close(v),
                           style="Primary.TButton" if value == default else "TButton")
            b.pack(side="right", padx=(px(8), 0))
            self.buttons[value] = b
        self.bind("<Escape>", lambda e: self.close(cancel))
        self.bind("<Return>", lambda e: self.close(default))
        self.protocol("WM_DELETE_WINDOW", lambda: self.close(cancel))
        self._place(parent)
        try:
            self.buttons[default].focus_set()
        except Exception:
            pass

    def _place(self, parent) -> None:
        """放在 parent 中間偏上（parent 沒顯示就放在螢幕中間），整個框夾進螢幕（Windows：工作區）——主視窗放得很低、提示很長
        （關閉時的提醒列了幾十個檔）時，以前底部跑到螢幕外、「確定」按不到（0.9.14 第三輪行為驗證：macOS 把主視窗串接到 y=398 時）。"""
        try:
            self.update_idletasks()
            w, h = self.winfo_reqwidth(), self.winfo_reqheight()
            title_h = 28
            if parent is not None and parent.winfo_ismapped():
                x = parent.winfo_rootx() + (parent.winfo_width() - w) // 2
                y = parent.winfo_rooty() + max(0, (parent.winfo_height() - h) // 3)
                try:
                    title_h = max(title_h, int(parent.winfo_rooty() - parent.winfo_y()))     # 標題列高度（照 parent 的框量）
                except Exception:
                    pass
            else:
                x, y = (self.winfo_screenwidth() - w) // 2, (self.winfo_screenheight() - h) // 3
            left, top, right, bottom = T.work_area(self)
            x = max(left, min(x, right - w))
            y = max(top, min(y, bottom - h - title_h))
            self.geometry(f"+{max(0, x)}+{max(0, y)}")
        except Exception:
            pass

    def close(self, value: Any) -> None:
        self.result = value
        try:
            self.grab_release()
        except Exception:
            pass
        try:
            self.destroy()
        except Exception:
            pass

    @classmethod
    def ask(cls, parent, title: str, message: str, buttons: Sequence[Tuple[str, Any]], default: Any, cancel: Any,
            term: Any = None, timeout_ms: Optional[int] = None, timeout_value: Any = None) -> Any:
        """模態：等使用者按一個按鈕，回傳那個按鈕的值。原本有別的對話框抓著輸入（grab）就先借過來，問完還給它。
        結束訊號來時（close_pending_dialogs）回傳 term。timeout_ms＝這麼久沒按就自己關掉、回傳 timeout_value（關閉時的提醒用：
        不能讓程式關不掉）。"""
        try:
            prev = parent.grab_current() if parent is not None else None
        except Exception:
            prev = None
        dlg = cls(parent, title, message, buttons, default, cancel, term)
        _TK_DIALOGS.append(dlg)
        try:
            if _TERM_REQUESTED[0]:
                dlg.close(dlg.term)
            else:
                try:
                    dlg.grab_set()
                except tk.TclError:
                    pass
                if timeout_ms is not None:
                    dlg.after(max(1, int(timeout_ms)), lambda: dlg.close(timeout_value))
                dlg.wait_window()
        finally:
            if dlg in _TK_DIALOGS:
                _TK_DIALOGS.remove(dlg)
            try:
                if prev is not None and prev.winfo_exists():
                    prev.grab_set()
            except Exception:
                pass
        return dlg.result

    @classmethod
    def notice(cls, parent, title: str, message: str) -> "DsvDialog":
        """不擋操作的提示（只有「確定」）：跳出來就回來，程式照常用；回傳那個視窗。"""
        return cls(parent, title, message, [(tr("確定"), True)], default=True, cancel=True)


def close_pending_dialogs(term: bool = True) -> int:
    """結束訊號（SIGTERM／SIGHUP：更新後自動重啟、kill）來時：正在等回答的 DsvDialog 都用它的 term 答案關掉，
    呼叫端照常往下走（更新後自動重啟不能被對話框擋住）；之後才要跳的也不等（_TERM_REQUESTED）。回傳關了幾個。
    term=False（開啟時的問句開著、使用者自己按主視窗的關閉鈕，C1）：只關掉正在等回答的，之後要跳的照常跳（關閉時的提醒，C2-2）。"""
    if term:
        _TERM_REQUESTED[0] = True
    n = 0
    for dlg in list(_TK_DIALOGS):
        dlg.close(dlg.term)
        n += 1
    return n


class _NativeDialogs:
    """包住 tkinter 的 messagebox：呼叫系統原生的訊息框時記下來（_NATIVE_DIALOGS），其他照舊。"""

    def __init__(self, mod):
        self._mod = mod

    def __getattr__(self, name):
        f = getattr(self._mod, name)
        if name.startswith("_") or not callable(f) or isinstance(f, type):
            return f

        def call(*a, **k):
            _NATIVE_DIALOGS[0] += 1
            try:
                return f(*a, **k)
            finally:
                _NATIVE_DIALOGS[0] -= 1
        return call


class _DsvMessageBox(_NativeDialogs):
    """sv.messagebox：tkinter.messagebox 加上 DSV 自己畫的兩種（DsvDialog）。測試把整個 sv.messagebox 換掉時一起攔下來。"""

    @staticmethod
    def askyesno_labels(title: str, message: str, yes: str, no: str, parent=None, default_yes: bool = False,
                        term: bool = True) -> bool:
        """兩個按鈕、文字自訂（例如「照樣關閉」「先不關」）；按 yes 回 True，no、Esc、關掉視窗回 False；結束訊號來時回 term。"""
        return bool(DsvDialog.ask(parent, title, message, [(yes, True), (no, False)], default=bool(default_yes), cancel=False,
                                  term=term))

    @staticmethod
    def shownotice(title: str, message: str, parent=None):
        """不擋操作的提示（Tk 畫的，只有「確定」）：跳出來就回來，回傳那個視窗。"""
        return DsvDialog.notice(parent, title, message)

    @staticmethod
    def shownotice_wait(title: str, message: str, parent=None, timeout_ms: Optional[int] = None) -> bool:
        """等使用者按「確定」的提示（Tk 畫的，模態）；timeout_ms 到了自己關掉。回傳 True＝按了確定（或 Esc、關掉視窗），
        False＝時間到自己關掉。結束訊號來時馬上關掉（close_pending_dialogs）。"""
        return bool(DsvDialog.ask(parent, title, message, [(tr("確定"), True)], default=True, cancel=True, term=True,
                                  timeout_ms=timeout_ms, timeout_value=False))


if HAVE_TK:
    messagebox = _DsvMessageBox(messagebox)      # filedialog／colorchooser 不包：測試直接改這兩個模組的函式（plotkit 也用同一個模組）


def sync_derived_timebase(signals) -> List[Signal]:
    """I/Q 幅度／相位衍生訊號的時間軸（SPS、offset）跟著來源 I（繪圖類型不跟）；回傳這次改了的衍生訊號。
    來源找不到（被移除）的不動。主視窗每次重畫前呼叫：改 I 的 SPS／offset（任何方式）都推進了 undo，衍生訊號跟著同一筆復原。"""
    changed: List[Signal] = []
    for _pass in range(max(1, len(signals))):      # 前處理可以接在另一條衍生訊號後面：來源排在後面時要再跑一輪才跟上
        moved = False
        for s in signals:
            if not s.derive:
                continue
            srcs = s.sources()
            if srcs is None:
                continue
            si = srcs[0]
            sps, off = pp_timebase(s, si) if s.derive in PP_KINDS else (float(si.sps), float(si.offset))
            if s.roi:                              # 擷取出來的一段：只跟來源的 SPS；起點是擷取時定的（MATLAB 擷取出來是另一條訊號）
                if s.sps != sps:
                    s.sps = sps
                    moved = True
                    if s not in changed:
                        changed.append(s)
                continue
            if s.sps != sps or s.offset != off:
                s.sps, s.offset = sps, off
                moved = True
                if s not in changed:
                    changed.append(s)
        if not moved:
            break
    return changed


def pp_empty_source_error(si: Signal) -> "dsv_preprocess.PreprocessError":
    """來源沒有資料時的 PreprocessError（訊息說明來源的問題：來源自己是算不出來的前處理結果 → 接上它的原因；它的來源不見了；空的訊號）。
    _load_full（接在算不出來的結果後面的結果）與 apply_preprocess（對這種來源按「套用」）共用。"""
    err = getattr(si, "pp_error", None) if si.derive in PP_KINDS else None
    missing = bool(si.derive) and si.detected == "missing"
    return dsv_preprocess.PreprocessError(dsv_preprocess.empty_source_message(si.name, err, missing), ident="dsv:preprocess:emptySource")


def pp_timebase(s: Signal, si: Signal) -> Tuple[float, float]:
    """前處理衍生訊號的 (SPS, offset)：起點和來源相同（MATLAB 的 Time 不變；resample 的 ty(1) = tx(1)），
    重取樣的 SPS＝來源 SPS × 新取樣率／原取樣率（symbol rate 不變）；offset 單位是 sample 時照新 SPS 換算成同一個起點。"""
    ratio = dsv_preprocess.rate_ratio(s.derive, s.pp, Signal._fs_of(si))
    if ratio == 1.0:
        return float(si.sps), float(si.offset)
    sps = float(si.sps) * ratio
    off = float(si.x0) * sps if SETTINGS.get("offset_unit") == "sample" else float(si.offset)
    return sps, off


def iq_timebase_mismatch(signals) -> List[Tuple[Signal, Signal]]:
    """有衍生訊號的 I/Q 配對裡，Q 的 SPS 或起點（x0）和 I 不一致的 (I, Q)（重複的只列一次）。"""
    out: List[Tuple[Signal, Signal]] = []
    seen = set()
    for s in signals:
        if not s.derive or s.derive not in IQ_DERIVE_KINDS:     # 前處理的衍生訊號只有一個來源，沒有 I/Q 配對
            continue
        srcs = s.sources()
        if srcs is None:
            continue
        si, sq = srcs
        if (si.uid, sq.uid) in seen:
            continue
        seen.add((si.uid, sq.uid))
        if not math.isclose(si.sps, sq.sps, rel_tol=1e-12) or not math.isclose(si.x0, sq.x0, rel_tol=1e-12, abs_tol=1e-12):
            out.append((si, sq))
    return out


# ---------------------------------------------------------------------------
# 5. 繪圖（和 GUI 分開，方便單獨測試）
# ---------------------------------------------------------------------------
def panel_units(opts: dict, panel: Optional[int] = None) -> Tuple[str, float]:
    """panel 的 (x 軸單位, Symbol rate)：opts["panels"][panel]（每個 panel 各自設，MATLAB Signal Analyzer 每個顯示畫面各自的單位）；
    沒給 panel 或那個 panel 沒設定就用 opts 的 xunit／symbol_rate。"""
    pp = (opts.get("panels") or {}).get(panel) if panel is not None else None
    unit = (pp or {}).get("xunit") or opts.get("xunit", "symbol")
    sr = (pp or {}).get("symbol_rate") or opts.get("symbol_rate") or DEFAULT_SYMBOL_RATE
    return unit, float(sr)


def panel_linked(opts: dict, panel: int) -> bool:
    """panel 的「連結時間」（MATLAB Signal Analyzer Link Time，預設勾）。"""
    return bool(((opts.get("panels") or {}).get(panel) or {}).get("link", True))


def x_display_factor(opts: dict, panel: Optional[int] = None) -> float:
    """symbol → 顯示單位的倍率（給 panel 就用那個 panel 的 x 單位與 Symbol rate）。"""
    unit, sr = panel_units(opts, panel)
    sc = X_UNIT_SCALE.get(unit)
    return 1.0 if not sc else sc / sr


def link_x_axes(ax_of: Dict[int, Any], panels: List[int], linked: Dict[int, bool],
                units: Dict[int, Tuple[str, float]]) -> Dict[int, int]:
    """連結時間：勾了的 panel x 一起縮放平移（MATLAB Signal Analyzer 預設勾、可對單一畫面取消）。
    x 單位與 Symbol rate 都一樣的 → matplotlib sharex（刻度共用、行為和以前全部共用 x 一樣）；
    不一樣的 → xlim_changed 互相換算成同一段時間（x 是各自的 symbol：乘上對方 rate／自己 rate）。
    要在建 twinx 之前呼叫（已經共用的軸不能再 sharex）。回傳 {panel: 群組 id}；座標區標 _pk_xlink，plotkit 縮放時當成同一組。"""
    lp = [p for p in panels if linked.get(p)]
    if len(lp) < 2:
        return {}
    sub: Dict[Tuple[str, float], List[Any]] = {}
    for p in lp:
        sub.setdefault(units[p], []).append(ax_of[p])
    for axs in sub.values():
        for a in axs[1:]:
            a.sharex(axs[0])
    for p in lp:
        ax_of[p]._pk_xlink = 1
    if len(sub) > 1:
        groups = [(key[1], axs) for key, axs in sub.items()]
        busy = [False]

        def bridge(rate_src: float, own: List[Any]):
            def cb(ax):
                if busy[0]:
                    return
                busy[0] = True
                try:
                    lo, hi = ax.get_xlim()
                    for rate, axs in groups:
                        if axs is not own:
                            axs[0].set_xlim(lo * rate / rate_src, hi * rate / rate_src)   # emit：同組 sharex 的跟著
                finally:
                    busy[0] = False
            return cb
        for rate, axs in groups:
            cb = bridge(rate, axs)
            for a in axs:
                a.callbacks.connect("xlim_changed", cb)
    return {p: 1 for p in lp}


def x_label_panels(panels: List[int], collapsed: set) -> set:
    """要畫 x 刻度文字與 x 軸標籤的 panel：每一張都畫（2026-10-25 使用者回報第 11 項：不管單位一不一樣、有沒有連結時間，當成預設；
    0.9.8 以前連結而且單位一樣的只有最下面一張有）。收合的矮列不畫，除非它是最下面那張。"""
    last = panels[-1] if panels else None
    return {p for p in panels if p not in collapsed or p == last}


def x_label_panels_shared(panels: List[int], collapsed: set, linked: Dict[int, bool],
                          units: Dict[int, Tuple[str, float]]) -> set:
    """0.9.8 的標法（只在「存成圖檔」的大小放不下每張的標籤時退回來用，見 panel_layout）：最下面那張一定畫；其他的只有下一張和它
    不同步（沒連結時間、單位或 Symbol rate 不同）才畫，連結而且單位一樣的連續幾張只在最下面標。收合的矮列不畫（除非是最下面那張）。"""
    out = set()
    for i, p in enumerate(panels):
        if i == len(panels) - 1:
            out.add(p)
            continue
        if p in collapsed:
            continue
        q = panels[i + 1]
        if not (linked.get(p) and linked.get(q) and units.get(p) == units.get(q)):
            out.add(p)
    return out


def x_label_room(style: dict) -> float:
    """座標區下面放 x 刻度文字＋x 軸標籤要多高（英吋）：朝外的刻度線＋間距＋刻度字＋標籤間距＋標籤字，再留 X_LABEL_CLEAR_PT。
    字高用字級 × 1.25 估（matplotlib 量 "lp" 的實際高度約 1.0 倍字級；多留的給 Windows 的中文字型）。圖字級（偏好設定）改大也跟著變大。"""
    rc = matplotlib.rcParams
    fs = float(style.get("fontsize", 10.0) or 10.0)
    fl = fs * float((style.get("label") or {}).get("scale", 1.0))
    out = {"out": 1.0, "inout": 0.5}.get(str(style.get("tick_dir", "out")), 0.0)     # 朝內的刻度線不佔下面的空間
    # xlabel_extra_pt：自訂的 x 軸名稱（中文、數學式）比一行字高時多留的（render／_resize_canvas 量好放進 style，x_label_extra_pt）
    pt = (out * float(rc["xtick.major.size"]) + float(rc["xtick.major.pad"]) + 1.25 * fs
          + float(rc["axes.labelpad"]) + 1.25 * fl + X_LABEL_CLEAR_PT + max(0.0, float(style.get("xlabel_extra_pt", 0.0) or 0.0)))
    return pt / 72.0


def x_label_bottom(style: dict) -> float:
    """最下面那張圖下面的留白（英吋）：0.5 in（以前固定的值），圖字級大到放不下 x 刻度字＋標籤時加大。"""
    return max(0.5, x_label_room(style) - X_LABEL_CLEAR_PT / 72.0)


def x_tick_out_in(style: dict) -> float:
    """朝外的 x 刻度線伸到座標區下面多長（英吋）：沒標 x 軸的圖（收合的矮列、匯出退回 0.9.8 的標法）下面還有它，下一張的標題要讓開。"""
    out = {"out": 1.0, "inout": 0.5}.get(str(style.get("tick_dir", "out")), 0.0)
    return out * float(matplotlib.rcParams["xtick.major.size"]) / 72.0


def panel_top_margin(h_in: float, tops: Optional[Sequence[float]] = None, fig_top: float = 0.0) -> float:
    """最上面那張圖上面的留白（英吋）：0.9.8 的 0.2 in（圖不到 1 in 高時是高度的兩成）；最上面那張有標題時至少放得下它（title_room_in），
    有整張圖的大標題時再加上大標題（figure_title_room_in）。最多佔圖高的一半。"""
    H = max(float(h_in), 1e-3)
    base = H * min(0.2, 0.2 / max(H, 1.0))
    t0 = float(tops[0]) if tops else 0.0
    m = (float(fig_top) + max(t0, base)) if fig_top > 0 else max(base, t0)
    return min(m, 0.5 * H)


def gap_needs(n: int, labeled: Sequence[bool], g_lab: float, tops: Optional[Sequence[float]] = None,
              g_tick: float = 0.0) -> List[float]:
    """每個空隙至少要多高（英吋；0＝沒有要求，照 0.9.8 的比例）：上面那張有標 x 軸＝g_lab（刻度字＋標籤，含下面留的 X_LABEL_CLEAR_PT），
    下面那張有標題＋副標題（tops[i+1]，2026-10-26 新功能）再加它（上面那張沒標 x 軸時改加朝外的刻度線 g_tick 和同樣的 X_LABEL_CLEAR_PT：
    收合的矮列、匯出退回 0.9.8 的標法時，下一張的標題和上面那張之間也留一樣的間距）。"""
    out = []
    for i in range(max(n - 1, 0)):
        t = float(tops[i + 1]) if tops and i + 1 < len(tops) else 0.0
        lab = bool(labeled[i]) if i < len(labeled) else False
        out.append((g_lab if lab else 0.0) + ((t + (0.0 if lab else g_tick + X_LABEL_CLEAR_PT / 72.0)) if t > 0 else 0.0))
    return out


def panel_gaps(u: float, ratios: Sequence[float], labeled: Sequence[bool], g_lab: float,
               tops: Optional[Sequence[float]] = None, g_tick: float = 0.0) -> List[float]:
    """每個空隙的高度（英吋）：一張正常的圖高 u 時，平均列高的 0.3 倍（和 0.9.8 的 GridSpec hspace=0.3 一樣）；
    上面那張有標 x 軸（labeled[i]）時至少 g_lab（放得下刻度字＋標籤）。收合的矮列下面不標，空隙照舊小。
    下面那張有標題、副標題（tops）時再留它們的高度（gap_needs），不壓到上面那張的 x 軸標籤、刻度字、圖例；沒有標題時和以前一樣。"""
    n = len(ratios)
    if n < 2:
        return []
    g_base = PANEL_HSPACE * u * float(sum(ratios)) / n
    return [max(need, g_base) for need in gap_needs(n, labeled, g_lab, tops, g_tick)]


def panel_rows_height(u: float, ratios: Sequence[float], mins: Optional[Sequence[float]] = None,
                      col_floor: bool = False) -> List[float]:
    """每一列（座標區）的高度（英吋）：一張正常的圖高 u 時 ratio × u，但不小於這一列自己的下限 mins[i]（放得下它的圖例；
    只有那一列加高，其他列照 u——2026-10-25 第二輪審查：以前一張訊號多就每一張都一起加高）。
    col_floor（「存成圖檔」別的大小）：收合的矮列至少是最矮那張展開的圖的 ratio 倍（0.22），展開的圖都被圖例的下限撐著、u 變得很小時
    矮列也不會被壓扁、標題不疊（2026-10-25 第四輪審查：8 張存成 8×5 in 時矮列只剩 7 px）。畫面上不用（u 就是正常的圖高）。"""
    if not mins:
        rows = [float(r) * float(u) for r in ratios]
    else:
        rows = [max(float(r) * float(u), float(m)) for r, m in zip(ratios, mins)]
    if col_floor:
        exp = [h for h, r in zip(rows, ratios) if float(r) >= 1.0]
        if exp:
            lo = min(exp)
            rows = [max(h, float(r) * lo) if float(r) < 1.0 else h for h, r in zip(rows, ratios)]
    return rows


def solve_panel_u(avail: float, ratios: Sequence[float], labeled: Sequence[bool], g_lab: float,
                  mins: Optional[Sequence[float]] = None, tol: float = 0.0, col_floor: bool = False,
                  tops: Optional[Sequence[float]] = None, g_tick: float = 0.0) -> Optional[float]:
    """可用高度 avail（英吋）裡，一張正常的圖能多高（u）：各列（panel_rows_height，col_floor 見那裡）＋各空隙（panel_gaps）＝avail。
    總高對 u 是分段線性、遞增的，在轉折點之間直接解（col_floor 的轉折點也是某一列的下限，已經在裡面）。
    各列的下限加上有標籤、標題的空隙就已經超過 avail（多 tol 以內不算）→ None（放不下）。"""
    n = len(ratios)
    if n == 0:
        return 0.0
    mins = [float(m) for m in mins] if mins else [0.0] * n
    S = float(sum(ratios)) or 1.0
    c = PANEL_HSPACE * S / n                       # 沒要求的空隙＝c × u；有標籤、標題的＝max(要的高度, c × u)

    def total(u: float) -> float:
        return sum(panel_rows_height(u, ratios, mins, col_floor)) + sum(panel_gaps(u, ratios, labeled, g_lab, tops, g_tick))
    t_prev = total(0.0)
    if t_prev > avail + tol:
        return None
    if t_prev >= avail:
        return 0.0
    u_prev = 0.0
    bps = sorted({m / float(r) for r, m in zip(ratios, mins) if m > 0 and float(r) > 0}
                 | ({need / c for need in gap_needs(n, labeled, g_lab, tops, g_tick) if need > 0} if c > 0 else set()))
    for b in bps:
        tb = total(b)
        if tb >= avail:
            return u_prev + (avail - t_prev) * (b - u_prev) / (tb - t_prev) if tb > t_prev else b
        u_prev, t_prev = b, tb
    slope = S + c * (n - 1)                        # 最後一個轉折點之後：每列都是 ratio × u、每個空隙都是 c × u
    return u_prev + (avail - t_prev) / slope


def labels_too_costly(u: float, u_fb: float, ratios: Sequence[float], mins: Sequence[float], g_lab: float) -> bool:
    """「存成圖檔」別的大小時要不要退回 0.9.8 的標法（2026-10-25 第三輪：和風格無關、不會比 0.9.8 的標法難看）。u＝每張都標時一張正常的圖
    （座標區）的高度、u_fb＝照 0.9.8 的標法時的高度（英吋）、g_lab＝一組 x 刻度字＋標籤的空隙。下面任一個成立就退回：
    （1）有展開的圖比它自己的 x 標籤空隙還矮（標籤比圖還佔地方）；（2）一張正常的圖比 0.9.8 的標法矮了三分之一以上（FALLBACK_SHORTER）；
    （3）有收合的矮列、而且每張展開的圖都被下限（圖例、PANEL_MIN_IN）撐著：矮列只剩 0.22 × u，會比一張正常的圖的 0.22 倍還扁、標題疊在一起。"""
    exp = [i for i, r in enumerate(ratios) if float(r) >= 1.0]
    if not exp:
        return False
    m = [float(x) for x in mins] if mins else [0.0] * len(ratios)
    if min(max(float(u) * float(ratios[i]), m[i]) for i in exp) < g_lab - 1e-9:
        return True
    if float(u) < FALLBACK_SHORTER * float(u_fb) - 1e-9:
        return True
    if any(float(r) < 1.0 for r in ratios) and all(float(u) * float(ratios[i]) < m[i] - 1e-9 for i in exp):
        return True
    return False


def panel_layout(w_in: float, h_in: float, ratios: Sequence[float], labeled: Sequence[bool], style: dict,
                 right_in: float = RIGHT_MARGIN_IN, mins: Optional[Sequence[float]] = None,
                 fallback: Optional[Sequence[bool]] = None, bottom_extra: float = 0.0,
                 tol: float = LAYOUT_TOL_IN, tops: Optional[Sequence[float]] = None, fig_top: float = 0.0) -> dict:
    """主圖的版面，用英吋算（第 11 項：每張都標 x 軸）：上留白 0.2 in、下留白放得下最下面那張的標籤（x_label_bottom，再加 bottom_extra：
    畫面上最下面的「新增 panel」拖放區）、左右照 0.9.8，列高照 ratios（正常 1、收合 COLLAPSED_RATIO）而且不小於 mins（每列放得下自己的圖例、
    至少 PANEL_MIN_IN），空隙見 panel_gaps（只有上面那張有標籤的空隙放大，收合的矮列下面不放大）。標籤空隙都不用放大、列都沒到下限時和
    0.9.8 的 GridSpec 版面一模一樣。
    fallback＝這次是「存成圖檔」別的大小時可以退回的 0.9.8 標法（連結而且單位一樣的只在最下面那張標）；畫面上、用目前大小存的圖不給（一定每張都標）。
    每張都標放不下、或標了反而難看（labels_too_costly：圖比自己的標籤空隙還矮、比 0.9.8 的標法矮三分之一以上、收合的矮列被壓扁）就照 fallback 重排。
    存成別的大小時收合的矮列至少是最矮那張展開的圖的 COLLAPSED_RATIO 倍（panel_rows_height 的 col_floor：退回之後也不會被壓扁、標題不疊）。
    0.9.8 的標法也放不下（或圖例下限把圖撐到圖與圖之間的空隙不到 0.9.8 比例的一半）就不管圖例下限、照 0.9.8 的比例排（和 0.9.8 一樣圖例可能超出），
    有標籤的空隙太大時圖至少佔可用高度的 PANEL_MIN_SHARE、標籤空隙等比例縮小（squeezed：存好之後狀態列提醒加大高度）。
    tol＝多高以內的「放不下」不算（畫布高度取整數像素少掉的；用目前大小匯出時再加上輸出 DPI 的取整）。
    tops＝每張上面的標題＋副標題要留的高度（英吋，title_room_in；2026-10-26 新功能）、fig_top＝整張圖的大標題（figure_title_room_in）：
    最上面那張的標題和大標題放在上留白裡（panel_top_margin），其他張的標題放在它上面的空隙裡（gap_needs：在上面那張的 x 軸標籤下面）；
    標題不會因為大小不夠而藏起來（退回 0.9.8 的標法只藏 x 軸標籤；連那樣都放不下時標題的空間和標籤空隙一起等比例縮小）。沒有標題時和以前一模一樣。
    回傳 {"left", "right"（比例）, "rows"：[(下緣, 高度)]（比例，由上到下）, "u"（一張正常的圖，英吋）, "gaps"（英吋）,
    "labeled"（這次哪幾個空隙上面那張有標）, "fallback"（是不是退回 0.9.8 的標法）, "squeezed"（標籤空隙被縮小、可能壓到下一張）,
    "top"（上留白，英吋）}。"""
    n = len(ratios)
    W, H = max(float(w_in), 1e-3), max(float(h_in), 1e-3)
    left = min(0.3, 0.75 / max(W, 1.0))
    right = 1.0 - min(0.3, float(right_in) / max(W, 1.0))
    tops_ = [max(0.0, float(t)) for t in tops][:n] if tops else [0.0] * n
    tops_ += [0.0] * (n - len(tops_))
    top_m = panel_top_margin(H, tops_, fig_top)
    bot_m = H * min(0.4, (x_label_bottom(style) + max(0.0, float(bottom_extra))) / max(H, 1.0))
    avail = max(H - top_m - bot_m, 1e-3)
    g_lab = x_label_room(style)
    g_tick = x_tick_out_in(style) if any(tops_) else 0.0
    lab = [bool(b) for b in labeled][:max(n - 1, 0)]
    mins_ = [float(m) for m in mins] if mins else [0.0] * n
    tol = max(0.0, float(tol))                          # 畫布高度取整數像素少掉的不到 1 px：不算放不下
    fb = [bool(b) for b in fallback][:len(lab)] if fallback is not None else None
    cf = fb is not None                                 # 「存成圖檔」別的大小：收合的矮列至少是最矮那張展開的圖的 0.22 倍（col_floor）
    u = solve_panel_u(avail, ratios, lab, g_lab, mins_, tol, cf, tops_, g_tick)
    used_fallback = False
    if fb is not None and fb != lab:
        u_fb = solve_panel_u(avail, ratios, fb, g_lab, mins_, tol, cf, tops_, g_tick)
        u_fb0 = solve_panel_u(avail, ratios, fb, g_lab, [0.0] * n, tol, tops=tops_, g_tick=g_tick) or 0.0    # 0.9.8 的比例（不管圖例下限）
        if u_fb is not None and u_fb < 0.5 * u_fb0:
            u_fb = None                                 # 圖例下限把圖撐得圖與圖之間幾乎沒有空隙：當成放不下（下面照 0.9.8 的比例排）
        if u is None or labels_too_costly(u, u_fb if u_fb is not None else u_fb0, ratios, mins_, g_lab):
            lab, u, used_fallback = fb, u_fb, True      # u＝None：0.9.8 的標法也放不下 → 下面不管圖例下限
    squeezed = False
    if u is None:
        squeezed = True
        mins_ = [0.0] * n
        need = sum(gap_needs(n, lab, g_lab, tops_, g_tick))
        if need > 0 and avail - need < avail * PANEL_MIN_SHARE:
            k_sq = avail * (1.0 - PANEL_MIN_SHARE) / need   # 標籤空隙（和標題的空間）等比例縮小，圖至少佔可用高度的 PANEL_MIN_SHARE
            g_lab, g_tick = g_lab * k_sq, g_tick * k_sq
            tops_ = [tops_[0]] + [t * k_sq for t in tops_[1:]]
        u = solve_panel_u(avail, ratios, lab, g_lab, mins_, tol, tops=tops_, g_tick=g_tick) or 0.0
    gaps = panel_gaps(u, ratios, lab, g_lab, tops_, g_tick)
    rows: List[Tuple[float, float]] = []
    y = H - top_m
    for i, h in enumerate(panel_rows_height(u, ratios, mins_, cf)):
        rows.append(((y - h) / H, h / H))
        y -= h + (gaps[i] if i < len(gaps) else 0.0)
    return {"left": left, "right": right, "rows": rows, "u": u, "gaps": gaps, "labeled": lab, "fallback": used_fallback,
            "squeezed": squeezed, "top": top_m}


def panel_canvas_height(u: float, ratios: Sequence[float], labeled: Sequence[bool], style: dict,
                        mins: Optional[Sequence[float]] = None, bottom_extra: float = 0.0,
                        tops: Optional[Sequence[float]] = None, fig_top: float = 0.0) -> float:
    """要讓一張正常的圖高 u 英吋（各列不小於 mins），畫布要多高（英吋）：panel_layout 的反函數（上 0.2 或放得下標題與大標題、
    下 x_label_bottom＋bottom_extra、列高、空隙）。"""
    n = len(ratios)
    tops_ = [max(0.0, float(t)) for t in tops][:n] if tops else [0.0] * n
    tops_ += [0.0] * (n - len(tops_))
    g_tick = x_tick_out_in(style) if any(tops_) else 0.0
    return (panel_top_margin(1e6, tops_, fig_top) + x_label_bottom(style) + max(0.0, float(bottom_extra))
            + sum(panel_rows_height(u, ratios, mins)) + sum(panel_gaps(u, ratios, labeled, x_label_room(style), tops_, g_tick)))


def panel_row_mins(ratios: Sequence[float], legend_counts: Sequence[int], style: dict,
                   measured: Optional[Sequence[Optional[float]]] = None) -> List[float]:
    """每一列的高度下限（英吋）：正常的圖至少 PANEL_MIN_IN、而且放得下它自己的圖例；收合的矮列沒有下限。圖例的高度用 measured
    （render 畫好圖例後量到的實際高度，legend_row_min：中文、重音大寫的標籤比估的高）；沒量到的才用條數估（legend_min_height）。"""
    meas = list(measured) if measured is not None else []
    out = []
    for i, (r, c) in enumerate(zip(ratios, legend_counts)):
        if float(r) < 1.0:
            out.append(0.0)
            continue
        m = meas[i] if i < len(meas) else None
        out.append(max(PANEL_MIN_IN, float(m) if m is not None else legend_min_height(int(c), style)))
    return out


def nominal_panel_height(ph: float, ratios: Sequence[float]) -> float:
    """「每張圖高度」ph 在 0.9.8 的版面裡一張正常的圖（座標區）實際多高：畫布 max(1, 張數)×ph＋0.9、上 0.2、下 0.5、GridSpec hspace 0.3。
    每張都標 x 軸之後照樣給圖這個高度，標籤的空隙另外把畫布加高（圖不被壓扁）。"""
    n = len(ratios)
    S = float(sum(ratios)) or 1.0
    avail = max(1.0, S) * float(ph) + 0.2
    return avail * n / (S * (n + PANEL_HSPACE * (n - 1)))


def legend_min_height(nentries: int, style: dict) -> float:
    """放得下 n 條圖例（右上角，含和座標區上緣的間距）的座標區高度（英吋）的估計（還沒畫圖例時用；畫好之後用 legend_row_min 量實際的）。
    matplotlib 實量（ASCII 標籤）：圖例高 ≈ 圖例字級 ×（1.5n＋0.35），離上緣 0.5 倍字級；再留 0.25 倍字級。"""
    if nentries <= 0:
        return 0.0
    fs = float((style.get("legend") or {}).get("fontsize") or style.get("fontsize", 10.0) or 10.0)
    return fs * (1.5 * nentries + 1.1) / 72.0


def legend_row_min(leg, renderer, dpi: float) -> Optional[float]:
    """放得下這個圖例的座標區高度（英吋）：圖例實際的高（get_window_extent；中文、重音大寫的標籤每列比 ASCII 高，2026-10-25 第三輪審查）
    ＋離座標區上緣的間距（borderaxespad）＋再留 0.25 倍字級，和 legend_min_height 同一個算法。量不到回 None。"""
    try:
        if leg is None or not leg.get_visible():
            return None
        bb = leg.get_window_extent(renderer)
        fs = float(leg.prop.get_size_in_points())
        pad = float(getattr(leg, "borderaxespad", 0.5) or 0.0)
        return float(bb.height) / float(dpi) + (pad + 0.25) * fs / 72.0
    except Exception:
        return None


def x_tick_overhang(ax, style: dict) -> float:
    """最右邊的 x 刻度字超出座標區右緣多少（英吋，估計）：看得到的刻度裡最右邊那個的字寬一半 − 它到右緣的距離。
    資料長度是整數（例如 0–3000）時最後一個刻度就在右緣，刻度字有一半在座標區外，右邊留白不夠就被圖的邊切掉（第 11 項之後每張都有刻度字）。"""
    try:
        if not ax.xaxis.get_major_ticks()[0].label1.get_visible():
            return 0.0
        lo, hi = sorted(ax.get_xlim())
        locs = [float(v) for v in ax.xaxis.get_majorticklocs() if lo - 1e-12 * abs(hi - lo) <= v <= hi + 1e-12 * abs(hi - lo)]
        if not locs or hi <= lo:
            return 0.0
        last = max(locs)
        txt = str(ax.xaxis.get_major_formatter()(last, None))
        fs = float(style.get("fontsize", 10.0) or 10.0)
        half = sum(0.32 if c in ".,:;" else 0.62 for c in txt) * fs / 72.0 / 2.0      # Arial／Helvetica 數字約 0.56 em，多估一點
        width_in = ax.get_position().width * ax.figure.get_figwidth()
        return half - (hi - last) / (hi - lo) * width_in
    except Exception:
        return 0.0


# ---------------------------------------------------------------------------
# 使用者打的名稱與標題（2026-10-26 新功能：每個 panel 的 x、y 軸名稱、標題、副標題、右軸名稱，整張圖的大標題；
# 使用者選單決定見 audit/2026-10-26-branch-pause/decisions/decisions_u26.md 第 3 項）
# ---------------------------------------------------------------------------
PANEL_NAME_KEYS = ("title", "subtitle", "xname", "yname", "yname_right")   # 設定檔 panels[p] 的鍵；空白＝沒有（舊設定檔沒有這些鍵＝空白）
FIGURE_TITLE_KEY = "figure_title"        # 設定檔頂層：整張圖的大標題（MATLAB sgtitle）
NAME_MAX = 200                           # 名稱、標題最多存幾個字（畫的時候放不下的另外縮短加「…」，完整的字在對話框看得到）
TITLE_PAD_PT = 6.0                       # 標題（有副標題時是副標題）的下緣離座標區上緣（matplotlib axes.titlepad 的預設）
SUBTITLE_GAP_PT = 2.0                    # 副標題上緣和標題下緣之間（MATLAB 標題在上、副標題在下）
TITLE_CLEAR_PT = 3.0                     # 標題上緣到上面那張的 x 軸標籤（或畫布上緣）之間至少再留幾 pt
FIG_TITLE_PAD_PT = 5.0                   # 整張圖的大標題上緣離畫布上緣
FIG_TITLE_GAP_PT = 6.0                   # 大標題下緣到最上面那張的標題（沒有標題時是一般的上留白）之間
FIT_SAFETY = 0.97                        # 縮短名稱時字最多佔可用長度的比例（這裡量字的解析度和畫面上的不同，差一點點）
TITLE_SIDE_EM = 3.5                      # panel 的標題、副標題左右各讓開幾個字寬（× 圖字級）：y 軸的指數（例如 1e6）畫在座標區左上角、右軸的在右上角，
                                         # 和標題同一個高度；量得到實際的指數字（畫過一次之後）就照它的寬
ELLIPSIS = "…"


def clean_user_text(s: Any, limit: int = NAME_MAX) -> str:
    """對話框、設定檔來的名稱與標題：轉成字串，換行、Tab 與其他控制字元換成空白（名稱都是一行），去掉頭尾空白，最多 limit 個字。
    孤立的代理字元（手改、壞掉的 JSON 裡的 \\ud800；Cs）也換成空白：matplotlib 畫不了（整張圖畫不出來）、JSON 寫不出去（自動存檔寫不進去）。"""
    if s is None:
        return ""
    t = "".join(" " if unicodedata.category(c) in ("Cc", "Zl", "Zp", "Cs") else c for c in str(s))
    return t.strip()[:max(0, int(limit))]


def drop_surrogates(s: Any) -> Any:
    """設定檔裡的其他字串（訊號的名稱 label、y 軸單位）：只把孤立的代理字元（Cs）換成空白，其他字照舊（不是字串的原樣回傳）。
    理由同 clean_user_text：0.9.9 的 label 裡有 \\ud800 時整張圖畫不出來、自動存檔寫不進去。"""
    if not isinstance(s, str) or not any(unicodedata.category(c) == "Cs" for c in s):
        return s
    return "".join(" " if unicodedata.category(c) == "Cs" else c for c in s)


@lru_cache(maxsize=1024)
def _mathtext_ok(s: str) -> bool:
    """s（有成對的 $）用 matplotlib 的數學式解析器排得出來嗎（不合法的 $x^$、$\\foo$、$$ 排版時會丟 ValueError，整張圖畫不出來）。"""
    try:
        from matplotlib.mathtext import MathTextParser
        MathTextParser("path").parse(s, 72)
        return True
    except Exception:
        return False


def user_text_is_math(s: str) -> bool:
    """使用者打的字會不會當成數學式畫：有成對（偶數個沒跳脫）的 $，而且數學式合法。"""
    return bool(s) and "$" in s and matplotlib.cbook.is_math_text(s) and _mathtext_ok(s)


def user_text_bad_math(s: str) -> bool:
    """有成對的 $ 但數學式不合法（畫的時候照打的字顯示，狀態列提醒）。"""
    return bool(s) and "$" in s and matplotlib.cbook.is_math_text(s) and not _mathtext_ok(s)


def safe_user_text(s: str) -> str:
    """使用者打的字 → 給 matplotlib 畫的字串：照打的字顯示（rx_data 就是 rx_data，_ 與 ^ 不是上下標），只有成對的 $…$ 是數學式
    （和 y 軸單位一樣，matplotlib 的規則；這一點和 MATLAB 預設的 tex 不同，是使用者選的）。$ 是單數、或數學式不合法時每個 $ 前面加 \\，
    整段照原樣顯示，畫圖不會丟例外。每一段（名稱、單位）各自處理，接在一起之後 $ 也不會跨段配對。"""
    if not s or "$" not in s:
        return s or ""
    if user_text_is_math(s):
        return s
    return s.replace("$", "\\$")


_UNESCAPED_DOLLAR = re.compile(r"(?<!\\)\$")


def _non_math_chars(s: str) -> str:
    """數學式字串裡 $…$ 外面的字（matplotlib 用「第一個」字型畫它們，見 math_font_family）。"""
    parts = _UNESCAPED_DOLLAR.split(s)
    return "".join(parts[0::2]).replace("\\$", "$")


@lru_cache(maxsize=128)
def _font_charmap(family: str, weight: str) -> Optional[frozenset]:
    try:
        from matplotlib import font_manager
        path = font_manager.findfont(font_manager.FontProperties(family=[family], weight=weight), fallback_to_default=False)
        return frozenset(font_manager.get_font(path).get_charmap())
    except Exception:
        return None


def math_font_family(fam: Sequence[str], s: str, weight: Any = "normal") -> List[str]:
    """s 會當成數學式畫時，matplotlib 用字型清單的「第一個」字型畫 $…$ 外面的字、不換備援字型（實測 Arial 畫中文變成方框）：
    第一個缺字就把第一個有全部這些字的字型排到最前面。不是數學式、或第一個字型就都有＝不動。"""
    fam = list(fam)
    if len(fam) < 2 or not matplotlib.cbook.is_math_text(s):
        return fam
    need = {ord(c) for c in _non_math_chars(s) if not c.isspace()}
    if not need:
        return fam
    w = str(weight)
    for i, f in enumerate(fam):
        cm = _font_charmap(f, w)
        if cm is not None and need <= cm:
            return fam if i == 0 else [f] + fam[:i] + fam[i + 1:]
    return fam


_MEASURE: Dict[str, Any] = {}


@lru_cache(maxsize=4096)
def text_extent_pt(s: str, family: Tuple[str, ...], size: float, weight: str = "normal") -> Tuple[float, float]:
    """s 畫成一行字的寬、高（pt）：和 matplotlib Text 的框一樣——高度至少是 "lp" 的高、數學式照 $…$ 排、\\$ 是 $。量不到回 (0, 0)。"""
    try:
        from matplotlib.backends.backend_agg import RendererAgg
        from matplotlib.font_manager import FontProperties
        r = _MEASURE.get("r")
        if r is None:
            r = _MEASURE["r"] = RendererAgg(16, 16, 72.0)       # 72 dpi：一個像素＝1 pt
        prop = FontProperties(family=list(family), size=float(size), weight=weight)
        if not s:
            return 0.0, 0.0
        ismath = matplotlib.cbook.is_math_text(s)
        txt = s if ismath else s.replace("\\$", "$")
        w, h, _d = r.get_text_width_height_descent(txt, prop, ismath=ismath)
        _w2, h_lp, _d2 = r.get_text_width_height_descent("lp", prop, ismath=False)
        return float(w), float(max(h, h_lp))
    except Exception:
        return 0.0, 0.0


def _text_font(style: dict, role: str, s: str) -> Tuple[Tuple[str, ...], float, str]:
    """名稱與標題的字型（字型清單、字級 pt、粗細）：照 MATLAB 的比例——標題 × 標題倍率（matlab 風格 1.1、加粗）、副標題同字級不加粗、
    大標題同字級不加粗（MATLAB sgtitle 的 FontWeight 預設 normal）、軸名稱 × 標籤倍率；圖字級（偏好設定）跟著。"""
    fs = float(style.get("fontsize", 10.0) or 10.0)
    t = style.get("title") or {}
    if role == "title":
        size, weight = fs * float(t.get("scale", 1.0)), str(t.get("weight", "normal"))
    elif role in ("subtitle", "figure"):
        size, weight = fs * float(t.get("scale", 1.0)), "normal"
    else:
        size, weight = fs * float((style.get("label") or {}).get("scale", 1.0)), "normal"
    fam = tuple(math_font_family(pk.styles.resolved_fonts(style), s, weight))
    return fam, size, weight


def title_offsets_pt(title: str, subtitle: str, style: dict) -> Tuple[float, float, float]:
    """panel 的標題、副標題放在座標區上緣上面多高（pt，字框的下緣）與它們佔的高度（含上面的留白）：
    副標題在 TITLE_PAD_PT；標題在副標題上面（沒有副標題時在 TITLE_PAD_PT）。回傳 (標題的位置, 副標題的位置, 要留的高度)；沒有標題也沒有副標題＝(0, 0, 0)。"""
    t, sub = safe_user_text(title), safe_user_text(subtitle)
    if not t and not sub:
        return 0.0, 0.0, 0.0
    y = TITLE_PAD_PT
    y_sub = y
    if sub:
        y += text_extent_pt(sub, *_text_font(style, "subtitle", sub))[1] + (SUBTITLE_GAP_PT if t else 0.0)
    y_t = y
    if t:
        y += text_extent_pt(t, *_text_font(style, "title", t))[1]
    return y_t, y_sub, y + TITLE_CLEAR_PT


def title_room_in(title: str, subtitle: str, style: dict) -> float:
    """panel 上面要給標題＋副標題留多高（英吋）；都沒有＝0（版面和以前一樣）。"""
    return title_offsets_pt(title, subtitle, style)[2] / 72.0


def figure_title_room_in(text: str, style: dict) -> float:
    """整張圖的大標題要佔多高（英吋，含上面的留白和下面到最上面那張的間距）；沒有＝0。"""
    t = safe_user_text(text)
    if not t:
        return 0.0
    return (FIG_TITLE_PAD_PT + text_extent_pt(t, *_text_font(style, "figure", t))[1] + FIG_TITLE_GAP_PT) / 72.0


def x_label_extra_pt(labels: Sequence[str], style: dict) -> float:
    """x 軸標籤（自訂名稱可能有中文、數學式）比 x_label_room 估的一行字（1.25 倍字級）高多少（pt，至少 0）：每張都用最高的那個留空隙。"""
    fl = float(style.get("fontsize", 10.0) or 10.0) * float((style.get("label") or {}).get("scale", 1.0))
    hmax = 0.0
    for s in labels:
        if s:
            hmax = max(hmax, text_extent_pt(s, *_text_font(style, "label", s))[1])
    return max(0.0, hmax - 1.25 * fl)


def _cut_points(name: str, math_mode: bool) -> List[int]:
    """名稱可以在哪裡截斷（保留前 k 個字）：照打的字顯示的名稱哪裡都可以；數學式只能截在 $…$ 外面（截在裡面會變成不合法的數學式）。"""
    if not math_mode:
        return list(range(len(name) + 1))
    out, inside, prev = [], False, ""
    for k, c in enumerate(name):
        if not inside:
            out.append(k)
        if c == "$" and prev != "\\":
            inside = not inside
        prev = c
    out.append(len(name))
    return out


def fit_user_text(head: str, name: str, tail: str, avail_pt: float, family: Tuple[str, ...], size: float,
                  weight: str = "normal") -> Tuple[str, str]:
    """head＋名稱＋tail 畫出來超過 avail_pt（座標區的高或寬）時把中間的名稱截短、加「…」（P 編號、單位留著）。
    回傳 (畫的字串, 字串裡名稱那一段)；名稱照 safe_user_text 處理（照打的字顯示或數學式）。
    連只留「…」都放不下（圖非常矮）時名稱整個不畫＝沒有名稱時的標籤（例如「≡ P1 [V]」）：名稱不會讓標籤比 0.9.9 的更長。"""
    shown = safe_user_text(name)
    full = head + shown + tail
    lim = float(avail_pt) * FIT_SAFETY
    if not name or (lim > 0 and text_extent_pt(full, family, size, weight)[0] <= lim):
        return full, shown
    math_mode = user_text_is_math(name)

    def part(k: int) -> str:
        pre = name[:k].rstrip()
        return (pre if math_mode else pre.replace("$", "\\$")) + ELLIPSIS
    cuts = _cut_points(name, math_mode)
    lo, hi, best = 0, len(cuts) - 1, None
    while lo <= hi:                                      # 名稱越長越寬：二分找放得下的最長的
        mid = (lo + hi) // 2
        cand = part(cuts[mid])
        if text_extent_pt(head + cand + tail, family, size, weight)[0] <= lim:
            best, lo = cand, mid + 1
        else:
            hi = mid - 1
    if best is None:                                     # 只留「…」也放不下：不畫名稱（head 後面為了名稱加的空白也拿掉）
        bare = (head.rstrip() + tail) if head.endswith(" ") else (head + tail)
        return bare, ""
    return head + best + tail, best


class PanelLayout(LayoutEngine):
    """主圖的版面引擎：每次畫圖（含存成圖檔換了大小、複製圖）都照「當時」的圖大小用英吋重排（panel_layout），
    所以匯出成別的寬高，每張的 x 刻度字＋標籤也放得下、不壓到下一張（以前 subplots_adjust 存的是比例，圖變矮空隙跟著縮）。
    座標區用 _set_position 擺（twinx 的右軸一起動）；位置沒變就不動。mins＝每列的高度下限（圖例實際的高、PANEL_MIN_IN）。
    畫面上（不是匯出）一定每張都標，最下面多留 drop_in 英吋的拖放區；匯出（savefig 中，或 plotkit.export 正在匯出：fig._pk_exporting）時：
    - 和畫面一樣大（差不到一個輸出像素：任何 DPI 用「目前大小」存、複製圖）＝照畫面的標法（每張都標）；
    - 只匯出某幾張（panel 右鍵「只匯出這個 panel」：其他座標區暫時隱藏）＝匯出的那幾張一定標，看不見的不用留標籤空隙、不退回；
    - 別的大小＝fallback（0.9.8 的標法）放得下而且每張都標划不來（labels_too_costly）就退回：那次畫圖把多出來的 x 刻度字＋標籤藏起來，
      回到畫面就再顯示。last_export＝最近一次匯出的版面（存好之後狀態列說有沒有退回）。
    標題（2026-10-26 新功能）：tops＝每張上面標題＋副標題的高度、fig_top＝整張圖的大標題的高度（panel_layout 照這些留空間，任何大小都不藏標題）；
    fig_title＝大標題的文字物件（每次照當時的寬高擺在所有 panel 最上面、座標區的中間；只匯出某幾張時不帶，和 MATLAB exportgraphics(ax) 一樣）；
    fits＝放不下要縮短的名稱（fit_user_text：y 軸、右軸名稱照座標區的高，x 軸名稱照座標區的寬，標題、副標題照座標區的寬再扣掉左右角的
    y 軸指數字（1e6 之類），大標題照所有座標區的寬），每次排版照當時的大小重新縮短（完整的字在設定裡，對話框看得到）。"""
    _adjust_compatible = True
    _colorbar_gridspec = True

    def __init__(self, axes: Sequence[Any], ratios: Sequence[float], labeled: Sequence[bool], style: dict,
                 right_in: float = RIGHT_MARGIN_IN, mins: Optional[Sequence[float]] = None,
                 fallback: Optional[Sequence[bool]] = None, drop_in: float = 0.0, tops: Optional[Sequence[float]] = None,
                 fig_top: float = 0.0, fig_title=None, fits: Optional[List[dict]] = None, **kwargs):
        super().__init__(**kwargs)
        self.axes = list(axes)
        self.ratios = [float(r) for r in ratios]
        self.labeled = [bool(b) for b in labeled]
        self.style = style
        self.right_in = float(right_in)
        self.mins = [float(m) for m in mins] if mins else None
        self.fallback = [bool(b) for b in fallback] if fallback is not None else None
        self.drop_in = float(drop_in)
        self.tops = [float(t) for t in tops] if tops else None
        self.fig_top = float(fig_top or 0.0)
        self.fig_title = fig_title
        self.fits = list(fits or [])
        self.screen_in: Optional[Tuple[float, float]] = None
        self.last: Optional[dict] = None
        self.last_export: Optional[dict] = None

    def set(self, **kwargs) -> None:
        for k, v in kwargs.items():
            setattr(self, k, v)

    @staticmethod
    def exporting(fig) -> bool:
        try:
            saving = bool(fig.canvas.is_saving())
        except Exception:
            saving = False
        return saving or bool(getattr(fig, "_pk_exporting", False))

    def same_as_screen(self, fig, w_in: float, h_in: float) -> bool:
        """匯出的大小和畫面上的畫布一樣（差不到一個輸出像素＋0.001 in：點陣輸出把寬高取成整數像素）。"""
        if self.screen_in is None:
            return False
        tol = 1.0 / max(float(fig.dpi), 1.0) + 1e-3
        return abs(float(w_in) - self.screen_in[0]) <= tol and abs(float(h_in) - self.screen_in[1]) <= tol

    def plan(self, fig) -> Tuple[List[bool], Optional[List[bool]], float, float]:
        """這次畫圖要標的（上面幾張）、可以退回的標法（None＝不退回）、最下面多留的拖放區（英吋）、放不下的容許誤差（英吋）。"""
        w_in, h_in = fig.get_size_inches()
        if not self.exporting(fig):
            self.screen_in = (float(w_in), float(h_in))
            return list(self.labeled), None, self.drop_in, LAYOUT_TOL_IN
        vis = [bool(ax.get_visible()) for ax in self.axes]
        if not all(vis):
            return [lb and v for lb, v in zip(self.labeled, vis)], None, 0.0, LAYOUT_TOL_IN
        if self.same_as_screen(fig, w_in, h_in):        # 用目前大小存（任何 DPI）：照畫面的標法；輸出取整數像素少掉的也不算放不下
            return list(self.labeled), None, 0.0, LAYOUT_TOL_IN + 1.0 / max(float(fig.dpi), 1.0) + 1e-3
        return list(self.labeled), self.fallback, 0.0, LAYOUT_TOL_IN

    def execute(self, fig) -> None:
        if not self.axes:
            return
        w_in, h_in = fig.get_size_inches()
        labeled, fallback, extra, tol = self.plan(fig)
        lay = panel_layout(w_in, h_in, self.ratios, labeled, self.style, self.right_in, self.mins, fallback, bottom_extra=extra,
                           tol=tol, tops=self.tops, fig_top=self.fig_top)
        self.last = lay
        if self.exporting(fig):
            self.last_export = lay
        x0, x1 = lay["left"], lay["right"]
        for ax, (y0, h) in zip(self.axes, lay["rows"]):
            pos = ax.get_position(original=True)
            if (abs(pos.x0 - x0) > 1e-9 or abs(pos.x1 - x1) > 1e-9 or abs(pos.y0 - y0) > 1e-9
                    or abs(pos.height - h) > 1e-9):
                ax._set_position([x0, y0, x1 - x0, h])
        for ax, full, now in zip(self.axes[:-1], self.labeled, lay["labeled"]):
            if full and ax.xaxis.label.get_visible() != bool(now):      # 只動「畫面上有標」的那幾張（收合的矮列本來就不標）
                ax.xaxis.label.set_visible(bool(now))
                ax.tick_params(axis="x", labelbottom=bool(now))
        ft = self.fig_title
        if ft is not None:
            whole = all(ax.get_visible() for ax in self.axes)          # 「只匯出這個 panel」：大標題屬於整張圖，不帶
            if ft.get_visible() != whole:
                ft.set_visible(whole)
            xy = ((x0 + x1) / 2.0, 1.0 - FIG_TITLE_PAD_PT / 72.0 / max(float(h_in), 1e-3))
            if tuple(ft.get_position()) != xy:
                ft.set_position(xy)
        self.fit_texts(float(w_in), float(h_in), x0, x1)

    def fit_texts(self, w_in: float, h_in: float, x0: float, x1: float) -> None:
        """名稱放不下就縮短加「…」（照這次的大小；字沒變就不動）。y 軸、右軸名稱：座標區的高；x 軸名稱、標題、副標題：座標區的寬；
        大標題：所有座標區的寬。畫出來的名稱那一段記在 _dsv_user_shown（英文介面的測試用：使用者打的字不翻譯）。"""
        for f in self.fits:
            art, ax = f.get("art"), f.get("ax")
            try:
                if f.get("dim") == "h":
                    avail = ax.get_position().height * h_in * 72.0
                elif f.get("dim") == "w":
                    avail = ax.get_position().width * w_in * 72.0
                elif f.get("dim") == "wt":                    # 標題、副標題：左右讓開 y 軸（和右軸）的指數字（1e6 之類，畫在座標區上緣的左右角）
                    side = float(f.get("side", 0.0))
                    for a2 in (ax, f.get("ax_r")):
                        ot = a2.yaxis.get_offset_text() if a2 is not None else None
                        if ot is not None and ot.get_visible() and ot.get_text():
                            fo = ot.get_fontproperties()
                            side = max(side, text_extent_pt(ot.get_text(), tuple(fo.get_family()), float(fo.get_size_in_points()),
                                                            str(fo.get_weight()))[0] + 4.0)
                    avail = ax.get_position().width * w_in * 72.0 - 2.0 * side
                else:
                    avail = (x1 - x0) * w_in * 72.0
                fp = art.get_fontproperties()
                txt, shown = fit_user_text(f.get("head", ""), f.get("name", ""), f.get("tail", ""), avail,
                                           tuple(fp.get_family()), float(fp.get_size_in_points()), str(fp.get_weight()))
            except Exception:
                continue
            art._dsv_user_shown = [shown] if shown else []
            if art.get_text() != txt:
                art.set_text(txt)


def _runs(flags: np.ndarray) -> List[Tuple[int, int]]:
    """bool 陣列裡 True 連續段 → [(start, end_exclusive), ...]。"""
    if flags.size == 0:
        return []
    d = np.diff(np.concatenate(([0], flags.astype(np.int8), [0])))
    starts = np.nonzero(d == 1)[0]
    ends = np.nonzero(d == -1)[0]
    return list(zip(starts.tolist(), ends.tolist()))


def diff_segments(group: List[Signal], tol: float) -> Tuple[List[Tuple[float, float]], float, bool]:
    """同一 panel 內 2 條以上訊號的差異區間（symbol 單位）、差異比例、是否為取樣比對（超過 MAX_DIFF_SAMPLES）。"""
    x0 = max(s.x_span[0] for s in group)
    x1 = min(s.x_span[1] for s in group)
    if x1 <= x0:                                  # 完全不重疊（例如 offset 推到別條訊號的範圍外）
        return [], 0.0, False
    step = 1.0 / max(s.sps for s in group)
    n = int(math.floor((x1 - x0) / step + 1e-9))
    if n <= 0:                                    # 重疊不到一個樣本
        return [], 0.0, False
    approx = n > MAX_DIFF_SAMPLES
    if approx:
        n = MAX_DIFF_SAMPLES
        step = (x1 - x0) / n
    xs = x0 + (np.arange(n) + 0.5) * step
    with np.errstate(invalid="ignore"), warnings.catch_warnings():
        warnings.simplefilter("ignore", RuntimeWarning)
        vals = np.vstack([s.values_at(xs) for s in group])
        spread = np.nanmax(vals, axis=0) - np.nanmin(vals, axis=0)
        flags = np.isfinite(spread) & (spread > tol)
        if approx:
            # 取樣只看每格中心的值，會漏掉單一樣本的差異：再比每格的 min／max（各訊號用自己的樣本算）
            edges = x0 + np.arange(n + 1) * step
            mins, maxs = [], []
            for s in group:
                y = s.get_data()
                m = len(y)
                if m == 0:
                    mins.append(np.full(n, np.nan))
                    maxs.append(np.full(n, np.nan))
                    continue
                bounds = np.clip(np.ceil((edges - s.x0) * s.sps - 1e-9).astype(np.int64), 0, m)
                lo_i, hi_i = bounds[:-1], bounds[1:]
                valid = hi_i > lo_i                              # 這格裡有沒有這條訊號的樣本
                idx = np.append(np.minimum(lo_i, m - 1), min(int(hi_i[-1]), m - 1))
                mn = np.minimum.reduceat(y, idx)[:-1]
                mx = np.maximum.reduceat(y, idx)[:-1]
                mins.append(np.where(valid, mn, np.nan))
                maxs.append(np.where(valid, mx, np.nan))
            mins = np.vstack(mins)
            maxs = np.vstack(maxs)
            d_min = np.nanmax(mins, axis=0) - np.nanmin(mins, axis=0)
            d_max = np.nanmax(maxs, axis=0) - np.nanmin(maxs, axis=0)
            flags |= (np.isfinite(d_min) & (d_min > tol)) | (np.isfinite(d_max) & (d_max > tol))
    ratio = float(flags.sum()) / n
    runs = _merge_runs(_runs(flags), MAX_DIFF_SEGMENTS)
    return [(x0 + a * step, x0 + b * step) for a, b in runs], ratio, approx


def _merge_runs(runs: List[Tuple[int, int]], limit: int) -> List[Tuple[int, int]]:
    """區間 [(start, end_exclusive), ...]（已排序）超過 limit 段時，合併相鄰的區間：間距門檻從 1 開始、每次加倍，直到 ≤ limit 段
    （差異比對的畫法；錯誤率比對的紅色區段也用，見 _merge_run_arrays）。"""
    if len(runs) <= limit:
        return runs
    starts, ends = _merge_run_arrays(np.array([r[0] for r in runs]), np.array([r[1] for r in runs]), limit)
    return list(zip(starts.tolist(), ends.tolist()))


def _merge_run_arrays(starts: np.ndarray, ends: np.ndarray, limit: int) -> Tuple[np.ndarray, np.ndarray]:
    """_merge_runs 的陣列版（區間很多時不用先做成 Python 的 list）：回傳合併後的 (starts, ends)。"""
    gap = 1
    while len(starts) > limit:                   # 合併相鄰區間，逐步放寬間距
        keep = np.concatenate(([True], (starts[1:] - ends[:-1]) > gap))
        idx = np.nonzero(keep)[0]
        starts = starts[idx]
        ends = ends[np.append(idx[1:] - 1, len(ends) - 1)]
        gap *= 2
    return starts, ends


def add_spans(ax, spans: Sequence[Tuple[float, float]]):
    """x 區間 [(a, b), ...] 畫成座標區整個高度的半透明紅色區段（x 用資料座標、y 用座標區比例，不受 ylim 與 twin 影響；zorder 0 在線的下面）：
    「標示差異區間」與錯誤率比對（有錯的符號）共用同一種畫法。回傳加進去的 PolyCollection。"""
    verts = [[(float(a), 0.0), (float(b), 0.0), (float(b), 1.0), (float(a), 1.0)] for a, b in spans]
    coll = PolyCollection(verts, facecolors="#ff3030", alpha=0.18, edgecolors="none", zorder=0, transform=ax.get_xaxis_transform())
    ax.add_collection(coll, autolim=False)
    return coll


def effective_ptype(ptype: str, n: int) -> str:
    """實際畫法：stem 超過 MAX_STEM_POINTS 點改用 line（太慢）。"""
    pt = ptype if ptype in PLOT_TYPE_KEYS else DEFAULT_PLOT_TYPE
    return "line" if (pt == "stem" and n > MAX_STEM_POINTS) else pt


def ptype_marker(sig: "Signal", ptype: str, n: int) -> Tuple[str, Any]:
    """(marker, markevery)：stairs 的頂點多一個結尾點（不標）；stem 的線是「基線→值→基線」三點一組，只標中間的針頭
    （沒設 marker 時用 MATLAB stem 預設的空心圓）；點數超過 MAX_MARKER_POINTS 一律不畫 marker。"""
    if n > MAX_MARKER_POINTS:
        return "", None
    if ptype == "stem":
        return (sig.marker or "o"), slice(1, None, 3)
    if not sig.marker:
        return "", None
    return sig.marker, (slice(0, -1) if ptype == "stairs" else None)


def ptype_xy(ptype: str, x: np.ndarray, yp: np.ndarray, base: float = 0.0) -> Tuple[np.ndarray, np.ndarray]:
    """依繪圖類型產生 Line2D 的頂點。x 是 step_xy() 的 N+1 個邊界，yp 是畫面上的 y（含 Normalize／ystack）。
    stairs：N+1 點配 step(where="post")；line：N 個樣本點；stem：每個樣本「基線→值→基線」三點一組的單一路徑
    （一條 Line2D 就是全部的針＋基線，1e6 點約 0.3 s；比 LineCollection 快 10 倍以上，也能直接做點選判定）。"""
    if ptype == "stairs":
        return x, np.append(yp, yp[-1]) if len(yp) else yp
    xs = x[:-1]
    if ptype == "line":
        return xs, yp
    xx = np.repeat(xs, 3)
    yy = np.full(3 * len(yp), float(base))
    yy[1::3] = yp
    return xx, yy


def render(fig, signals: List[Signal], opts: dict, xlim=None) -> dict:
    """把訊號畫到 fig 上；回傳 panel / axes / 差異區間 / artist 等資訊給狀態列、游標與 Interactor 用。

    隱藏的訊號不畫、不比差異；yaxis="right" 的畫在該 panel 的 twinx 上；標註與資料提示不在這裡畫
    （由 plotkit.Interactor.rebuild() 依模型重建）。
    每個 panel 有自己的 x 軸、x 單位、Symbol rate、y 單位（opts["panels"]）；「連結時間」勾著的一起縮放平移（link_x_axes）。
    xlim：{panel: (lo, hi)}（各自的 symbol 座標；沒有的自動）或一組 (lo, hi)（舊呼叫：每個 panel 都用它）。
    """
    info: Dict[str, Any] = {"panels": [], "axes": [], "axes_right": {}, "panel_of_ax": {}, "groups": {},
                            "all_groups": {}, "diff_segments": {}, "diff_ratio": {}, "spikes": 0, "points": 0,
                            "artists": {}, "colors": {}, "legend_uids": {}, "hidden": [], "style": None,
                            "style_lw": 1.0, "marker_skipped": 0, "stem_fallback": 0, "errmark_artists": []}
    fig.clear()
    if isinstance(fig.get_layout_engine(), PanelLayout):
        fig.set_layout_engine(None)                  # 上一次的版面引擎（沒有 panel 時不留著）；有 panel 時下面換新的
    style = pk.get_style(opts.get("style") or "default")
    info["style"] = style
    info["style_lw"] = float(style.get("lw", 1.0))
    palette = list(style.get("colors") or PALETTE)
    info["palette"] = palette                      # 右鍵「顏色」色塊用目前風格的色序
    sigs = [s for s in signals if s is not None]
    info["hidden"] = [s.uid for s in sigs if not s.visible]
    if not sigs:
        fig.set_facecolor(style.get("fig_face", "white"))
        fig.text(0.5, 0.5, tr("尚無訊號：在左側「資料夾」面板選檔案，按「加入選取的」"),
                 ha="center", va="center", fontsize=11, color=style.get("text_color", "gray"), alpha=0.7, wrap=True)
        return info
    order: List[int] = []
    all_groups: Dict[int, List[Signal]] = {}
    for s in sigs:                               # 依 panel 第一次出現的順序分組（含隱藏，顏色序號才穩定）
        if s.panel not in all_groups:
            all_groups[s.panel] = []
            order.append(s.panel)
        all_groups[s.panel].append(s)
    # B1：等來源檔案回來的訊號（佔位訊號與它的衍生訊號）和隱藏的一樣不畫，只有它們的 panel 也不畫（panel 編號、設定照留；檔案回來就畫回原 panel）
    info["waiting"] = [s.uid for s in sigs if s.waiting()]
    groups: Dict[int, List[Signal]] = {p: [s for s in all_groups[p] if s.visible and not s.waiting()] for p in order}
    panels = [p for p in order if groups[p]]
    info["all_groups"] = all_groups
    if not panels:
        fig.set_facecolor(style.get("fig_face", "white"))
        fig.text(0.5, 0.5, tr("所有訊號都已隱藏：在清單的「顯示」欄勾回來"),
                 ha="center", va="center", fontsize=11, color=style.get("text_color", "gray"), alpha=0.7, wrap=True)
        return info
    collapsed = {int(p) for p in (opts.get("collapsed") or [])}
    info["collapsed"] = sorted(p for p in panels if p in collapsed)
    info["collapsed_uids"] = []
    ratios = [COLLAPSED_RATIO if p in collapsed else 1.0 for p in panels]
    axes = fig.subplots(len(panels), 1, squeeze=False, gridspec_kw={"height_ratios": ratios})[:, 0]
    units = {p: panel_units(opts, p) for p in panels}          # 每個 panel 的 (x 單位, Symbol rate)
    linked = {p: panel_linked(opts, p) for p in panels}
    info["xlink"] = link_x_axes(dict(zip(panels, axes)), panels, linked, units)   # 要在 twinx 之前
    info["units"] = units
    tol = float(opts.get("tol") or 0.0)
    ystack = float(opts.get("ystack") or 0.0)
    info["ystack"] = ystack
    normalize = bool(opts.get("normalize"))       # Normalize Y：每條線除以自己的峰值絕對值（只影響畫面，資料不動）
    info["normalize"] = normalize
    dashed = bool(opts.get("dashed"))
    markers = bool(opts.get("markers"))
    show_spikes = bool(opts.get("show_spikes", True))
    want_diff = bool(opts.get("diff", True))
    all_axes: List[Any] = []
    fits: List[dict] = []                           # 放不下要縮短的名稱（PanelLayout.fit_texts）
    for ax, p in zip(axes, panels):
        grp = groups[p]
        ax._pk_role = "left"
        ax._dsv_panel = p
        info["panel_of_ax"][id(ax)] = p
        all_axes.append(ax)
        if p in collapsed:                           # 收合：只畫一條矮列，標題留著、線不畫（資料提示保留在模型裡，展開後回來）
            info["axes_right"][p] = None
            info["collapsed_uids"].extend(s.uid for s in grp)
            ax.set_yticks([])
            ax.set_ylabel(PANEL_GRIP + tr("P{p}").format(p=p))
            ax.text(0.5, 0.5, tr("已收合：{n} 條訊號（{names}）").format(n=len(grp), names=tr("、").join(s.name for s in grp)[:60]),
                    transform=ax.transAxes, ha="center", va="center", fontsize=8, color=style.get("text2", style.get("text_color", "gray")), clip_on=True)
            continue
        ax_r = None
        if any(s.yaxis == "right" for s in grp):
            ax_r = ax.twinx()
            ax_r._pk_role = "right"
            ax_r._dsv_panel = p
            ax_r._pk_xlink = getattr(ax, "_pk_xlink", None)
            info["panel_of_ax"][id(ax_r)] = p
            all_axes.append(ax_r)
        info["axes_right"][p] = ax_r
        lo = {"left": math.inf, "right": math.inf}
        hi = {"left": -math.inf, "right": -math.inf}
        digital = True
        has_left = False
        nfix = 0
        handles = []
        bus_plan, bus_pure = dsv_bus.plan_panel(grp)     # 數位匯流排（六角框＋數值）的配置
        for s in grp:
            j = all_groups[p].index(s)
            x, y = s.step_xy()
            info["points"] += len(y)
            if len(y) == 0:
                continue
            side = "right" if (s.yaxis == "right" and ax_r is not None) else "left"
            tgt = ax_r if side == "right" else ax
            j_side = [t for t in all_groups[p]              # ystack 每一側各自從 0 疊起（右軸單位和左軸無關）
                      if ("right" if (t.yaxis == "right" and ax_r is not None) else "left") == side].index(s)
            gain = norm_gain(y) if normalize else 1.0
            yp = (y * gain if gain != 1.0 else y) + j_side * ystack
            auto_color = palette[j % len(palette)]
            auto_ls = AUTO_LINESTYLES[j % len(AUTO_LINESTYLES)] if dashed else "-"
            color = s.color or auto_color
            ls = s.ls or auto_ls
            lw = float(s.lw) if s.lw else info["style_lw"]
            pt = effective_ptype(s.ptype, len(y))
            if pt != s.ptype and s.ptype in PLOT_TYPE_KEYS:
                info["stem_fallback"] += 1
            marker, mevery = ptype_marker(s, pt, len(y))
            if (s.marker or pt == "stem") and not marker:
                info["marker_skipped"] += 1
            kw: Dict[str, Any] = {"color": color, "ls": ls, "lw": lw, "label": s.name}
            if marker:
                kw.update(marker=marker, ms=float(s.ms or DEFAULT_MS), markevery=mevery)
                if pt == "stem":
                    kw["mfc"] = "none"                 # MATLAB stem 預設空心針頭
            bus_extra = None
            if s.uid in bus_plan:                      # 數位匯流排（dsv_bus）優先於繪圖類型
                ln, bus_extra = dsv_bus.draw_bus(tgt, s, x, y, yp, bus_plan[s.uid], kw)
                yp = np.full(len(y), bus_extra["bus_center"])
            else:
                base = j_side * ystack                 # stem 的基線＝這條線的 0（含疊圖 y 位移）
                lx, ly = ptype_xy(pt, x, yp, base)
                if pt == "stairs":
                    ln, = tgt.step(lx, ly, where="post", **kw)
                else:
                    ln, = tgt.plot(lx, ly, **kw)
                pk.lod.enable(ln)                      # 大資料：畫面只畫看得到範圍的 M4 子集（資料、點選判定不變）
            ln._dsv_uid = s.uid                       # 點選線條時用來找回訊號
            ln._pk_uid = s.uid
            arts: Dict[str, Any] = {"line": ln, "markers": None, "ax": tgt, "panel": p, "yaxis": side,
                                    "lw": lw, "auto_color": auto_color, "auto_ls": auto_ls, "j": j_side, "gain": gain,
                                    "ptype": "bus" if bus_extra else pt}
            if bus_extra:
                arts.update(bus_extra)
            if markers and not marker and pt != "stem" and len(y) <= MAX_MARKER_POINTS and not bus_extra:
                arts["markers"], = tgt.plot(x[:-1], yp, ls="", marker=".", ms=3, color=color)
            info["artists"][s.uid] = arts
            info["colors"][s.uid] = color
            handles.append(ln)
            if show_spikes and s.spike_mask is not None and s.spike_mask.any():
                idx = np.nonzero(s.spike_mask)[0]
                tgt.plot(x[idx], yp[idx], ls="", marker="x", color=style.get("spike_color", "red"), ms=6, mew=1.2,
                         label="_nolegend_")
                nfix += int(len(idx))
            fin = yp[np.isfinite(yp)]
            if bus_extra:
                fin = np.array([bus_extra["bus_center"] - bus_extra["bus_half"], bus_extra["bus_center"] + bus_extra["bus_half"]])
            if fin.size:
                lo[side] = min(lo[side], float(fin.min()), base if pt == "stem" else math.inf)
                hi[side] = max(hi[side], float(fin.max()), base if pt == "stem" else -math.inf)
            if side == "left":
                has_left = True
                if digital and (bus_extra or not np.all((y == 0) | (y == 1))):
                    digital = False
        info["spikes"] += nfix

        def _lims(side: str) -> Tuple[float, float]:
            a, b = lo[side], hi[side]
            if not math.isfinite(a):
                a, b = 0.0, 1.0
            rng = b * 0.5 - a * 0.5                    # 先除 2 再相減：±1e308 這種範圍 b − a 會溢位成 inf
            if rng == 0:
                rng = (abs(b) or 1.0) * 0.5
            big = 8e307                                # matplotlib 3.10／3.11 實測：|範圍| ≥ 1e308 時 MaxNLocator 的 arange 溢位（MATLAB 可以到 realmax）
            return max(a - 0.16 * rng, -big), min(b + 0.16 * rng, big)

        if not has_left:
            ax.set_yticks([])
            ylo, yhi = 0.0, 1.0
        elif digital and ystack == 0:
            ax.set_yticks([0, 1])
            ylo, yhi = -0.2, 1.2
        else:
            ylo, yhi = _lims("left")
        cmp = [s for s in grp if info["artists"].get(s.uid, {}).get("yaxis", "left") == "left"]
        if len(cmp) < 2:                              # 左右軸尺度不同不互比：左軸不足 2 條才比右軸的
            cmp = [s for s in grp if info["artists"].get(s.uid, {}).get("yaxis") == "right"]
        if want_diff and len(cmp) >= 2:
            segs, ratio, approx = diff_segments(cmp, tol)
            info["diff_segments"][p] = segs
            info["diff_ratio"][p] = ratio
            info.setdefault("diff_approx", {})[p] = approx
            if segs:                                  # 用 x 資料／y 軸比例座標畫，不受 ylim 與 twin 影響
                add_spans(ax, segs)
        em = (opts.get("errmarks") or {}).get(p)
        if em:                                        # 錯誤率比對（第四批 T5）有錯的符號：和差異區間同一種畫法
            info["errmark_artists"].append(add_spans(ax, em))
        ax.set_ylim(ylo, yhi)
        dsv_bus.finish_axes(ax, ax_r, bus_pure)
        pp_ = (opts.get("panels") or {}).get(p) or {}
        yunit = str(pp_.get("yunit") or "").strip()
        yname = clean_user_text(pp_.get("yname"))
        # y 軸：「≡ P1 電壓 [V]」——自訂名稱接在 P 編號後面，單位照 y 單位與 Normalize 自動接（2026-10-26 使用者選的；名稱空白＝「≡ P1 [V]」）
        y_head = PANEL_GRIP + tr("P{p}").format(p=p) + (" " if yname else "")
        y_tail = ((" [norm]" if normalize else (f" [{safe_user_text(yunit)}]" if yunit else ""))
                  + (tr(" [{n} spike fixed]").format(n=nfix) if nfix else ""))
        ax.set_ylabel(y_head + safe_user_text(yname) + y_tail)
        ax.yaxis.label._dsv_user_fixed = [safe_user_text(yunit)] if (yunit and not normalize) else []
        ax.yaxis.label._dsv_user_shown = [safe_user_text(yname)] if yname else []
        if yname:
            fits.append({"art": ax.yaxis.label, "ax": ax, "dim": "h", "head": y_head, "name": yname, "tail": y_tail})
        if ax_r is not None:
            ax_r.set_ylim(*_lims("right"))
            rname = clean_user_text(pp_.get("yname_right"))
            ax_r.set_ylabel(safe_user_text(rname) if rname else tr("右軸"))      # 右軸名稱空白＝照舊「右軸」
            ax_r.yaxis.label._dsv_user_shown = [safe_user_text(rname)] if rname else []
            if rname:
                fits.append({"art": ax_r.yaxis.label, "ax": ax_r, "dim": "h", "head": "", "name": rname, "tail": ""})
        if opts.get("legend", True) and handles:
            top = ax_r if ax_r is not None else ax
            leg = pk.draw.build_legend(top, handles, [h.get_label() for h in handles], style,
                                       loc=(opts.get("legend_loc") or {}).get(p, "upper right"))
            info["legend_uids"][p] = [h._dsv_uid for h in handles]
            for t_, h in zip(leg.get_texts(), handles):
                t_._dsv_uid = h._dsv_uid
    show_x = x_label_panels(panels, collapsed)
    info["xlabel_panels"] = sorted(show_x)
    for ax, p in zip(axes, panels):                  # 每個 panel 自己的刻度格式（顯示單位）；每張都標 x 刻度與 x 軸標籤（收合的矮列除外）
        f = x_display_factor(opts, p)
        ax.xaxis.set_major_formatter(FuncFormatter(lambda v, pos, f=f: f"{v * f:.6g}"))
        if p in show_x:
            xname = clean_user_text(((opts.get("panels") or {}).get(p) or {}).get("xname"))
            x_tail = f" [{units[p][0]}]"
            ax.set_xlabel((safe_user_text(xname) if xname else "x") + x_tail)      # 「時間 [us]」：自訂名稱取代「x」，單位照 x 單位自動接
            ax.xaxis.label._dsv_user_shown = [safe_user_text(xname)] if xname else []
            if xname:
                fits.append({"art": ax.xaxis.label, "ax": ax, "dim": "w", "head": "", "name": xname, "tail": x_tail})
        else:
            ax.tick_params(axis="x", labelbottom=False)
    xl_map = dict(xlim) if isinstance(xlim, dict) else ({p: xlim for p in panels} if xlim is not None else {})
    for ax, p in zip(axes, panels):
        xl = xl_map.get(p)
        if xl is not None and all(map(math.isfinite, xl)) and xl[1] > xl[0]:
            ax.set_xlim(float(xl[0]), float(xl[1]))
    lp = [p for p in panels if p in info["xlink"] and p not in collapsed]
    if lp and not any(xl_map.get(p) is not None for p in lp) and len({units[p][1] for p in lp}) > 1:
        lo_t, hi_t = math.inf, -math.inf             # 連結的 panel Symbol rate 不同、又是自動範圍：對齊到大家資料的聯集（同一段時間）
        for ax, p in zip(axes, panels):
            if p in lp:
                a, b = ax.get_xlim()
                lo_t, hi_t = min(lo_t, a / units[p][1]), max(hi_t, b / units[p][1])
        if hi_t > lo_t and math.isfinite(lo_t) and math.isfinite(hi_t):
            for ax, p in zip(axes, panels):
                if p in lp:
                    ax.set_xlim(lo_t * units[p][1], hi_t * units[p][1])
    pk.apply_style(fig, all_axes, style, grid=bool(opts.get("grid", True)))
    for a in all_axes:                               # 名稱有 $…$ 數學式時，數學式外面的字（中文名稱）要用有那些字的字型（math_font_family）
        for lab_ in (a.xaxis.label, a.yaxis.label):
            if matplotlib.cbook.is_math_text(lab_.get_text()):
                lab_.set_fontfamily(math_font_family(lab_.get_fontfamily(), lab_.get_text(), lab_.get_fontweight()))
    # 標題、副標題（每個展開的 panel 上面；收合的矮列只有「≡ P1」）與整張圖的大標題（MATLAB title／subtitle／sgtitle 的字級比例）
    pnames = opts.get("panels") or {}
    tc = style.get("text_color", "black")
    tops: List[float] = []
    info["title_artists"] = {}
    side_pt = TITLE_SIDE_EM * float(style.get("fontsize", 10.0) or 10.0)
    for ax, p in zip(axes, panels):
        pp_ = pnames.get(p) or {}
        t_ = clean_user_text(pp_.get("title")) if p not in collapsed else ""
        st_ = clean_user_text(pp_.get("subtitle")) if p not in collapsed else ""
        y_t, y_s, room = title_offsets_pt(t_, st_, style)
        tops.append(room / 72.0)
        arts_t: Dict[str, Any] = {}
        for role, txt_, y_ in (("subtitle", st_, y_s), ("title", t_, y_t)):
            if not txt_:
                continue
            shown_ = safe_user_text(txt_)
            fam_, size_, weight_ = _text_font(style, role, shown_)
            art = ax.text(0.5, 1.0, shown_, transform=ax.transAxes + ScaledTranslation(0.0, y_ / 72.0, fig.dpi_scale_trans),
                          ha="center", va="bottom", fontfamily=list(fam_), fontsize=size_, fontweight=weight_, color=tc, clip_on=False)
            art._dsv_role, art._dsv_panel, art._dsv_user_shown = role, p, [shown_]
            arts_t[role] = art
            fits.append({"art": art, "ax": ax, "ax_r": info["axes_right"].get(p), "dim": "wt", "side": side_pt,
                         "head": "", "name": txt_, "tail": ""})
        if arts_t:
            info["title_artists"][p] = arts_t
    info["title_rooms"] = {p: t for p, t in zip(panels, tops)}
    ftitle = clean_user_text(opts.get("figure_title"))
    fig_top = figure_title_room_in(ftitle, style)
    info["figure_title_artist"] = None
    if ftitle:
        shown_ = safe_user_text(ftitle)
        fam_, size_, weight_ = _text_font(style, "figure", shown_)
        art = fig.text(0.5, 1.0, shown_, ha="center", va="top", fontfamily=list(fam_), fontsize=size_, fontweight=weight_, color=tc)
        art._dsv_role, art._dsv_user_shown = "figure_title", [shown_]
        info["figure_title_artist"] = art
        fits.append({"art": art, "ax": None, "dim": "fig", "head": "", "name": ftitle, "tail": ""})
    info["fig_top"] = fig_top
    try:            # x 刻度字只有數字（上面的 FuncFormatter）：只給第一個字型（數字本來就用它畫，畫出來一模一樣），不帶中文字型的備援清單——
        fam1 = pk.styles.resolved_fonts(style)[:1]  # 每張都標 x 軸之後刻度字多了好幾組，備援清單每次重畫都要查（8 張約多 8 ms）
        for ax in axes:
            ax.tick_params(axis="x", labelfontfamily=fam1)
    except Exception:
        pass
    has_right = any(info["axes_right"].values())
    # 有右軸時留位置給右軸刻度與標籤；沒有時至少放得下半個四位數的刻度字（縮放到刻度剛好在右緣時不被圖的邊切掉，字級大也一樣）
    right_in = 0.75 if has_right else max(RIGHT_MARGIN_IN, 1.24 * float(style.get("fontsize", 10.0) or 10.0) / 72.0)
    # 版面用英吋排（第 11 項）：每張的 x 刻度字＋標籤放在它下面的空隙裡，不壓到下一張的座標區、圖例；收合的矮列下面不放大；
    # 每次畫圖都照當時的圖大小重排（存成圖檔換了寬高也對）。_resize_canvas 已經把畫布加高，圖本身不被壓扁。
    # 每列的高度下限：放得下它自己的圖例（只有那一列加高）；存成圖檔的大小放不下每張的標籤時退回 0.9.8 的標法（x_label_panels_shared）
    shared_x = x_label_panels_shared(panels, collapsed, linked, units)
    # 圖例的高度用畫好的圖例實際量（中文、重音大寫的標籤比照條數估的高：2026-10-25 第三輪審查）；主視窗的畫布也照量到的加高（legend_mins）
    measured: List[Optional[float]] = []
    try:
        rr = fig.canvas.get_renderer()
    except Exception:
        rr = None
    for ax, p in zip(axes, panels):
        top = info["axes_right"].get(p) or ax
        measured.append(legend_row_min(top.get_legend(), rr, float(fig.dpi)) if rr is not None and p not in collapsed else None)
    info["legend_mins"] = {p: m for p, m in zip(panels, measured) if m is not None}
    mins = panel_row_mins(ratios, [len(info["legend_uids"].get(p, [])) for p in panels], style, measured)
    # 自訂的 x 軸名稱比一行字高（中文字型、數學式）時，每個標籤空隙都照最高的那個加（x_label_room 看 style 的 xlabel_extra_pt）
    style["xlabel_extra_pt"] = x_label_extra_pt([a.xaxis.label.get_text() for a, p in zip(axes, panels)
                                                 if p in show_x and a.xaxis.label._dsv_user_shown], style)
    eng = PanelLayout(axes, ratios, [p in show_x for p in panels[:-1]], style, right_in, mins=mins,
                      fallback=[p in shared_x for p in panels[:-1]], drop_in=DROP_STRIP_IN if opts.get("drop_strip") else 0.0,
                      tops=tops, fig_top=fig_top, fig_title=info["figure_title_artist"], fits=fits)
    fig.set_layout_engine(eng)
    eng.execute(fig)                                 # 現在就排好（transData、刻度位置才正確），之後每次畫圖再照當時的大小排
    info["layout"] = eng
    big = pk.interact.MAX_DRAWABLE_LIM
    for a in all_axes:                               # 強制算好延遲的自動範圍，transData 才正確
        for get, put in ((a.get_xlim, a.set_xlim), (a.get_ylim, a.set_ylim)):
            lo_, hi_ = get()
            if not pk.interact.drawable_limits((lo_, hi_)):     # offset／x 範圍／資料到 ±1e308：matplotlib 刻度會溢位 → 夾到畫得出來的範圍
                lo_ = min(max(lo_, -big), big) if math.isfinite(lo_) else -big
                hi_ = min(max(hi_, -big), big) if math.isfinite(hi_) else big
                put(lo_, hi_ if hi_ > lo_ else lo_ + abs(lo_) * 1e-9 + 1.0)
    if not has_right:                                # 最右邊的 x 刻度字剛好在右緣（資料長度是整數時常見）：右邊留白加到放得下，不被圖的邊切掉
        need = max([x_tick_overhang(ax, style) for ax, p in zip(axes, panels) if p in show_x] + [0.0]) + 0.03
        if need > eng.right_in:
            for _ in range(2):                       # 座標區變窄，刻度離右緣的距離跟著變：再算一次
                eng.right_in = min(1.5, need)
                eng.execute(fig)
                need = max([x_tick_overhang(ax, style) for ax, p in zip(axes, panels) if p in show_x] + [0.0]) + 0.03
                if need <= eng.right_in:
                    break
    info["panels"] = panels
    info["axes"] = list(axes)
    info["groups"] = groups
    return info

# ---------------------------------------------------------------------------
# 像 MATLAB 的 plot edit：訊號快照（複製貼上用）與點選線條的判定
# ---------------------------------------------------------------------------
CLIPBOARD = pk.CLIPBOARD            # 和 plotkit 共用同一個剪貼簿 list（內容是 pk.Series）


def make_snapshot(sig: Signal, opts: dict, color: Optional[str] = None, lw: Optional[float] = None,
                  ls: Optional[str] = None) -> "pk.Series":
    """把一條訊號目前畫的資料存成 plotkit Series（x 已換成顯示單位），給圖片視窗貼上疊圖用。"""
    x, y = sig.step_xy()
    factor = x_display_factor(opts, sig.panel)          # 那條訊號所在 panel 的 x 單位
    style_lw = float(pk.get_style(opts.get("style") or "default").get("lw", 1.0))
    pt = effective_ptype(sig.ptype, len(y))
    kind, marker, ls = "step", sig.marker or "", ls or sig.ls or "-"
    bus = dsv_bus.is_bus(sig)
    if bus:                               # 數位匯流排：圖片視窗也畫六角框＋數值（plotkit Series.disp="digital"；進位制／位元寬度照主圖）
        marker = ""
    elif pt != "stairs":                  # line：樣本點連線；stem：圖片視窗沒有針狀線，只帶針頭（樣本點＋marker、不連線）
        x = x[:-1]
        kind = "line"
        if pt == "stem":
            marker, ls = (sig.marker or "o"), "None"
    return pk.Series(label=sig.name, x=np.asarray(x, dtype=float) * factor, y=np.asarray(y, dtype=float),
                     kind=kind, color=color or sig.color or PALETTE[0], lw=float(lw or sig.lw or style_lw),
                     ls=ls, marker=marker, ms=sig.ms, xunit=panel_units(opts, sig.panel)[0],
                     meta={"key": sig.key, "path": sig.path, "sps": sig.sps, "offset": sig.offset, "ptype": sig.ptype},
                     disp="digital" if bus else "analog", radix=dsv_bus.bus_radix(sig) if bus else "",
                     bits=dsv_bus.effective_bits(sig) if bus else 0)

hit_test_lines = pk.draw.hit_test_lines   # 與 plotkit 共用（含 x 未排序的保護）


# ---------------------------------------------------------------------------
# 5b. 量測（MATLAB Time Scope／Signal Analyzer：Signal Statistics 與 Bilevel Measurements → Cycles）、
#     轉態位置、Normalize Y —— 純計算，和 GUI 分開方便測試；全部 numpy 向量化（1e6 點各約數十 ms）
# ---------------------------------------------------------------------------
# (鍵, 介面名稱)；名稱的英文就是 MATLAB 的欄名（Time Scope 介面顯示的欄名）
MEAS_STAT_ROWS = (("samples", "樣本數"), ("max", "最大值"), ("min", "最小值"), ("p2p", "峰對峰值"), ("mean", "平均值"),
                  ("var", "變異數"), ("std", "標準差"), ("median", "中位數"), ("rms", "RMS"), ("msq", "均方值"))
MEAS_PULSE_ROWS = (("npos", "+脈波數"), ("nneg", "−脈波數"), ("period", "週期"), ("freq", "頻率"),
                   ("width", "+脈寬"), ("duty", "+工作週期"), ("nwidth", "−脈寬"), ("nduty", "−工作週期"))
# Time Scope Bilevel：Transitions（+ Edges／− Edges：Rise／Fall Time、Slew Rate）與 Aberrations（+／− Transitions：Preshoot、
# Overshoot、Undershoot、Settling Time）；面板上是逐轉態的平均（MathWorks「Scope Bilevel Measurements」）
MEAS_TRANS_ROWS = (("pedges", "+邊緣數"), ("rise", "上升時間"), ("pslew", "+迴轉率"),
                   ("nedges", "−邊緣數"), ("fall", "下降時間"), ("nslew", "−迴轉率"))
MEAS_ABERR_ROWS = (("ppre", "+前衝"), ("pover", "+過衝"), ("punder", "+下衝"), ("psettle", "+穩定時間"),
                   ("npre", "−前衝"), ("nover", "−過衝"), ("nunder", "−下衝"), ("nsettle", "−穩定時間"))
MEAS_PEAK_ROWS = (("peaks", "峰值（值與位置）"),)  # 一個鍵：表格裡展開成 P1…PN（N＝Num Peaks）
MEAS_ROWS = MEAS_STAT_ROWS + MEAS_PEAK_ROWS + MEAS_TRANS_ROWS + MEAS_ABERR_ROWS + MEAS_PULSE_ROWS
MEAS_GROUP_KEYS = ("stats", "peaks", "trans", "aberr", "pulse")
DEFAULT_MEAS_GROUPS = "stats,pulse"              # 新的三組（峰值、轉態、過衝／下衝）預設關著，跟 Time Scope 一樣
MEAS_ROW_KEYS = tuple(k for k, _ in MEAS_ROWS)
MEAS_MAX_SIGNALS = 8             # 量測面板一次最多算幾條訊號（選取的；沒有選取時全部；表格一欄一條）
PULSE_REF = (0.1, 0.5, 0.9)      # 脈波量測的參考位準（MATLAB 預設 lower 10%／mid 50%／upper 90% of 狀態位準差）


def parse_meas_rows(text) -> List[str]:
    """設定字串（逗號分隔的列鍵）→ 依 MEAS_ROWS 順序的鍵清單；空字串／全是不認得的鍵 → 全部。"""
    want = {t.strip() for t in str(text or "").split(",") if t.strip()}
    keys = [k for k in MEAS_ROW_KEYS if k in want]
    return keys or list(MEAS_ROW_KEYS)


def signal_stats(y, x0: float = 0.0, dx: float = 1.0) -> dict:
    """MATLAB Signal Statistics：樣本 i 的 x = x0 + i·dx。NaN／inf 不算。Variance／Std 用 N−1（MATLAB var／std 預設）。
    回傳 samples、max／max_x、min／min_x（第一次出現的位置）、p2p、mean、var、std、median、rms、msq；沒有樣本時只有 samples=0。"""
    y = np.asarray(y, dtype=float)
    fin = np.isfinite(y)
    if fin.all():
        yy, pos = y, None
    else:
        pos = np.nonzero(fin)[0]
        yy = y[pos]
    n = int(yy.size)
    if n == 0:
        return {"samples": 0}
    imax, imin = int(np.argmax(yy)), int(np.argmin(yy))
    if pos is not None:
        imax, imin = int(pos[imax]), int(pos[imin])
    vmax, vmin = float(y[imax]), float(y[imin])
    mean = float(np.mean(yy))
    var = float(np.var(yy, ddof=1)) if n > 1 else 0.0
    msq = float(np.mean(yy * yy))
    return {"samples": n, "max": vmax, "max_x": x0 + imax * dx, "min": vmin, "min_x": x0 + imin * dx,
            "p2p": vmax - vmin, "mean": mean, "var": var, "std": math.sqrt(max(var, 0.0)),
            "median": float(np.median(yy)), "rms": math.sqrt(max(msq, 0.0)), "msq": msq}


def state_levels(y, nbins: int = 100) -> Tuple[float, float]:
    """雙位準訊號的低／高狀態位準＝MATLAB statelevels（histogram mode）：直方圖 100 格，下半、上半各取樣本最多那一格的
    「中心」（所以 0/1 數位訊號是 0.005／0.995，和 MATLAB 一樣）。實作在 dsv_measure。"""
    return dsv_measure.state_levels(y, nbins)


def pulse_edges(y, x0: float = 0.0, dx: float = 1.0) -> Tuple[np.ndarray, np.ndarray, float, float]:
    """雙位準訊號的轉態（MATLAB 定義，見 dsv_measure）：離開一個狀態的 2% 容差帶、進入另一個狀態的容差帶才算；
    位置＝50% 中位準交越的內插時刻（MATLAB midcross）。回傳 (edge_x, rising, low, high)。"""
    b = dsv_measure.bilevel(y, x0, dx)
    pol = np.asarray(b["pol"])
    return np.asarray(b["t_mid"], dtype=float), pol > 0, b["low"], b["high"]


def pulse_stats(y, x0: float = 0.0, dx: float = 1.0) -> dict:
    """Time Scope Bilevel Measurements → Cycles＝MATLAB pulsewidth／pulseperiod／dutycycle 的平均：
    npos／nneg＝完整的正／負脈波數；period＝相鄰兩次上升（中位準交越）的平均間隔；freq＝1/period；
    width／nwidth＝正／負脈波的平均寬度；duty／nduty＝逐脈波（寬度 ÷ 週期）的平均（%）。量不到的值是 None。"""
    sm = dsv_measure.summary(dsv_measure.bilevel(y, x0, dx))
    return {k: sm.get(k) for k in ("low", "high", "edges", "npos", "nneg", "period", "freq", "width", "duty", "nwidth", "nduty")}


def measure_signal(sig: "Signal", x_lo: float, x_hi: float, cfg: Optional[dict] = None) -> dict:
    """一條訊號在 x 範圍 [x_lo, x_hi]（symbol）內的統計＋雙位準（轉態、過衝／下衝、脈波）＋峰值，合成一個 dict（鍵見 MEAS_ROWS）。
    cfg：tol（%）、ref（下／中／上 %）、levels（None＝自動）、settle_d（Settle Seek，symbol）、peaks（None＝不找；
    {"num","min_height","min_dist","threshold"}）。"""
    cfg = cfg or {}
    y = sig.get_data()
    i0 = max(0, int(math.ceil((x_lo - sig.x0) * sig.sps - 1e-9)))
    i1 = min(len(y), int(math.floor((x_hi - sig.x0) * sig.sps + 1e-9)) + 1)
    seg = y[i0:i1] if i1 > i0 else np.zeros(0)
    dx = 1.0 / sig.sps
    x_first = sig.x0 + i0 * dx
    out = signal_stats(seg, x_first, dx)
    try:
        b = dsv_measure.bilevel(seg, x_first, dx, tol=float(cfg.get("tol", dsv_measure.DEFAULT_TOL)),
                                ref=tuple(cfg.get("ref", dsv_measure.DEFAULT_REF)), levels=cfg.get("levels"),
                                settle_d=cfg.get("settle_d"))
        out.update(dsv_measure.summary(b))
    except Exception as e:                             # 雙位準失敗：統計照樣顯示，那些列是 —
        log(f"雙位準量測失敗 {sig.name}: {e}")
    pk = cfg.get("peaks")
    if pk:
        try:
            v, idx = dsv_measure.find_peaks(seg, num=int(pk.get("num", 3)), min_height=float(pk.get("min_height", -math.inf)),
                                            min_dist=float(pk.get("min_dist", 1)), threshold=float(pk.get("threshold", 0.0)))
            out["peaks"] = [(float(vv), x_first + int(ii) * dx) for vv, ii in zip(v, idx)]
        except Exception as e:
            log(f"峰值搜尋失敗 {sig.name}: {e}")
            out["peaks"] = []
    out["range"] = (x_lo, x_hi)
    return out


def format_meas(key: str, res: dict, factor: float = 1.0, unit: str = "symbol", symbol_rate: float = DEFAULT_SYMBOL_RATE,
                vfmt=None) -> str:
    """量測值 → 表格文字。時間類（週期、脈寬、Max／Min 的位置）用 x 軸顯示單位；x 軸是 symbol 時另外換算成秒；頻率用 Hz
    （＝symbol_rate／週期[symbol]），後面括號是「每 x 單位」。"""
    if key not in res or res.get(key) is None:
        return "—"
    v = res[key]
    if isinstance(v, float) and not math.isfinite(v):
        return "—"
    if key in ("samples", "npos", "nneg", "pedges", "nedges"):
        return f"{int(v):,}"
    if key in ("rise", "fall", "psettle", "nsettle", "nwidth"):
        s = f"{v * factor:.6g} {unit}"
        if unit == "symbol" and symbol_rate:
            s += f" ({fmt_si(v / symbol_rate, 's')})"
        return s
    if key in ("pslew", "nslew"):
        s = f"{v / factor:.6g} /{unit}" if factor else f"{v:.6g} /symbol"
        if unit == "symbol" and symbol_rate:
            s += f" ({v * symbol_rate:.6g} /s)"
        return s
    if key in ("ppre", "pover", "punder", "npre", "nover", "nunder"):
        return f"{v:.4g} %"
    if key == "nduty":
        return f"{v:.4g} %"
    if key in ("max", "min"):
        return f"{(vfmt or fmt_num)(v)} @ x={float(res[key + '_x']) * factor:.6g}"
    if key in ("period", "width"):
        s = f"{v * factor:.6g} {unit}"
        if unit == "symbol" and symbol_rate:
            s += f" ({fmt_si(v / symbol_rate, 's')})"
        return s
    if key == "freq":
        per = res.get("period")
        if not per:
            return "—"
        return f"{fmt_si(symbol_rate / per, 'Hz')} ({1.0 / (per * factor):.6g} /{unit})"
    if key == "duty":
        return f"{v:.4g} %"
    if key == "p2p" and vfmt is not None:              # 進位制（dsv_bus.meas_formatter）只用在值類：Max／Min／峰對峰值
        return vfmt(v)
    return f"{float(v):.6g}"


def format_peak(p: Optional[Tuple[float, float]], factor: float = 1.0, vfmt=None) -> str:
    """峰值列的格子：「值 @ x=…」（Time Scope Peaks 表的 Value／Time）；沒有這個名次的峰 → —。"""
    if not p:
        return "—"
    v, x = p
    return f"{(vfmt or fmt_num)(v)} @ x={x * factor:.6g}"


def transition_x(sig: "Signal") -> np.ndarray:
    """訊號值改變的位置（symbol；樣本 i 和 i−1 不同 → x0 + i/sps，DSV stairs 的邊緣）。NaN 和 NaN 算相同。"""
    y = sig.get_data()
    if len(y) < 2:
        return np.zeros(0)
    a, b = y[1:], y[:-1]
    with np.errstate(invalid="ignore"):
        ch = (a != b) & ~(np.isnan(a) & np.isnan(b))
    return sig.x0 + (np.nonzero(ch)[0] + 1) / sig.sps


def norm_gain(y) -> float:
    """Normalize Y 的倍率＝1／峰值絕對值（Signal Analyzer 的 Normalize Y：每條線除以自己的最大絕對值）；全 0 或沒有有限值 → 1。"""
    y = np.asarray(y, dtype=float)
    fin = y[np.isfinite(y)]
    peak = float(np.max(np.abs(fin))) if fin.size else 0.0
    return 1.0 / peak if peak > 0 else 1.0


def snap_signal_x(sig: "Signal", x: float) -> float:
    """量測游標的 Snap to data：離 x 最近的樣本的 x（x0 + i/sps，DSV stairs 每一階的起點）。"""
    return pk.cursors.snap_to_grid(x, sig.x0, 1.0 / sig.sps, len(sig.get_data()))


def cursor_readout(signals: List["Signal"], xs: List[float], opts: dict) -> List[Tuple[str, List[str]]]:
    """量測游標的讀數（Time Scope 的 Cursor Measurements）：[(列名, [游標 1, 游標 2, Δ])]；一條游標時每列只有一格。
    第一列 x（顯示單位）、兩條時第二列 1/Δx（Hz：Δx 換算成秒＝Δx[symbol]／symbol rate），之後每條訊號在游標處的值與 Δy
    （sample-and-hold，跟十字游標一樣；游標在訊號範圍外＝—）。"""
    factor = x_display_factor(opts)
    unit = opts.get("xunit", "symbol")
    sr = float(opts.get("symbol_rate") or DEFAULT_SYMBOL_RATE)
    xs = [float(v) for v in xs][:2]
    if not xs:
        return []
    two = len(xs) == 2
    rows: List[Tuple[str, List[str]]] = []
    xr = [f"{v * factor:.6g}" for v in xs]
    if two:
        xr.append(f"{(xs[1] - xs[0]) * factor:.6g}")
    rows.append((f"x ({unit})", xr))
    if two:
        dx = abs(xs[1] - xs[0])
        rows.append(("1/Δx", ["", "", fmt_si(sr / dx, "Hz") if dx > 0 and sr > 0 else "—"]))
    for sg in signals:
        vals = [sg.value_at(v) for v in xs]
        cells = [dsv_bus.fmt_value(sg, v) for v in vals]
        if two:
            cells.append(fmt_num(vals[1] - vals[0]) if None not in vals else "—")
        rows.append((sg.name, cells))
    return rows


HCURSOR_TIP = ("MATLAB Time Scope 的 Screen Cursors → Horizontal：每個 panel 兩條水平游標（標 1、2，在右緣），可和垂直游標同時開；\n"
               "拖曳移動，點一下選取後 ↑／↓ 微調 1 像素（Shift ×10）；「游標量測」面板列出 y1、y2、Δy（左軸單位，有右軸另列右軸值）")


def hcursor_readout(info: dict, ys: Dict[Any, List[float]], signals: List["Signal"]) -> List[Tuple[str, List[str]]]:
    """水平游標（Screen Cursors → Horizontal）的讀數：每個 panel 一列「P{p} y」＝左軸的 y1、y2、Δy；
    有右軸的 panel 再一列「P{p} y 右軸」（同一個螢幕高度換成右軸的值）。Normalize Y 或疊圖 y 位移開著時，軸上的數字不是訊號的單位，
    所以再給該 panel 每條訊號一列「名稱 (y)」：(y − 疊圖位移) ／ normalize 倍率＝訊號原始單位（匯流排略過）。"""
    rows: List[Tuple[str, List[str]]] = []
    panels = list(info.get("panels") or [])
    axes = list(info.get("axes") or [])
    collapsed = set(info.get("collapsed") or [])
    norm = bool(info.get("normalize"))
    ystack = float(info.get("ystack") or 0.0)
    arts = info.get("artists") or {}

    def cells(v):
        return [fmt_num(v[0]), fmt_num(v[1]), fmt_num(v[1] - v[0])]

    for p, ax in zip(panels, axes):
        y = list(ys.get(p) or [])[:2]
        if len(y) < 2 or p in collapsed:
            continue
        rows.append((tr("P{p} y").format(p=p) + (" [norm]" if norm else ""), cells(y)))
        ax_r = (info.get("axes_right") or {}).get(p)
        yr = None
        if ax_r is not None:
            try:                                     # 同一個螢幕高度 → 右軸的資料 y（左右軸共用座標區框，尺度可以不同）
                inv = ax_r.transData.inverted()
                yr = [float(inv.transform(ax.transData.transform((0.0, v)))[1]) for v in y]
                rows.append((tr("P{p} y 右軸").format(p=p), cells(yr)))
            except Exception:
                yr = None
        if norm or ystack:
            for sg in signals:
                a = arts.get(sg.uid)
                if a is None or a.get("panel") != p or a.get("ptype") == "bus":
                    continue
                base = yr if a.get("yaxis") == "right" else y
                if base is None:
                    continue
                g = float(a.get("gain") or 1.0) or 1.0
                off = float(a.get("j") or 0) * ystack
                rows.append((f"{sg.name} (y)", cells([(b - off) / g for b in base])))
    return rows


# ---------------------------------------------------------------------------
# 6. 頻譜
# ---------------------------------------------------------------------------
def spectrum_type_values(stype: str, r: Dict[str, Any], which: str = "") -> np.ndarray:
    """dsv_spectrum.welch 的結果 → spectrum_units() 要的值。which：""＝平均（一般軌跡）、"max_"／"min_"＝最大／最小值保持。
    mag＝振幅（單邊 DC 與 Nyquist 以外是 √(2P)，雙邊 √P：剛好在 bin 上的正弦讀到振幅 A）；power／rms＝每個 bin 的功率 P；psd＝功率密度。"""
    if stype == "psd":
        return np.asarray(r[which + "psd"])
    P = np.asarray(r[which + "power"])
    if stype != "mag":
        return P
    amp = np.sqrt(np.maximum(P, 0.0))
    if r.get("mode") == "onesided" and amp.shape[-1] > 1:          # 頻率在最後一軸（頻譜圖是 (線, 頻率)）
        hi = amp.shape[-1] - 1 if r["nfft"] % 2 == 0 else amp.shape[-1]
        amp = amp.copy()
        amp[..., 1:hi] *= math.sqrt(2.0)
    return amp


def to_db(a, floor: float = 1e-12) -> np.ndarray:
    return 20.0 * np.log10(np.maximum(np.asarray(a, dtype=float), floor))


# --- 頻譜的類型與單位（MATLAB Spectrum Analyzer：SpectrumType／SpectrumUnits／FullScale／ReferenceLoad）---------
SPEC_TYPES = (("mag", "振幅（Magnitude）"), ("power", "功率（Power）"), ("psd", "功率密度（Power Density）"), ("rms", "RMS"))
SPEC_TYPE_KEYS = tuple(k for k, _ in SPEC_TYPES)
SPEC_UNITS = ("dB", "dBFS", "dBm")


def spectrum_units(stype: str, vals, unit: str = "dB", db: bool = True, fullscale: float = 1.0,
                   rload: float = 1.0, cplx: bool = False, per: str = "Hz") -> Tuple[np.ndarray, str]:
    """把頻譜換成要顯示的單位 → (y, y 軸標籤)。vals：mag＝振幅（spectrum() 的輸出），power／rms＝每 bin 功率 P，psd＝密度 D。
    dB（相對）：mag 20·log10(A)、power 10·log10(P)、psd dB/Hz、rms dBV；
    dBFS：0 dBFS ＝ 振幅等於 Full scale 的單音（實數 FS²/2、複數 FS² 的功率）；
    dBm：10·log10(P / R / 1 mW)（R＝Reference load Ω；mag 用 A²/2 換成功率）；
    線性（db=False）：mag 振幅、power W（P/R）、psd W/Hz、rms Vrms（√P）。"""
    v = np.asarray(vals, dtype=float)
    R = float(rload) if rload and rload > 0 else 1.0
    FS = float(fullscale) if fullscale and fullscale > 0 else 1.0
    # dBFS 用對數換算：振幅 20·log10(A) − 20·log10(FS)、功率類 10·log10(P) − 10·log10(滿刻度單音的功率 FS²/2，複數 FS²)，下限照舊（振幅 -240 dB、
    # 功率類 -3000 dB；0 墊到下限）。不先算 P/(FS²/2)：滿刻度很小、資料很大時這個商溢位成 Inf（滿刻度 1e-150 時 P 只要 1e8 就溢位），FS² 在
    # 約 1.34e154 以上也溢位（第七輪以前 FS ** 2 丟 OverflowError、第七輪的乘法是 Inf → 整條墊到下限）。滿刻度欄位的範圍 1e-150～1e150（Auto 照資料
    # 猜，可能更大）之內，任何有限的 float64 頻譜都換得出有限的 dBFS
    lfs = math.log10(FS)
    lpfs = 2.0 * lfs - (0.0 if cplx else math.log10(2.0))
    tiny = 1e-300
    dens = f"/{per}" if stype == "psd" else ""
    if stype == "mag":
        if not db:
            return v, "amplitude"
        if unit == "dBFS":
            with np.errstate(divide="ignore", invalid="ignore"):
                return np.maximum(20.0 * (np.log10(np.maximum(v, 0.0)) - lfs), 20.0 * math.log10(1e-12)), "dBFS"
        if unit == "dBm":
            pw = v ** 2 if cplx else v ** 2 / 2.0
            return 10.0 * np.log10(np.maximum(pw / R / 1e-3, 1e-24)), "dBm"
        return to_db(v), "dB"
    if not db:
        if stype == "rms":
            return np.sqrt(np.maximum(v, 0.0)), "Vrms"
        return v / R, "W" + dens
    if unit == "dBFS":
        with np.errstate(divide="ignore", invalid="ignore"):
            return np.maximum(10.0 * (np.log10(np.maximum(v, 0.0)) - lpfs), 10.0 * math.log10(tiny)), "dBFS" + dens
    if unit == "dBm":
        return 10.0 * np.log10(np.maximum(v / R / 1e-3, tiny)), "dBm" + dens
    return 10.0 * np.log10(np.maximum(v, tiny)), ("dBV" if stype == "rms" else "dB" + dens)


def guess_fullscale(y) -> Tuple[float, str]:
    """Full scale（dBFS 的 0 dB 點）預設值與說明：
    無號整數且中位數在中間（suggest_shift 會建議平移 −2^(b−1) 的 offset binary ADC）→ 2^(b−1)；
    其他整數 → 能裝下 max|y| 的 2^(b−1)（有號 b bit）；小數且 |y| ≤ 1 → 1（正規化浮點）；其他 → max|y|。"""
    v = np.asarray(y, dtype=float)
    v = v[np.isfinite(v)]
    if v.size == 0:
        return 1.0, "1"
    sh = suggest_shift(v)
    if sh is not None:
        half = -float(sh)
        b = int(round(math.log2(half))) + 1
        return half, tr("{b} bit 無號（中心 {half:g}）").format(b=b, half=half)
    peak = float(np.max(np.abs(v)))
    if np.all(v == np.rint(v)):
        b = 1
        while 2.0 ** (b - 1) < peak and b < 64:
            b += 1
        return 2.0 ** (b - 1), tr("{b} bit 有號").format(b=b)
    if peak <= 1.0:
        return 1.0, tr("浮點 ±1")
    return peak, tr("峰值絕對值")


