SETTING_INDEX_MAX = 9999   # 設定檔索引的上限：一個頻譜視窗不會有上萬條訊號，比這大的是手改或損毀的值（1e300 會變成 301 位數的整數）


def setting_index(v) -> int:
    """設定檔裡的索引（cm_channel、mask_channel、頻譜圖的 channel）：0～SETTING_INDEX_MAX 的整數才收；負數、小數、NaN、非數字、list、
    bool、超過上限 → 0（DSV 自己只會存非負整數，其他是手改或損毀的設定檔，不能讓頻譜視窗開不起來，也不能把 1e20 這種值一直顯示、存回去）。"""
    if isinstance(v, bool):
        return 0
    try:
        f = float(v)
    except (TypeError, ValueError, OverflowError):
        return 0
    return int(f) if (math.isfinite(f) and 0 <= f <= SETTING_INDEX_MAX and f == int(f)) else 0


def setting_choice(v, choices, default: str) -> str:
    """設定檔裡的選項鍵：是字串、而且在 choices（(鍵, 名稱)… 或鍵的序列）裡才收；不認得、list、數字… → default。"""
    keys = [c[0] if isinstance(c, (tuple, list)) else c for c in choices]
    return v if isinstance(v, str) and v in keys else default


def blend_rgb(base, color, r: float) -> Tuple[float, float, float]:
    """MATLAB 失真標記的混色：base·(1−r)＋color·r，每個分量在 0～255 上算、捨去小數成整數（不透明色）。
    失真 ▼ 的面＝座標區底色和線色依「線的 alpha／2」混出來的顏色。"""
    a = [int(round(x * 255)) for x in to_rgba(base)[:3]]
    if r <= 0:
        return tuple(x / 255.0 for x in a)
    b = [int(round(x * 255)) for x in to_rgba(color)[:3]]
    if r >= 1:
        return tuple(x / 255.0 for x in b)
    return tuple(int(a[i] * (1.0 - r) + b[i] * r) / 255.0 for i in range(3))


def eng_units(a: float, unit: str = "Hz") -> Tuple[str, float]:
    """分析器的工程單位：a＝|值|，r 從 1e24 起每次除以 1000，第一個 a ≥ r 的字首、乘數 1/r；
    0 或非有限 → (unit, 1)。比 1e-24 還小時 MATLAB 沒有對應的字首，這裡當 (unit, 1)。"""
    if a == 0 or not math.isfinite(a):
        return unit, 1.0
    r = 1e24
    for p in ENG_PREFIXES:
        if a >= r:
            return p + unit, 1.0 / r
        r /= 1e3
    return unit, 1.0


def format_frequency_values(vals) -> Tuple[List[float], str, float]:
    """MATLAB 量測表格的頻率欄：每個值各自取工程字首（NaN 與 0 算 Hz），整組用乘數最小（量級最大）
    那個值的字首。回傳 (乘過的值, 單位, 乘數)。"""
    v = [float(x) for x in vals]
    if not v:
        return [], "Hz", 1.0
    units = ["Hz"] * len(v)
    mults = [1.0] * len(v)
    for i, x in enumerate(v):
        if not math.isnan(x) and x != 0:
            units[i], mults[i] = eng_units(abs(x), "Hz")
    k = 0
    for i, m in enumerate(mults):
        if m < mults[k]:
            k = i
    m = min(mults)
    return [x * m for x in v], units[k], m


def ml_num(v: float) -> str:
    """分析器把數字寫回工具列欄位的寫法：±Inf → Inf／-Inf，其餘＝JavaScript 的 String(v)
    （最短可還原的十進位；1e-6 ≤ |v| < 1e21 用一般寫法，其他像 1.5e+21、1e-7）。"""
    v = float(v)
    if math.isnan(v):
        return "NaN"
    if math.isinf(v):
        return "Inf" if v > 0 else "-Inf"
    if v == 0:
        return "0"
    d = decimal.Decimal(repr(v))                     # repr 和 JavaScript 一樣是最短可還原的位數
    if 1e-6 <= abs(v) < 1e21:
        s = format(d, "f")
        return s.rstrip("0").rstrip(".") if "." in s else s
    t = d.as_tuple()
    digs = "".join(map(str, t.digits))
    e10 = t.exponent + len(digs) - 1
    digs = digs.rstrip("0") or "0"
    mant = digs[0] + ("." + digs[1:] if len(digs) > 1 else "")
    return ("-" if t.sign else "") + mant + "e" + ("+" if e10 >= 0 else "-") + str(abs(e10))


def msg_count(n) -> str:
    """說明裡的點數、段數這種整數：和 MATLAB 訊息裡的數字同一個寫法（ml_num＝JavaScript 的 String）——小於 1e21 寫成整數，再大用科學記號
    （1e+300），不把 300 多位數的整數整串寫出來（視窗長度打 1e300 時「不夠一段視窗（{L} 點）」以前寫出 301 位數）。"""
    try:
        return ml_num(float(n))
    except OverflowError:                            # 比 float 的上限還大的 Python 整數（欄位擋掉了，這裡是保險）
        s = str(int(n))
        return f"{s[0]}{'.' + s[1:7].rstrip('0') if s[1:7].rstrip('0') else ''}e+{len(s) - 1}"


def ml_array(vals) -> str:
    """MATLAB 把向量寫回工具列欄位的寫法：[] 寫 "[]"、一個元素不加括號、兩個以上 "[a b c]"。"""
    v = [ml_num(x) for x in vals]
    if not v:
        return "[]"
    return v[0] if len(v) == 1 else "[" + " ".join(v) + "]"


def js_fixed(v: float, digits: int = 4) -> str:
    """量測表格的數字（MATLAB 量測表格固定 4 位小數）＝JavaScript 的 Number(v).toFixed(4)：
    依 double 的精確值四捨五入、剛好一半時取絕對值大的那個；NaN、±Infinity 照 JavaScript 寫；|v| ≥ 1e21 時改用 String(v)。"""
    v = float(v)
    if math.isnan(v):
        return "NaN"
    if math.isinf(v):
        return "Infinity" if v > 0 else "-Infinity"
    if abs(v) >= 1e21:
        return ml_num(v)
    if v == 0:
        return "0." + "0" * digits if digits else "0"
    q = decimal.Decimal(v).quantize(decimal.Decimal(1).scaleb(-digits), rounding=decimal.ROUND_HALF_UP)
    return format(q, "f")


def ml_cell(v) -> str:
    """量測表格的一格（MATLAB 量測表格的格子）：數字＝toFixed(4)；NaN 與 None 是**空白**——MATLAB 的表格只在值是數字
    （不是 NaN、不是布林、不是 null）時寫字；±Infinity 算數字，寫 Infinity／-Infinity。"""
    if v is None or isinstance(v, bool):
        return ""
    v = float(v)
    return "" if math.isnan(v) else js_fixed(v)


def parse_vector(text) -> Optional[List[float]]:
    """偏移量欄位：[2000 3500]、2000 3500、2000, 3500、2k 3.5k 都可以；空的或有看不懂的 → None。每個數字照頻譜視窗欄位的單一規則
    （parse_spec_number：有限的數，可寫 SI 字首，「12abc」「1..2」是錯）。"""
    t = unicodedata.normalize("NFKC", str(text or "")).strip()
    if t.startswith("[") and t.endswith("]"):
        t = t[1:-1]
    parts = [p for p in re.split(r"[\s,;]+", t) if p]
    if not parts:
        return None
    out = []
    for p in parts:
        v = parse_spec_number(p)
        if v is None:
            return None
        out.append(float(v))
    return out


# ---------------------------------------------------------------------------
# 7. GFSK 分析
# ---------------------------------------------------------------------------
def gaussian_matched_filter(x, bw: float, dt: float, taps: int = 33) -> np.ndarray:
    """Gaussian 係數 g = exp(-(π·sqrt(2/ln2)·bw·t)²)，正規化後 convolve(mode='same')；支援複數。"""
    taps = int(taps)
    if taps < 3:
        taps = 3
    if taps % 2 == 0:
        taps += 1
    t = (np.arange(taps) - (taps - 1) / 2.0) * dt
    alpha = math.pi * math.sqrt(2.0 / math.log(2.0)) * bw
    g = np.exp(-(alpha * t) ** 2)
    g = g / g.sum()
    return np.convolve(np.asarray(x), g, mode="same")


def gfsk_discriminator(i, q, fc_offset: float, fs: float, bw3db: float,
                       iq_order: str = "IQ", taps: int = 33) -> Tuple[np.ndarray, np.ndarray]:
    """I/Q → 下變頻 → 去平均 → Gaussian 濾波 → unwrap 相位 → 一階差分 × fs/2π = 頻率(Hz)。"""
    i = np.asarray(i, dtype=float)
    q = np.asarray(q, dtype=float)
    n = min(len(i), len(q))                       # 長度不同時截成較短的
    i, q = i[:n], q[:n]
    if str(iq_order).upper() == "QI":
        i, q = q, i
    nn = np.arange(n)
    z = (i + 1j * q) * np.exp(-2j * math.pi * fc_offset * nn / fs)
    z = z - z.mean()                              # 扣掉平均值（不做範圍正規化）
    z = gaussian_matched_filter(z, bw3db, 1.0 / fs, taps)
    ph = np.unwrap(np.angle(z))
    f = np.diff(ph) * fs / (2.0 * math.pi)
    t = nn / fs
    return t[1:], f


_I_RE = re.compile(r"(adc[\s_]*i|in[\s_]*i|(?<![a-z0-9])i(?![a-z0-9]))", re.IGNORECASE)
_Q_RE = re.compile(r"(adc[\s_]*q|in[\s_]*[qr]|(?<![a-z0-9])q(?![a-z0-9]))", re.IGNORECASE)


def find_iq_pairs(signals: List[Signal]) -> List[Tuple[Signal, Signal]]:
    """I/Q 自動配對：同 panel 內用正則比對 → 看前兩條的名稱 → 剛好 2 條就直接配。"""
    pairs: List[Tuple[Signal, Signal]] = []
    groups: Dict[int, List[Signal]] = {}
    for s in signals:
        groups.setdefault(s.panel, []).append(s)
    for grp in groups.values():
        iis = [s for s in grp if _I_RE.search(s.name) and not _Q_RE.search(s.name)]
        qs = [s for s in grp if _Q_RE.search(s.name) and not _I_RE.search(s.name)]
        if iis and qs:
            pairs.append((iis[0], qs[0]))
    if not pairs and len(signals) >= 2:
        a, b = signals[0], signals[1]
        if _I_RE.search(a.name) and _Q_RE.search(b.name):
            pairs.append((a, b))
        elif _Q_RE.search(a.name) and _I_RE.search(b.name):
            pairs.append((b, a))
    if not pairs and len(signals) == 2:
        pairs.append((signals[0], signals[1]))
    return pairs


def suggest_shift(vals) -> Optional[float]:
    """值域落在 [0, 2^b) 且中位數接近 2^(b-1)（20% 以內）→ 建議平移 -2^(b-1)。"""
    v = np.asarray(vals, dtype=float)
    v = v[np.isfinite(v)]
    if v.size == 0 or v.min() < 0:
        return None
    hi = float(v.max())
    med = float(np.median(v))
    for b in range(2, 40):
        full = 2.0 ** b
        if hi < full:
            half = full / 2.0
            return -half if abs(med - half) <= 0.2 * half else None
    return None


# ---------------------------------------------------------------------------
# 7b. 星座圖（comm.ConstellationDiagram／scatterplot）：每 SPS 取一點
# ---------------------------------------------------------------------------
MAX_CONST_POINTS = 100_000       # 星座圖一次最多畫幾個點（超過只畫最後這麼多個，狀態列說明）
CONST_REFS = (("none", "無"), ("bpsk", "BPSK"), ("qpsk", "QPSK"), ("8psk", "8-PSK"), ("16qam", "16-QAM"))
CONST_REF_KEYS = tuple(k for k, _ in CONST_REFS)


def constellation_indices(n: int, sps: float, offset: float = 0.0, i0: int = 0, i1: Optional[int] = None,
                          last: Optional[int] = None, first: Optional[int] = None) -> np.ndarray:
    """符號取樣點的樣本索引：round(offset + k·sps)（k 整數，offset／sps 以樣本計、可以是小數），
    只留 [i0, i1) 之內的；last＝只留最後幾個（MATLAB SymbolsToDisplay）、first＝只留最前面幾個（兩個都給時 last 優先）。sps ≤ 0 時當 1。"""
    sps = float(sps) if sps and sps > 0 else 1.0
    i1 = n if i1 is None else min(int(i1), n)
    i0 = max(0, int(i0))
    if i1 <= i0:
        return np.zeros(0, dtype=np.int64)
    k0 = int(math.ceil((i0 - 0.5 - offset) / sps))
    k1 = int(math.floor((i1 - 0.5 - offset) / sps))
    idx = np.rint(offset + np.arange(k0, k1 + 1) * sps).astype(np.int64)
    idx = idx[(idx >= i0) & (idx < i1)]
    if last is not None and last > 0:
        idx = idx[-int(last):]
    elif first is not None and first > 0:
        idx = idx[:int(first)]
    return idx


def reference_constellation(name: str) -> np.ndarray:
    """參考星座點（平均功率 1）：BPSK ±1、QPSK (±1±j)/√2、8-PSK 單位圓 8 點、16-QAM {±1,±3}²/√10。"""
    if name == "bpsk":
        return np.array([-1.0 + 0j, 1.0 + 0j])
    if name == "qpsk":
        return np.array([1 + 1j, -1 + 1j, -1 - 1j, 1 - 1j]) / math.sqrt(2.0)
    if name == "8psk":
        return np.exp(2j * np.pi * np.arange(8) / 8)
    if name == "16qam":
        lv = np.array([-3.0, -1.0, 1.0, 3.0])
        return (lv[:, None] + 1j * lv[None, :]).ravel() / math.sqrt(10.0)
    return np.zeros(0, dtype=complex)


def evm_rms(z, ref) -> Tuple[float, np.ndarray]:
    """參考星座縮放到 z 的 RMS（自動增益），每個點對最近的參考點算誤差：
    回傳 (RMS EVM %，縮放後的參考點)；EVM = √(mean|e|²) / √(mean|ref|²) × 100（comm.EVM 的 average reference power 正規化）。"""
    z = np.asarray(z, dtype=complex)
    z = z[np.isfinite(z)]                              # NaN／inf 的符號點不算（comm.EVM 不會因為一個 NaN 整個變 NaN）
    ref = np.asarray(ref, dtype=complex)
    if z.size == 0 or ref.size == 0:
        return float("nan"), ref
    rz = math.sqrt(float(np.mean(np.abs(z) ** 2))) or 1.0
    rr = math.sqrt(float(np.mean(np.abs(ref) ** 2))) or 1.0
    ref_s = ref * (rz / rr)
    k = np.argmin(np.abs(z[:, None] - ref_s[None, :]), axis=1)
    e = z - ref_s[k]
    return 100.0 * math.sqrt(float(np.mean(np.abs(e) ** 2))) / math.sqrt(float(np.mean(np.abs(ref_s[k]) ** 2)) or 1.0), ref_s


CONST_SYNC_MAX_OFFSETS = 64       # 時序修正最多試幾個取樣相位（SPS 更大時等間隔取 64 個）
CONST_SYNC_SEARCH_POINTS = 2048  # 試算 EVM 時每個候選最多用幾個符號點（等間隔抽樣；最後結果用全部的點）


def evm_phase_fit(z, ref, iters: int = 6) -> Tuple[float, float]:
    """載波相位修正：找讓 EVM 最小的旋轉角 φ（z·e^(−jφ) 對參考星座）。先每 5° 粗掃（抽樣的點），再用判決導向的
    最小平方相位反覆修正：φ = ∠Σ z·conj(d)（d＝旋轉後最近的參考點、縮放到 z 的 RMS）。回傳 (RMS EVM %，φ 弧度)。
    對稱星座（QPSK 等）的 90° 模糊不影響 EVM。"""
    z = np.asarray(z, dtype=complex)
    ref = np.asarray(ref, dtype=complex)
    if z.size == 0 or ref.size == 0:
        return float("nan"), 0.0
    sub = z[:: max(1, z.size // CONST_SYNC_SEARCH_POINTS)]
    grid = np.radians(np.arange(0.0, 360.0, 5.0))
    phi = float(min(grid, key=lambda a: evm_rms(sub * np.exp(-1j * a), ref)[0]))
    phi0 = phi
    rz = math.sqrt(float(np.mean(np.abs(z) ** 2))) or 1.0
    rr = math.sqrt(float(np.mean(np.abs(ref) ** 2))) or 1.0
    ref_s = ref * (rz / rr)
    for _ in range(max(1, iters)):
        zr = z * np.exp(-1j * phi)
        d = ref_s[np.argmin(np.abs(zr[:, None] - ref_s[None, :]), axis=1)]
        c = complex(np.sum(z * np.conj(d)))
        if c == 0:
            break
        new = math.atan2(c.imag, c.real)
        if abs(new - phi) < 1e-12:
            break
        phi = new
    e, e0 = evm_rms(z * np.exp(-1j * phi), ref)[0], evm_rms(z * np.exp(-1j * phi0), ref)[0]
    return (e, phi) if not (e0 < e) else (e0, phi0)      # 判決導向收斂到別處（雜訊很大時）：保留粗掃的結果，EVM 不會比 0° 差


def symbol_timing_search(zf, n: int, sps: float, i0: int, i1: Optional[int], last: Optional[int], ref,
                         phase: bool = True, first: Optional[int] = None) -> Tuple[float, float]:
    """符號時序修正：0 ≤ offset < SPS 的每個取樣相位（最多 CONST_SYNC_MAX_OFFSETS 個）都取符號點試算 EVM（phase＝先做相位修正），
    挑 EVM 最小的。zf＝整段 I+jQ（複數）。last／first＝只用最後／最前面幾個符號（和畫出來的一樣）。
    回傳 (最佳 offset（樣本）, 該 offset 的 EVM %)；沒有任何符號點 → (0, nan)。"""
    sps = float(sps) if sps and sps > 0 else 1.0
    nc = int(math.ceil(sps - 1e-9))
    offs = np.arange(nc, dtype=float) if nc <= CONST_SYNC_MAX_OFFSETS else np.linspace(0.0, sps, CONST_SYNC_MAX_OFFSETS, endpoint=False)
    best = (0.0, float("nan"))
    for o in offs:
        idx = constellation_indices(n, sps, float(o), i0, i1, last, first)
        if len(idx) == 0:
            continue
        zz = np.asarray(zf)[idx]
        zz = zz[:: max(1, zz.size // CONST_SYNC_SEARCH_POINTS)]
        e = evm_phase_fit(zz, ref)[0] if phase else evm_rms(zz, ref)[0]
        if math.isfinite(e) and not (e >= best[1]):
            best = (float(o), e)
    return best


# ---------------------------------------------------------------------------
# GUI 小工具
# ---------------------------------------------------------------------------
def safe_filename(s: str, limit: int = 80) -> str:
    s = re.sub(r'[\\/:*?"<>|;\x00-\x1f]+', "_", str(s)).strip(" ._")
    return (s or "signal")[:limit]


def open_in_explorer(folder: str) -> None:
    """用系統檔案總管開啟資料夾（Windows 用 os.startfile）。"""
    try:
        if hasattr(os, "startfile"):
            os.startfile(folder)  # type: ignore[attr-defined]
        elif sys.platform == "darwin":
            subprocess.Popen(["open", folder])
        else:
            subprocess.Popen(["xdg-open", folder])
    except Exception as e:
        log(f"開啟資料夾失敗: {e}")


fmt_num = pk.draw.fmt_num          # NaN／inf 安全（plotkit 的版本）

def ask_string(parent, title: str, prompt: str, initial: str = "") -> Optional[str]:
    return simpledialog.askstring(title, prompt, initialvalue=initial, parent=parent)


# ---------------------------------------------------------------------------
# 8. CSV 匯入對話框（modal）
# ---------------------------------------------------------------------------
class CsvImportDialog(tk.Toplevel):
    """選欄位 → 數值與取樣率 → 突波抑制參數 → 其他選項 → 加入。"""

    COLS = ("add", "name", "ss", "ds", "min", "max", "median", "suggest")
    HEADS = ("加入", "欄位名", "套用平移/縮放", "突波抑制", "最小", "最大", "中位數", "建議平移")
    TOGGLE = ("add", "ss", "ds")

    def __init__(self, app, path: str, table: CsvTable, preselect: Optional[List[str]] = None):
        super().__init__(app)
        self.app = app
        self.path = path
        self.table = table
        self.result: Optional[List[str]] = None
        self.title(tr("匯入 CSV：{name}").format(name=os.path.basename(path)))
        self.transient(app)
        d = app.csv_defaults
        self.v_shift = tk.StringVar(value=str(d.get("shift", "0")))
        self.v_scale = tk.StringVar(value=str(d.get("scale", "1")))
        est = table.estimate_rate()               # 有時間欄就預填它的估計值：沿用上一個檔案的 fs 會把不同取樣率的檔案算錯 SPS
        self.v_fs = tk.StringVar(value=fmt_si(est) if est else str(d.get("fs", "")))
        self.v_fmt = tk.StringVar(value=str(d.get("fmt", "AUTO")))
        self.v_dk = tk.StringVar(value=str(d.get("dk", 2)))
        self.v_dthr = tk.StringVar(value=str(d.get("dthr", 8.0)))
        self.v_dmin = tk.StringVar(value=str(d.get("dmin", 20.0)))
        self.v_merge = tk.BooleanVar(value=bool(d.get("merge", True)))
        self.v_toff = tk.BooleanVar(value=bool(d.get("time_offset", False)))
        self.v_sps_info = tk.StringVar(value="")
        self.rows: Dict[str, dict] = {}
        self._build(preselect or [])
        self.v_fs.trace_add("write", lambda *a: self._update_sps_info())
        self._update_sps_info()
        self.grab_set()
        self.focus_set()

    # --- 介面 ---------------------------------------------------------------
    def _build(self, preselect: List[str]) -> None:
        pad = {"padx": 4, "pady": 2}
        f1 = ttk.LabelFrame(self, text=tr("1. 選欄位"))
        f1.pack(fill="both", expand=True, padx=6, pady=4)
        self.tree = ttk.Treeview(f1, columns=self.COLS, show="headings", height=8, selectmode="browse")
        widths = (44, 180, 110, 80, 80, 80, 80, 80)
        th = T.current()
        hfont = th.font("bold") if th else None
        for c, h, w in zip(self.COLS, self.HEADS, widths):
            self.tree.heading(c, text=tr(h))
            if hfont is not None:
                w = heading_width(hfont, tr(h), w)
            self.tree.column(c, width=w, anchor="center" if c != "name" else "w", stretch=(c == "name"))
        sb = ttk.Scrollbar(f1, orient="vertical", command=self.tree.yview)
        self.tree.configure(yscrollcommand=sb.set)
        sb.pack(side="right", fill="y")
        self.tree.pack(fill="both", expand=True)
        self.tree.bind("<Button-1>", self._on_click)
        fmt = self.v_fmt.get()
        for name in self.table.data_columns():
            try:
                vals = self.table.values(name, fmt)
                fin = vals[np.isfinite(vals)]
                analog = len(np.unique(fin)) > 2
                st = {"min": float(fin.min()) if fin.size else None,
                      "max": float(fin.max()) if fin.size else None,
                      "median": float(np.median(fin)) if fin.size else None,
                      "suggest": suggest_shift(fin)}
            except Exception as e:           # 欄位讀不了也要能顯示
                log(f"CSV 欄位 {name} 統計失敗: {e}")
                analog = False
                st = {"min": None, "max": None, "median": None, "suggest": None}
            row = {"add": (not preselect) or (name in preselect), "ss": analog, "ds": analog, **st}
            self.rows[name] = row
            self.tree.insert("", "end", iid=name, values=self._row_values(name))
        ttk.Label(f1, text=tr("不同值超過 2 種的欄位視為類比欄位，預設勾選平移/縮放與突波抑制。點格子可切換。"),
                  style="Hint.TLabel").pack(anchor="w", padx=4)

        f2 = ttk.LabelFrame(self, text=tr("2. 數值與取樣率"))
        f2.pack(fill="x", padx=6, pady=4)
        r = ttk.Frame(f2)
        r.pack(fill="x", **pad)
        ttk.Label(r, text="shift").pack(side="left")
        ttk.Entry(r, textvariable=self.v_shift, width=10).pack(side="left", padx=2)
        ttk.Label(r, text="scale").pack(side="left")
        ttk.Entry(r, textvariable=self.v_scale, width=10).pack(side="left", padx=2)
        ttk.Button(r, text=tr("用建議值"), command=self._use_suggest).pack(side="left", padx=4)
        ttk.Label(r, text=tr("顯示值 = (原始值 + shift) × scale"), style="Hint.TLabel").pack(side="left", padx=6)
        r = ttk.Frame(f2)
        r.pack(fill="x", **pad)
        ttk.Label(r, text="Sample rate").pack(side="left")
        ttk.Entry(r, textvariable=self.v_fs, width=12).pack(side="left", padx=2)
        ttk.Button(r, text=tr("用估計值"), command=self._use_estimate).pack(side="left", padx=4)
        ttk.Label(r, textvariable=self.v_sps_info).pack(side="left", padx=6)
        r = ttk.Frame(f2)
        r.pack(fill="x", **pad)
        ttk.Label(r, text=tr("讀取格式")).pack(side="left")
        ttk.Combobox(r, textvariable=self.v_fmt, values=FORMATS, width=7, state="readonly").pack(side="left", padx=2)

        f3 = ttk.LabelFrame(self, text=tr("3. 突波抑制參數"))
        f3.pack(fill="x", padx=6, pady=4)
        r = ttk.Frame(f3)
        r.pack(fill="x", **pad)
        ttk.Label(r, text=tr("最長連續突波 k")).pack(side="left")
        ttk.Combobox(r, textvariable=self.v_dk, values=("1", "2", "3"), width=3, state="readonly").pack(side="left", padx=2)
        ttk.Label(r, text=tr("門檻 × 雜訊")).pack(side="left", padx=(8, 0))
        ttk.Entry(r, textvariable=self.v_dthr, width=6).pack(side="left", padx=2)
        ttk.Label(r, text=tr("最小偏差")).pack(side="left", padx=(8, 0))
        ttk.Entry(r, textvariable=self.v_dmin, width=6).pack(side="left", padx=2)

        f4 = ttk.LabelFrame(self, text=tr("4. 其他選項"))
        f4.pack(fill="x", padx=6, pady=4)
        ttk.Checkbutton(f4, text=tr("勾選的欄位合併畫在同一張圖"), variable=self.v_merge).pack(anchor="w", **pad)
        ttk.Checkbutton(f4, text=tr("用 Time 欄的起始時間當 offset"), variable=self.v_toff).pack(anchor="w", **pad)

        b = ttk.Frame(self)
        b.pack(fill="x", padx=6, pady=6)
        ttk.Button(b, text=tr("加入"), command=self._on_add).pack(side="right", padx=4)
        ttk.Button(b, text=tr("取消"), command=self.destroy).pack(side="right")
        self.bind("<Escape>", lambda e: self.destroy())

    def _row_values(self, name: str) -> tuple:
        r = self.rows[name]
        mark = lambda b: "☑" if b else "☐"  # noqa: E731
        return (mark(r["add"]), name, mark(r["ss"]), mark(r["ds"]), fmt_num(r["min"]),
                fmt_num(r["max"]), fmt_num(r["median"]), fmt_num(r["suggest"]))

    def _on_click(self, event):
        if self.tree.identify("region", event.x, event.y) != "cell":
            return
        col = self.tree.identify_column(event.x)
        row = self.tree.identify_row(event.y)
        if not row or not col:
            return
        cname = self.COLS[int(col[1:]) - 1]
        if cname in self.TOGGLE:
            self.rows[row][cname] = not self.rows[row][cname]
            self.tree.item(row, values=self._row_values(row))
            return "break"

    def _use_suggest(self):
        for name, r in self.rows.items():
            if r["add"] and r["suggest"] is not None:
                self.v_shift.set(fmt_num(r["suggest"]))
                self.v_scale.set("1")
                r["ss"] = True
                self.tree.item(name, values=self._row_values(name))
                return
        messagebox.showinfo(tr("建議平移"), tr("勾選的欄位沒有可用的建議值。"), parent=self)

    def _use_estimate(self):
        fs = self.table.estimate_rate()
        if fs:
            self.v_fs.set(fmt_si(fs))
        else:
            messagebox.showinfo(tr("取樣率"), tr("沒有時間欄或無法估計取樣率。"), parent=self)

    def _update_sps_info(self):
        fs = parse_si(self.v_fs.get())
        sr = self.app.symbol_rate()
        est = self.table.estimate_rate()
        hint = tr("（時間欄估計 {est}）").format(est=fmt_si(est, 'Hz')) if est else ""
        if fs and fs > 0:
            self.v_sps_info.set(f"→ SPS = fs / symbol rate = {fs / sr:.6g}  {hint}")
        else:
            self.v_sps_info.set(tr("→ 空白則用預設 SPS {sps:g}  {hint}").format(sps=self.app.default_sps(), hint=hint))

    # --- 加入 ---------------------------------------------------------------
    def _on_add(self):
        selected = [n for n, r in self.rows.items() if r["add"]]
        if not selected:
            messagebox.showwarning(tr("匯入 CSV"), tr("請至少勾選一個欄位。"), parent=self)
            return
        shift = parse_number(self.v_shift.get())
        scale = parse_number(self.v_scale.get())
        if shift is None or scale is None or scale == 0:
            messagebox.showwarning(tr("匯入 CSV"), tr("shift / scale 必須是數字，scale 不可為 0。"), parent=self)
            return
        fs_text = self.v_fs.get().strip()
        fs = parse_si(fs_text) if fs_text else None
        if fs_text and (fs is None or fs <= 0):
            messagebox.showwarning(tr("匯入 CSV"), tr("Sample rate 無法解析：{text}").format(text=fs_text), parent=self)
            return
        dthr = parse_number(self.v_dthr.get())
        dmin = parse_number(self.v_dmin.get())
        if dthr is None or dmin is None:
            messagebox.showwarning(tr("匯入 CSV"), tr("突波抑制參數必須是數字。"), parent=self)
            return
        dk = int(parse_number(self.v_dk.get()) or 2)
        sr = self.app.symbol_rate()
        sps = fs / sr if fs else self.app.default_sps()
        if sps <= 0:
            messagebox.showwarning(tr("匯入 CSV"), tr("SPS 必須 > 0。"), parent=self)
            return
        fmt = self.v_fmt.get() or "AUTO"
        merge = self.v_merge.get()
        t0 = self.table.start_time() if self.v_toff.get() else None
        app = self.app
        app._push_undo(tr("匯入 CSV"))
        existing = [app.find_signal(signal_key_for(app.root_dir, self.path, n)) for n in selected]
        base = next((s.panel for s in existing if s is not None), None) if merge else None
        if base is None:
            base = app.next_panel()
        for j, name in enumerate(selected):
            row = self.rows[name]
            key = signal_key_for(app.root_dir, self.path, name)
            sig = app.find_signal(key)
            new = sig is None
            if new:
                sig = Signal(key=key, path=self.path, column=name, uid=app.new_uid(), fresh_add=True)   # 新加的欄位：讀不了就照舊不加
                sig.label = sig.default_label()
            sig.sps = sps
            sig.fmt = fmt
            sig.vshift = shift if row["ss"] else 0.0
            sig.vscale = scale if row["ss"] else 1.0
            sig.despike = bool(row["ds"])
            sig.dk, sig.dthr, sig.dmin = dk, float(dthr), float(dmin)
            sig.panel = base if merge else (base + j if new else sig.panel)
            if t0 is not None:
                off_sym = t0 * sr
                sig.offset = off_sym * sps if SETTINGS.get("offset_unit") == "sample" else off_sym
            sig.invalidate(reload=True)
            if new:
                app.signals.append(sig)
            record_action((tr("加入 CSV 欄位 {key}") if new else tr("更新 CSV 欄位 {key}")).format(key=key))
        app.csv_defaults.update({"shift": self.v_shift.get(), "scale": self.v_scale.get(),
                                 "fs": fs_text, "fmt": fmt, "dk": dk, "dthr": float(dthr),
                                 "dmin": float(dmin), "merge": merge,
                                 "time_offset": self.v_toff.get()})
        self.result = selected
        empty = []                                         # 整欄沒有數值（文字欄）＝NaN，不畫線：狀態列說明
        for sig in app.signals:
            if sig.path == self.path and sig.column in selected:
                try:
                    d = sig.get_data()
                    if len(d) and not np.isfinite(d).any():
                        empty.append(sig.name)
                except Exception:
                    pass
        if empty:
            note = tr("；").join(tr("{name}：整欄沒有數值（當成 NaN，不畫線）").format(name=n) for n in empty)
            app.after(400, lambda: app.status_var.set(note))
        self.destroy()


# ---------------------------------------------------------------------------
# 頻譜／GFSK 視窗共用的圖上互動（和主畫面同一套 plotkit.Interactor）
# ---------------------------------------------------------------------------
# 分析視窗（頻譜、GFSK、AM/PM/FM、星座圖、眼圖）的線色——1.0.0 第 1 輪 B2（決定檔 decisions_skins.md「主 session 照建議，11-01 21:1x」）：
# 六個外觀主題（Sony 風、Apple 風）的繪圖風格用該風格自己的線色（第 1 條＝主題刻意選的強調色，不是 matplotlib 的藍）；
# matplotlib 預設與 MATLAB 兩個風格（深色／淺色主題）照舊用 matplotlib 的色序（0.9.14 起就是這樣；眼圖對照 eyediagram 的預設藍）。
ANALYSIS_MPL_CYCLE_STYLES = ("default", "matlab", "matlab-dark")


def analysis_colors(style) -> Optional[List[str]]:
    """分析視窗要用的線色（風格名或風格 dict）；None＝照舊用 matplotlib 的色序（rcParams）。"""
    name = str(style.get("name", "default")) if isinstance(style, dict) else style
    if not isinstance(name, str) or name in ANALYSIS_MPL_CYCLE_STYLES or name not in pk.STYLES:
        return None
    cols = [c for c in (pk.STYLES[name].get("colors") or []) if isinstance(c, str)]
    return cols or None


def _analysis_line_colors(fn):
    """包住分析視窗的重畫（建 axes、畫線）：外觀主題時把 matplotlib 的色序暫時換成該主題繪圖風格的線色（只在這次呼叫裡，不改全域設定）。"""
    import functools

    @functools.wraps(fn)
    def wrapper(self, *a, **k):
        try:
            cols = analysis_colors(self.app.v["style"].get())
        except Exception:
            cols = None
        if not cols:
            return fn(self, *a, **k)
        with matplotlib.rc_context({"axes.prop_cycle": matplotlib.cycler(color=cols)}):
            return fn(self, *a, **k)
    return wrapper


class AnalysisHost(pk.InteractorHost):
    """頻譜／GFSK 視窗：滾輪縮放、左鍵拖曳平移、雙擊空白／Home 還原、資料提示、右鍵選單。

    線是每次 compute() 重畫的（標籤是算出來的，不給改名、不進 undo）；重新計算時資料提示一起清掉。"""

    def __init__(self, win):
        self.win = win

    def style(self) -> dict:
        name = self.win.app.v["style"].get()
        return pk.get_style(name if name in pk.STYLES else "default")

    def lines_in(self, ax):
        return [(uid, ln) for uid, ln in self.win.lines.items() if ln.axes is ax]

    def series_data(self, uid):
        ln = self.win.lines.get(uid)
        if ln is None or ln.axes is None:
            return None
        return (np.asarray(ln.get_xdata(), dtype=float), np.asarray(ln.get_ydata(), dtype=float),
                ln.get_label(), ln.axes)

    def legend_entries(self, ax):
        return [uid for uid, ln in self.win.lines.items() if ln.axes is ax]

    def tip_text(self, uid, index, x, y) -> str:
        ln = self.win.lines.get(uid)
        return pk.format_tip_text(ln.get_label() if ln is not None else str(uid), x, y, self.win.tip_xunit)

    def on_context(self, hit, event) -> None:
        self.win.context_menu(hit, event)

    def begin_inline_edit(self, bbox, text, on_commit) -> bool:
        self.win._inline_editor = pk.widgets.InlineEditor(self.win.canvas, bbox, text, on_commit)
        return True

    def on_rename(self, uid, label) -> None:
        self.win.rename_line(uid, label)

    def on_legend_move(self, ax, loc) -> None:
        self.win.legend_loc = tuple(loc)
        self.win.relegend(ax)

    def on_legend_loc(self, ax, loc) -> None:
        self.win.legend_loc = loc
        self.win.relegend(ax)

    def on_legend_delete(self, ax) -> None:
        leg = ax.get_legend()
        if leg is not None:
            leg.remove()
            self.win.canvas.draw_idle()

    def status(self, msg) -> None:
        self.win.v_status.set(msg)

    def before_view_change(self, tag) -> None:
        self.win._view_undo.push(self.win._view_state(), tr("縮放／平移"), tag)


class AnalysisInteractMixin:
    """SpectrumWindow／GfskWindow 用：建 Interactor、資料提示按鈕、右鍵選單、重畫前後的整理。"""

    def _init_interact(self) -> None:
        self.lines: Dict[int, Any] = {}
        self.tip_xunit = ""
        self.legend_loc: Any = "upper right"        # 圖例拖曳／右鍵選的位置；重算頻譜時沿用
        self.v_tips = tk.BooleanVar(value=True)     # 跟主畫面一樣：點線條就釘資料提示
        self._tips_resume = False
        self.plot_toolbar.add_toggle("tips", "datatip", tr("資料提示模式：點線條釘住資料提示"), self.v_tips, self._on_tips_toggle,
                                     before="pan")                 # MATLAB 的 Data tips 按鈕在 Pan 前面
        self.plot_toolbar.on_mode = self._on_nav_mode
        self.v_status = tk.StringVar(value="")
        T.status_bar(self, self.v_status).pack(side="bottom", fill="x")   # 狀態訊息（座標欄是固定寬度，英文訊息放不下）
        self.ia = pk.Interactor(self.canvas, AnalysisHost(self), toolbar=self.toolbar, wheel_axis="both")
        self.ia.tips_enabled = bool(self.v_tips.get())
        self.plot_toolbar.home_command = self.ia.restore_view
        self.ia.wheel_enabled = bool(self.app.v["wheel_zoom"].get())      # 跟主畫面「滾輪縮放」開關一致
        for seq in self.app._shortcut_seqs("w"):                            # MATLAB 圖形視窗 File > Close 的快速鍵 Ctrl+W
            self.bind(seq, lambda e: (self.destroy(), "break")[1])
        # MATLAB 圖形視窗 Edit > Undo／Redo（Ctrl+Z／Ctrl+Y；macOS ⌘Z／⌘Y）：這裡的線是算出來的，只有視圖可以復原
        self._view_undo = pk.undo.UndoStack(100)

        def wrap(fn):
            def handler(e):
                try:
                    if e.widget.winfo_class() in ("Entry", "TEntry", "Text", "TCombobox", "Spinbox", "TSpinbox"):
                        return None             # 輸入框有焦點時放行
                except Exception:
                    pass
                fn()
                return "break"
            return handler
        for mod in (["Control"] + (["Command"] if IS_MAC else [])):
            for seq, fn in ((f"<{mod}-z>", self._undo_view), (f"<{mod}-Z>", self._undo_view),
                            (f"<{mod}-y>", self._redo_view), (f"<{mod}-Shift-Z>", self._redo_view)):
                self.bind(seq, wrap(fn))
        self.bind("<<Undo>>", wrap(self._undo_view), add="+")
        self.bind("<<Redo>>", wrap(self._redo_view), add="+")
        self.bind("<Key>", lambda e: self._on_key_fallback(e), add="+")

    def _on_key_fallback(self, e):
        """注音等非拉丁輸入法之下 ⌘W／⌘Z／⌘Y 的 keysym 是 "??"，上面的 <Command-w> 這些都對不到：照實體按鍵認，做同一件事
        （2026-10-27 第二次選單「全部都修」；ABC 之下 <Command-w> 比 <Key> 精確，Tk 只會執行那一個，不會做兩次）。
        IqWindow 另外接 ⌘C／⌘V（第 13 項）。"""
        k = pk.keys.command_key(e)
        if k == "w":                                  # ⌘W 不管焦點在哪都關（和 <Command-w> 一樣）
            self.destroy()
            return "break"
        fn = {"z": self._undo_view, "y": self._redo_view, "Z": self._redo_view}.get(k or "")
        if fn is None:
            return None
        try:
            if e.widget.winfo_class() in ("Entry", "TEntry", "Text", "TCombobox", "Spinbox", "TSpinbox"):
                return None                           # 輸入框有焦點時放行（和 <Command-z> 一樣）
        except Exception:
            pass
        fn()
        return "break"

    def _view_state(self) -> list:
        return [(tuple(ax.get_xlim()), tuple(ax.get_ylim())) for ax in self.fig.axes]

    def _apply_view_state(self, views) -> bool:
        axes = self.fig.axes
        if not views or len(views) != len(axes):
            return False
        for ax, (xl, yl) in zip(axes, views):
            ax.set_xlim(*xl)
            ax.set_ylim(*yl)
        self.ia._push_toolbar()                  # 上一個／下一個視圖跟著記
        self.canvas.draw_idle()
        return True

    def _undo_view(self) -> None:
        desc = self._view_undo.peek_desc()
        views = self._view_undo.undo(self._view_state())
        if views is None or not self._apply_view_state(views):
            self.v_status.set(tr("沒有可復原的動作"))
            return
        self.v_status.set(tr("已復原：{desc}").format(desc=desc))

    def _redo_view(self) -> None:
        desc = self._view_undo.peek_redo_desc()
        views = self._view_undo.redo(self._view_state())
        if views is None or not self._apply_view_state(views):
            self.v_status.set(tr("沒有可重做的動作"))
            return
        self.v_status.set(tr("已重做：{desc}").format(desc=desc))

    def _on_nav_mode(self, mode: str) -> None:
        """工具列的平移／框選放大開著時資料提示暫停，關掉後恢復。"""
        if mode:
            resume = bool(self.v_tips.get()) or self._tips_resume
            if self.v_tips.get():
                self.v_tips.set(False)
                self._on_tips_toggle()
            self._tips_resume = resume
        elif self._tips_resume:
            self.v_tips.set(True)
            self._on_tips_toggle()

    def _on_tips_toggle(self) -> None:
        self._tips_resume = False
        self.ia.tips_enabled = bool(self.v_tips.get())
        if self.ia.tips_enabled:
            self.plot_toolbar.clear_mode()                 # 和平移／框選放大互斥

    def _fit_width(self, top, w0: int = 960, h0: int = 640) -> None:
        """選項列需要的寬度超過預設 960（英文字比較長）時把視窗加寬，最多到螢幕寬的 95%。
        Windows 高 DPI（W10，T.NARROW_LAYOUT）：預設寬高照 DPI 放大、最多到工作區的 95%；加寬了還放不下的選項列換行（T.flow_row）。"""
        try:
            self.update_idletasks()
            need = top.winfo_reqwidth() + 12
            if T.NARROW_LAYOUT:
                ww, hh = T.window_size(self, w0, h0)
                if need > ww:
                    l_, _t, r_, _b = T.work_area(self)
                    self.geometry(f"{min(need, int((r_ - l_) * 0.95))}x{hh}")
                T.flow_row(top)
                return
            if need > w0:
                self.geometry(f"{min(need, int(self.winfo_screenwidth() * 0.95))}x{h0}")
        except Exception:
            pass

    def _begin_redraw(self) -> None:
        """fig.clear() 之前：舊的線與提示都會不見。只有換主題（資料沒變）時把提示留下來，畫完再放回同一個點。"""
        self.ia.forget_home()              # 重新計算＝新的圖，原始視圖重記
        self._view_undo = pk.undo.UndoStack(100)    # 新的圖：舊視圖的 undo 不適用
        self.ia.reset()
        kept = list(self.ia.model.tips) if getattr(self, "_keep_tips_once", False) else []
        self._keep_tips_once = False
        self.ia.model.tips.clear()
        self.ia.selected_tip = None
        self.lines = {}
        if kept:                                       # 記下工作的 id：關視窗時要取消（AnalysisInteractMixin.destroy）
            self._tips_job = self.after_idle(lambda: self._restore_tips(kept))

    @staticmethod
    def _cancel_after_jobs(pairs) -> None:
        """取消排著的 after 工作：pairs＝((擁有者元件, 存工作 id 的屬性名), …)；取消後屬性設成 None（擁有者是 None 或沒排就跳過）。"""
        for owner, attr in pairs:
            job = getattr(owner, attr, None) if owner is not None else None
            if job is not None:
                try:
                    owner.after_cancel(job)
                except Exception:
                    pass
                setattr(owner, attr, None)

    def destroy(self) -> None:
        """關視窗（關閉鈕、Ctrl+W、程式；頻譜、GFSK、AM/PM/FM、星座圖視窗都是）：先取消這個視窗排著的 after 工作——換主題後放回資料提示
        （_tips_job）——和 matplotlib 畫布排著的閒置重畫（照 FigureManagerTk.destroy 取消 canvas._idle_draw_id／_event_loop_id）。不取消的話，
        Tk 還沒閒下來就關窗（例如換主題或縮放後馬上按 ⌘W），時間到時找不到已刪掉的 Tcl 指令，會跳 Tk 的背景錯誤對話框（invalid command name
        "…<lambda>"／"…idle_draw"）。暫時資料提示的 200 ms 計時器由 plotkit Interactor 在畫布的 close_event 停掉、工具列元件的提示（plotkit
        Tooltip 的 600 ms 延遲）由 Tooltip 自己在元件的 <Destroy> 取消；頻譜視窗另外有自己的工作（SpectrumWindow.destroy）。"""
        self._cancel_after_jobs(((self, "_tips_job"),))
        canvas = getattr(self, "canvas", None)
        tkc = getattr(canvas, "_tkcanvas", None)
        for attr in ("_idle_draw_id", "_event_loop_id"):
            job = getattr(canvas, attr, None) if tkc is not None else None
            if job:
                try:
                    tkc.after_cancel(job)
                except Exception:
                    pass
                setattr(canvas, attr, None)
        super().destroy()

    def _restore_tips(self, kept) -> None:
        self._tips_job = None
        if not self.winfo_exists() or not self.lines:
            return
        ok = [t for t in kept
              if self.lines.get(t.uid) is not None and 0 <= t.index < len(self.lines[t.uid].get_ydata())]
        if ok:
            self.ia.model.tips[:] = ok
            self.ia.rebuild()
            self.canvas.draw_idle()

    def _track(self, ln) -> None:
        pk.lod.enable(ln)                            # 頻譜／GFSK 的長線條（nseg=1 時上百萬點）畫面也只畫 M4 子集
        self.lines[len(self.lines) + 1] = ln

    def relegend(self, ax) -> None:
        """改名／移位後重建這個 axes 的圖例（字級跟 compute() 一樣）；本來沒有圖例（或已刪除）就不建。"""
        if ax.get_legend() is None:
            return
        ax.legend(fontsize=8, loc=self.legend_loc)
        self.canvas.draw_idle()

    def rename_line(self, uid: int, label: str) -> None:
        """圖例文字雙擊就地改名（MATLAB 預設 ItemHitFcn 的行為）：只改這條線的標籤，重算時會回到訊號名稱。"""
        ln = self.lines.get(uid)
        if ln is None or not label:
            return
        ln.set_label(label)
        self.relegend(ln.axes)
        self.v_status.set(tr("改名 {name}").format(name=label))

    def copy_figure_clipboard(self, vector: bool = False) -> None:
        """右鍵「複製圖到剪貼簿」＝PNG（MATLAB Copy as image）；vector=True＝PDF（Copy as vector graphic）。"""
        ok, msg = pk.copy_figure_to_clipboard(self.fig, content="vector" if vector else "image")
        self.v_status.set(msg)
        if not ok:
            messagebox.showinfo(tr("複製圖到剪貼簿"), msg, parent=self)

    def context_menu(self, hit, event) -> None:
        g = getattr(event, "guiEvent", None)
        x, y = (g.x_root, g.y_root) if (g is not None and hasattr(g, "x_root")) else self.winfo_pointerxy()
        m = tk.Menu(self, tearoff=0)
        pk.widgets.fill_menu(m, self.ia.legend_menu_items(hit))      # 圖例上：刪除圖例／圖例位置（MATLAB 圖例右鍵選單）
        if hit.kind in ("legend", "legend_box"):                       # 圖例上只有圖例自己的項目（批次 E；MATLAB 圖例右鍵選單）
            while m.index("end") is not None and m.type("end") == "separator":
                m.delete("end")
            pk.menus.popup_menu(m, int(x), int(y))      # 0.9.13 W1：彈出後銷毀（Windows 的選單代號有限）
            return
        top = getattr(self, "_context_top", None)              # 視窗自己的項目放最上面（I/Q 分析視窗：複製／複製全部訊號）
        if top is not None and top(m, hit):
            m.add_separator()
        if hit.kind == "tip":
            m.add_command(label=tr("刪除這個資料提示"), command=lambda tid=hit.id: self.ia.remove_tip(tid))
        if self.ia.model.tips:
            m.add_command(label=tr("清除全部資料提示"), command=self.ia.clear_tips)
        m.add_checkbutton(label=tr("資料提示模式"), variable=self.v_tips, command=self._on_tips_toggle)
        m.add_command(label=tr("還原視圖 (Home)"), command=self.ia.restore_view)
        if hit.ax is not None:
            m.add_command(label=tr("只匯出這個 panel…"), command=lambda ax=hit.ax: self.ia.export_axes_dialog(ax))
        p = (getattr(self, "render_info", None) or {}).get("panel_of_ax", {}).get(id(hit.ax)) if hit.ax is not None else None
        if p is not None and hasattr(self, "delete_panel"):           # 主視窗的 panel：上移／下移／刪除（也可以拖左邊的 ≡ 握把換順序）
            cur = self.panel_order()
            i = cur.index(p) if p in cur else 0
            m.add_separator()
            m.add_command(label=tr("上移 panel"), command=lambda p=p: self.move_panel(p, -1), state="normal" if i > 0 else "disabled")
            m.add_command(label=tr("下移 panel"), command=lambda p=p: self.move_panel(p, 1), state="normal" if i < len(cur) - 1 else "disabled")
            m.add_command(label=tr("刪除這個 panel"), command=lambda p=p: self.delete_panel(p))
        m.add_separator()
        m.add_command(label=tr("複製圖到剪貼簿"), command=self.copy_figure_clipboard)
        m.add_command(label=tr("複製向量圖（PDF）到剪貼簿"), command=lambda: self.copy_figure_clipboard(vector=True),
                      state=pk.clipboard.vector_copy_state())             # Windows：剪貼簿放不了向量圖 → 灰
        pk.menus.popup_menu(m, int(x), int(y))      # 0.9.13 W1：彈出後銷毀（Windows 的選單代號有限）


