    def _act(self, aid: str, label: str, group: str, run: Callable[[], Any], *, enabled: Optional[Callable[[], bool]] = None,
             widgets: Sequence[Any] = (), scope: str = "app") -> None:
        self.actions[aid] = dsv_keys.Action(aid, label, group, run, self.ACTION_DEFAULTS.get(aid, ()), enabled, scope)
        self._action_widgets[aid] = [w for w in widgets if w is not None]

    def _flip(self, var, after: Callable[[], Any]) -> None:
        """勾選型動作的快速鍵：切換變數再跑 Checkbutton 的 command（和按鈕按下去一樣）。"""
        var.set(not bool(var.get()))
        after()

    def _strip_btns(self, text: str) -> List[Any]:
        """工具列上文字＝tr(text) 的按鈕／勾選（給動作掛提示用）。"""
        want = tr(text)
        out: List[Any] = []
        stack = [self.strip]
        while stack:
            w = stack.pop()
            try:
                if w.winfo_class() in ("TButton", "TCheckbutton") and str(w.cget("text")) == want:
                    out.append(w)
                stack.extend(w.winfo_children())
            except Exception:
                pass
        return out

