    check(d["dist_on"] is False and d["dist_type"] == "harmonic" and d["dist_nharm"] == "6" and d["dist_label"] is False
          and dict(DIST_TYPES) == {"harmonic": "諧波", "intermod": "互調"} and DIST_IMOD_LABELS == ("F1", "F2", "2F1 - F2", "2F2 - F1"),
          "失真的預設＝MATLAB DistortionMeasurementsConfiguration（諧波、Num Harmonics 6、不標示）；互調的欄名照 MATLAB")
    nh_in = ("6", "2", "99", "1", "100", "2.5", "abc", "", "NaN", "0.01k", "1e1", "0x10", "12abc", "6abc", "Inf")
