    full_w = text_extent_pt("≡ P1 " + "很長的名稱" * 10 + " [V]", fam_t, 11.0)[0]
    fit_s, shown_s = fit_user_text("≡ P1 ", "很長的名稱" * 10, " [V]", 120.0, fam_t, 11.0)
    check(full_w > 120 and fit_s.startswith("≡ P1 很長") and fit_s.endswith("… [V]") and shown_s.endswith("…")
          and text_extent_pt(fit_s, fam_t, 11.0)[0] <= 120.0,
          f"fit_user_text：放不下就截短名稱加「…」，P 編號、單位留著，量起來放得下（{fit_s}）")
    fit_m, _sm = fit_user_text("", "$\\alpha_{1}$ 很長的數學 $\\beta$ 名稱" * 3, "", 90.0, fam_t, 11.0)
    check(matplotlib.cbook.is_math_text(fit_m) and _mathtext_ok(fit_m) and fit_m.endswith("…"),
          f"fit_user_text：數學式只截在 $…$ 外面（截完還是合法的數學式：{fit_m}）")
    fit_0, sh_0 = fit_user_text("≡ P1 ", "電壓", " [V]", 8.0, fam_t, 11.0)
    check(fit_0 == "≡ P1 [V]" and sh_0 == "", f"fit_user_text：連「…」都放不下（圖非常矮）＝不畫名稱、和 0.9.9 一樣的標籤（{fit_0}）")
    check(fit_user_text("≡ P1 ", "電壓", " [V]", 500.0, fam_t, 11.0) == ("≡ P1 電壓 [V]", "電壓")
          and fit_user_text("", "標題", "", -5.0, fam_t, 11.0) == ("", ""),
          "fit_user_text：放得下＝原樣；可用的長度是 0 或負的（圖窄到扣掉左右的指數字就沒有了）＝不畫名稱")
    # 版面：沒有標題＝和以前一模一樣；有標題時上面留標題的空間（最上面那張放在上留白裡、其他放在上一張的標籤空隙下面）、大標題在最上面
    st_t = pk.get_style("matlab-dark")
    r4 = [1.0, 1.0, COLLAPSED_RATIO, 1.0]
    lab4 = [True, False, True]
    l_plain = panel_layout(8, 6, r4, lab4, st_t)
    l_zero = panel_layout(8, 6, r4, lab4, st_t, tops=[0.0] * 4, fig_top=0.0)
    check(l_plain["rows"] == l_zero["rows"] and l_plain["gaps"] == l_zero["gaps"] and close(l_plain["top"], 0.2),
          "panel_layout：沒有標題（tops 全 0、沒有大標題）＝和以前一模一樣")
    t_rooms = [title_room_in("標題 A", "副標題", st_t), title_room_in("B", "", st_t), 0.0, title_room_in("", "只有副標題", st_t)]
    f_room = figure_title_room_in("整張圖", st_t)
    check(t_rooms[0] > t_rooms[1] > 0 and t_rooms[3] > 0 and f_room > 0 and title_room_in("", "", st_t) == 0.0
          and figure_title_room_in("", st_t) == 0.0,
          f"title_room_in／figure_title_room_in：標題＋副標題比只有標題高；都沒有＝0（{[round(t, 3) for t in t_rooms]}、{f_room:.3f} in）")
    g_lab_t = x_label_room(st_t)
    g_tick_t = x_tick_out_in(st_t)
    u_t = 1.2
    h_t = panel_canvas_height(u_t, r4, lab4, st_t, tops=t_rooms, fig_top=f_room)
    l_t = panel_layout(8, h_t, r4, lab4, st_t, tops=t_rooms, fig_top=f_room)
    h_n = panel_canvas_height(u_t, r4, lab4, st_t)
    exp_gaps = [g_lab_t + t_rooms[1], max(PANEL_HSPACE * u_t * sum(r4) / 4, 0.0), g_lab_t + t_rooms[3]]
    check(close(l_t["u"], u_t, rel=1e-6) and close(l_t["top"], f_room + max(t_rooms[0], 0.2), rel=1e-9)
          and all(close(a, b, rel=1e-6) for a, b in zip(l_t["gaps"], exp_gaps))
          and close(h_t - h_n, f_room + max(t_rooms[0], 0.2) - 0.2 + t_rooms[1] + t_rooms[3], rel=1e-6),
          f"panel_layout／panel_canvas_height（有標題）：互為反函數、每張圖照樣高 {u_t} in；上留白＝大標題＋最上面那張的標題；"
          f"下面有標題的空隙＝x 標籤空隙＋標題（{[round(g, 3) for g in l_t['gaps']]}）；畫布多出來的＝標題的高度")
    lab_un = [False, False, True]
    l_un = panel_layout(8, panel_canvas_height(u_t, r4, lab_un, st_t, tops=t_rooms), r4, lab_un, st_t, tops=t_rooms)
    check(close(l_un["gaps"][0], max(g_tick_t + X_LABEL_CLEAR_PT / 72.0 + t_rooms[1], PANEL_HSPACE * u_t * sum(r4) / 4), rel=1e-6),
          "gap_needs：上面那張沒標 x 軸（收合、退回 0.9.8 的標法）時，下一張的標題只讓開刻度線＋同樣的間距")
    l_fb = panel_layout(8, 5.0, [1.0] * 4, [True] * 3, st_t, mins=[PANEL_MIN_IN] * 4, fallback=[False] * 3,
                        tops=[t_rooms[0]] * 4, fig_top=f_room)
    check(l_fb["fallback"] and not l_fb["squeezed"] and l_fb["labeled"] == [False] * 3 and all(g >= t_rooms[0] - 1e-9 for g in l_fb["gaps"])
          and close(l_fb["top"], f_room + max(t_rooms[0], 0.2)),
          f"panel_layout：匯出的大小放不下每張的 x 標籤 → 退回 0.9.8 的標法，標題的空間照留（不藏標題；空隙 {[round(g, 3) for g in l_fb['gaps']]}）")
    l_sq = panel_layout(8, 2.0, [1.0] * 6, [True] * 5, st_t, tops=[t_rooms[0]] * 6, fig_top=f_room)
    check(l_sq["squeezed"] and all(h > 0 for _y, h in l_sq["rows"]) and l_sq["rows"][-1][0] > 0,
          "panel_layout：連標題都放不下（6 張 8×2 in）＝標籤與標題的空間等比例縮小，圖還在畫布裡（狀態列會提醒加大高度）")
    # render：名稱、標題、大標題畫上去、每段照打的字、單位自動接；量 bbox 不重疊（畫面大小、存成別的大小、退回 0.9.8 的標法）
    sgn = _sigs_x(1300, [(1, "na"), (1, "nb"), (2, "nc"), (3, "nd")])
    sgn[1].yaxis = "right"
    sgn[3].raw = 2.0e6 + 1.5e6 * np.sin(np.arange(600) / 7.0)      # 大數值：y 軸左上角有指數字（1e6），長的副標題要讓開它
    fig_n = Figure(figsize=(8, 7), dpi=100)
    _FCAx(fig_n)
    pn_opts = {1: {"title": "接收端 rx_data", "subtitle": "副標題 $V_{in}$", "xname": "時間", "yname": "電壓", "yunit": "V",
                   "yname_right": "右邊"},
               2: {"title": "很長的標題 " * 30, "yname": "很長的名稱" * 40, "xname": "$\\frac{a}{b}$ ratio"},
               3: {"subtitle": "只有副標題 subtitle " * 12, "yname": "$x^$ 不合法"}}
    info_n = render(fig_n, sgn, {"xunit": "us", "symbol_rate": 1e6, "style": "matlab-dark", "panels": pn_opts,
                                 "figure_title": "整張圖 $E=mc^2$"}, None)
    axn = info_n["axes"]

    def _overlaps_n():
        fig_n.canvas.draw()
        rr_n = fig_n.canvas.get_renderer()
        probs_n = []
        for i_, (p_, a_) in enumerate(zip(info_n["panels"], axn)):
            for k_, t_ in ((info_n.get("title_artists") or {}).get(p_) or {}).items():
                bb_ = t_.get_window_extent(rr_n)
                if bb_.y0 < a_.bbox.y1 - 0.5 or bb_.x0 < -0.5 or bb_.x1 > fig_n.bbox.width + 0.5 or bb_.y1 > fig_n.bbox.height + 0.5:
                    probs_n.append((p_, k_, "位置"))
                if i_ > 0:
                    up_ = axn[i_ - 1]
                    xb_ = up_.xaxis.get_tightbbox(rr_n)
                    lim_ = min(up_.bbox.y0, xb_.y0 if xb_ is not None and xb_.height > 0 else up_.bbox.y0)
                    if bb_.y1 > lim_ + 0.5:
                        probs_n.append((p_, k_, "壓到上一張"))
            for a2_ in (a_, (info_n.get("axes_right") or {}).get(p_)):
                if a2_ is not None and getattr(a2_.yaxis.label, "_dsv_user_shown", None):
                    yb_ = a2_.yaxis.label.get_window_extent(rr_n)
                    if yb_.y0 < a2_.bbox.y0 - 2 or yb_.y1 > a2_.bbox.y1 + 2:
                        probs_n.append((p_, "y 軸名稱超出"))
                ot_ = a2_.yaxis.get_offset_text() if a2_ is not None else None
                if ot_ is not None and ot_.get_visible() and ot_.get_text():
                    ob_ = ot_.get_window_extent(rr_n)
                    for k_, t_ in ((info_n.get("title_artists") or {}).get(p_) or {}).items():
                        if t_.get_window_extent(rr_n).overlaps(ob_):
                            probs_n.append((p_, k_, f"壓到 y 軸的指數字 {ot_.get_text()}"))
        ft_ = info_n.get("figure_title_artist")
        if ft_ is not None and ft_.get_visible():
            fb_ = ft_.get_window_extent(rr_n)
            top_ = max([t_.get_window_extent(rr_n).y1 for t_ in ((info_n.get("title_artists") or {}).get(info_n["panels"][0]) or {}).values()]
                       + [axn[0].bbox.y1])
            if fb_.y0 < top_ - 0.5 or fb_.y1 > fig_n.bbox.height + 0.5:
                probs_n.append(("大標題",))
        return probs_n
    pr_n = _overlaps_n()
    ot3 = axn[2].yaxis.get_offset_text().get_text()
    yl1 = axn[0].get_ylabel()
    check(yl1 == "≡ P1 電壓 [V]" and axn[0].get_xlabel() == "時間 [us]" and info_n["axes_right"][1].get_ylabel() == "右邊"
          and axn[2].get_xlabel() == "x [us]" and axn[1].get_xlabel() == "$\\frac{a}{b}$ ratio [us]"
          and {k: a.get_text() for k, a in info_n["title_artists"][1].items()} == {"title": "接收端 rx_data", "subtitle": "副標題 $V_{in}$"}
          and info_n["figure_title_artist"].get_text() == "整張圖 $E=mc^2$" and "\\$x^\\$ 不合法" in axn[2].get_ylabel(),
          f"render：「≡ P1 電壓 [V]」「時間 [us]」、右軸名稱、標題、副標題、大標題；不合法的數學式照打的字（{yl1}、{axn[2].get_ylabel()}）")
    check(not pr_n and axn[1].get_ylabel().endswith("…") and info_n["title_artists"][2]["title"].get_text().endswith("…")
          and bool(ot3) and info_n["title_artists"][3]["subtitle"].get_text().endswith("…"),
          f"render：畫面上標題不壓到上一張的 x 標籤、不疊、不超出、不壓到 y 軸左上角的指數字（{ot3}）；太長的 y 軸名稱、標題縮短加「…」（{pr_n[:3]}）")
    st_xn = info_n["style"]
    check(close(info_n["title_artists"][1]["title"].get_fontsize(), 10 * float(st_xn["title"]["scale"]))
          and info_n["title_artists"][1]["title"].get_fontweight() in ("bold", 700)
          and info_n["title_artists"][1]["subtitle"].get_fontweight() in ("normal", 400)
          and info_n["figure_title_artist"].get_fontweight() in ("normal", 400)
          and close(info_n["figure_title_artist"].get_fontsize(), 10 * float(st_xn["title"]["scale"])),
          "render：字級照 MATLAB（matlab 風格）：標題 ×1.1 加粗、副標題同字級不加粗、大標題同字級不加粗（sgtitle 的 FontWeight 預設 normal）")
    w0_n, h0_n = fig_n.get_size_inches()
    fig_n.set_size_inches(8, 4)
    fig_n._pk_exporting = True
    try:
        pr_s = _overlaps_n()
        lay_s_ = info_n["layout"].last or {}
        vis_s = all(t_.get_visible() for d_ in info_n["title_artists"].values() for t_ in d_.values()) and info_n["figure_title_artist"].get_visible()
    finally:
        del fig_n._pk_exporting
    fig_n.set_size_inches(w0_n, h0_n)
    pr_b = _overlaps_n()
    check(not pr_s and vis_s and not pr_b and bool(lay_s_),
          f"版面引擎：存成 8×4 in（{'退回 0.9.8 的標法' if lay_s_.get('fallback') else '每張都標'}）標題、大標題照畫、不重疊；回到原大小也一樣（{pr_s[:2]}、{pr_b[:2]}）")
    fig_n._pk_exporting = True
    try:
        for a_ in axn[1:]:
            a_.set_visible(False)
        fig_n.canvas.draw()
        ft_hidden = not info_n["figure_title_artist"].get_visible()
    finally:
        for a_ in axn[1:]:
            a_.set_visible(True)
        del fig_n._pk_exporting
    fig_n.canvas.draw()
    check(ft_hidden and info_n["figure_title_artist"].get_visible(),
          "版面引擎：只匯出某幾張（其他座標區藏起來）時大標題不畫（屬於整張圖；MATLAB exportgraphics(ax) 也不帶）；回到畫面照畫")
    # 很高的 x 軸名稱（$…$ 數學式比 x_label_room 估的一行字高很多；2026-10-27 驗證：x_label_extra_pt 改成 0 時沒有測試擋住）：
    # 每個標籤空隙照最高的那個多留——不壓到下一張的座標區、圖例，下一張的標題不壓到它，最下面那張的不被圖的下緣切掉（存成小圖退回 0.9.8 的標法也一樣）
    tall_x = "$\\frac{\\sum_{i=0}^{N} a_i^{2}}{\\prod_{j=1}^{M} b_j}$ 比"
    st_tx = pk.get_style("matlab-dark")
    ex_tall = x_label_extra_pt(["x [us]", tall_x + " [us]", ""], st_tx)
    check(x_label_extra_pt(["x [us]", "rx_data [ns]"], st_tx) == 0.0 and x_label_extra_pt([], st_tx) == 0.0 and ex_tall > 20.0
          and close(ex_tall, x_label_extra_pt([tall_x + " [us]"], st_tx))
          and close(x_label_room(dict(st_tx, xlabel_extra_pt=ex_tall)) - x_label_room(st_tx), ex_tall / 72.0),
          f"x_label_extra_pt：一行字的 x 軸標籤不多留；很高的數學式照最高的那個多留（{ex_tall:.1f} pt），x_label_room 照加")

    def _tall_x_layout(pn_, base_uid, export=None):
        """畫 3 張（pn_＝panels 的名稱與標題），回傳 (每張 x 軸標籤下緣到下一張的座標區、圖例、標題的距離 px（負的＝壓到）,
        最下面那張標籤的下緣 px, 是否退回 0.9.8 的標法, 多留的 pt)；export＝(寬, 高) 英吋：照「存成圖檔」那次的版面量。"""
        fig_ = Figure(figsize=(8, 7), dpi=100)
        _FCAx(fig_)
        info_ = render(fig_, _sigs_x(base_uid, [(1, "ta"), (2, "tb"), (3, "tc")]),
                       {"xunit": "us", "symbol_rate": 1e6, "style": "matlab-dark", "panels": pn_}, None)
        if export:
            fig_._pk_exporting = True
            fig_.set_size_inches(*export)
        try:
            fig_.canvas.draw()
            rr_ = fig_.canvas.get_renderer()
            axs_ = info_["axes"]
            gaps_ = []
            for i_ in range(len(axs_) - 1):
                if not axs_[i_].xaxis.label.get_visible():
                    continue
                lo_ = axs_[i_].xaxis.get_tightbbox(rr_).y0
                nx_ = axs_[i_ + 1]
                tops_ = [nx_.bbox.y1] + ([nx_.get_legend().get_window_extent(rr_).y1] if nx_.get_legend() is not None else [])
                tops_ += [t_.get_window_extent(rr_).y1 for t_ in ((info_.get("title_artists") or {}).get(info_["panels"][i_ + 1]) or {}).values()
                          if t_.get_visible()]
                gaps_.append(float(lo_ - max(tops_)))
            return (gaps_, float(axs_[-1].xaxis.get_tightbbox(rr_).y0), bool((info_["layout"].last or {}).get("fallback")),
                    float(info_["style"].get("xlabel_extra_pt", 0.0) or 0.0))
        finally:
            if export:
                del fig_._pk_exporting
    g_a, _bt, _fb, ex_a = _tall_x_layout({1: {"xname": tall_x}}, 1400)
    g_b, _bt, _fb, _ex = _tall_x_layout({1: {"xname": tall_x}, 2: {"title": "下一張的標題"}}, 1410)
    g_c, bt_c, _fb, _ex = _tall_x_layout({3: {"xname": tall_x}}, 1420)
    _g, bt_e, fb_e, _ex = _tall_x_layout({3: {"xname": tall_x}}, 1430, export=(8, 3))
    g_0, bt_0, _fb, ex_0 = _tall_x_layout({1: {"xname": "time"}}, 1440)
    check(ex_a > 20.0 and len(g_a) == 2 and min(g_a) >= -0.5 and len(g_b) == 2 and min(g_b) >= -0.5,
          f"render：P1 的 x 軸名稱很高（多留 {ex_a:.1f} pt）時不壓到 P2 的座標區、圖例（{[round(g, 1) for g in g_a]} px），"
          f"P2 有標題時標題不壓到它（{[round(g, 1) for g in g_b]} px）")
    check(min(g_c) >= -0.5 and bt_c >= -0.5 and fb_e and bt_e >= -0.5,
          f"render：最下面那張（P3）的 x 軸名稱很高：標籤的下緣在圖裡（{bt_c:.1f} px）；存成 8×3 in 退回 0.9.8 的標法時也是（{bt_e:.1f} px）")
    check(ex_0 == 0.0 and min(g_0) > 0 and bt_0 >= 0,
          f"render：一行字的名稱（time）不多留（{ex_0} pt），標籤照樣不壓到下一張（{[round(g, 1) for g in g_0]} px）")
    # --- 量測（Signal Statistics＋Bilevel Cycles）、轉態、Normalize Y ----------------------------------------
    ys = np.array([3.0, -1.0, 4.0, 1.0, 5.0, np.nan, 9.0, 2.0, 6.0])
    st_ = signal_stats(ys, x0=10.0, dx=0.5)
    fin_ = ys[np.isfinite(ys)]
    check(st_["samples"] == 8 and st_["max"] == 9.0 and close(st_["max_x"], 13.0) and st_["min"] == -1.0 and close(st_["min_x"], 10.5)
          and st_["p2p"] == 10.0 and close(st_["mean"], float(np.mean(fin_))) and close(st_["var"], float(np.var(fin_, ddof=1)))
          and close(st_["std"], float(np.std(fin_, ddof=1))) and close(st_["median"], float(np.median(fin_)))
          and close(st_["msq"], float(np.mean(fin_ ** 2))) and close(st_["rms"], math.sqrt(float(np.mean(fin_ ** 2)))),
          "signal_stats：Max／Min 含位置（x0+i·dx，NaN 不算）、P2P、Mean、Var／Std（N−1）、Median、RMS、Mean Square 對 numpy")
    check(signal_stats([]) == {"samples": 0} and signal_stats([5.0])["var"] == 0.0, "signal_stats：沒有樣本只回 samples=0；單一樣本 var=0")
    clk_ = np.tile([0, 0, 1, 1, 1, 0, 0, 0], 40).astype(float)        # 週期 8、正脈寬 3、duty 37.5%
    ps_ = pulse_stats(clk_, x0=0.0, dx=0.25)
    sl_ = state_levels(clk_)                       # MATLAB statelevels：100 格直方圖的格中心 → 0/1 資料是 0.005／0.995
    check(close(sl_[0], 0.005) and close(sl_[1], 0.995) and ps_["npos"] == 40 and ps_["nneg"] == 39 and close(ps_["period"], 2.0)
          and close(ps_["freq"], 0.5) and close(ps_["width"], 0.75) and close(ps_["duty"], 37.5),
          f"pulse_stats：數位時脈 +Pulses 40、−Pulses 39、Period 2、Freq 0.5、Width 0.75、Duty 37.5%（{ps_}）")
    rng_ = np.random.default_rng(7)
    big_p = np.where((np.arange(1_000_000) // 100) % 4 == 0, 2.0, 0.0) + rng_.normal(0, 0.08, 1_000_000)
    t0_ = time.time()
    ps_big = pulse_stats(big_p)
    st_big = signal_stats(big_p)
    dt_ = time.time() - t0_
    check(ps_big["npos"] == 2499 and ps_big["nneg"] == 2499 and close(ps_big["period"], 400.0, rel=1e-6) and close(ps_big["width"], 100.0, rel=1e-3)
          and close(ps_big["duty"], 25.0, rel=1e-3) and st_big["samples"] == 1_000_000 and dt_ < 2.0,
          f"pulse_stats：1e6 點含雜訊（σ=4% 振幅）不誤判（頭尾不完整的脈波不算：±Pulses 2499）、週期 400／寬 100／duty 25%；統計＋脈波 {dt_:.2f}s")
    runt = np.array([0, 0, 1, 1, 0, 0, 0.6, 0, 0, 1, 1, 0, 0], dtype=float)   # 0.6 沒到 90%：runt 不算
    ex_, rise_, _lo, _hi = pulse_edges(runt)
    check(ex_.tolist() == [1.5, 3.5, 8.5, 10.5] and rise_.tolist() == [True, False, True, False],
          f"pulse_edges：runt 不算轉態、中間位準交點用線性內插（MATLAB midcross）{ex_.tolist()}")
