    check(close(norm_gain([0.0, -4.0, 2.0, np.nan]), 0.25) and norm_gain(np.zeros(5)) == 1.0, "norm_gain：1/峰值絕對值；全 0 → 1")
    n1 = Signal(key="n1", path="", uid=960, panel=1, label="n1")
